COLLDATA("asabahur","ur",[[11546,"§۱۱۵۸۵ ۔ فاطمہ بنت حمزہ\n(1) بن عبدالمطلب بن ہاشم، ہاشمیہ، ان کی والدہ سلمیٰ بنت عمیس ہیں: ابن سکن کا قول ہے: ان کی کنیت ام الفضل ہے، دارقطنی نے کتاب الاخوۃ میں فرمایا: ان کا نام امیمہ ہے ان سے سعد بن زید کا بیٹا عبد الرحمن پیدا ہوا نبی کریم صلی اللہ علیہ وسلم نے سلمہ بن ابو سلمہ ابن عبد الاسد سے ان کا نکاح کر دیا، ابن ابی عاصم نے ابو فاختہ کے طریق سے بحوالہ جعدہ بن کبیرہ، انہوں نے علی سے روایت کیا ہے، فرماتے ہیں نبی کریم صلی اللہ علیہ وسلم کو موٹے ریشم کا جوڑا ہدیہ دیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: “فاطماؤں کے لیے اسے اوڑھنیاں بنا دو” تو میں نے اسے پھاڑ کر چار اوڑھنیاں بنائیں: ایک سیدہ فاطمہ بنت رسول اللہ صلی اللہ علیہ وسلم کے لیے، ایک سیدہ فاطمہ بنت اسد اور ایک فاطمہ بنت حمزہ کے لیے اوڑھنی بنائی اور چوتھی فاطمہ کا ذکر نہیں کیا۔(2) میں کہتا ہوں: شاید وہ عقیل کی زوجہ ہیں جن کا ذکر آگے آ رہا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۲)، تجرید (۲۹۴/۲)\n(2) الاحاد والمثانی (۱۴۲/۱، ۱۴۳۰)"}],[11547,"§۱۱۵۸۶ ۔ فاطمہ بنت الخطاب\n(1) بن نفیل قرشیہ عدویہ، سیدنا عمر رضی اللہ عنہ کی بہن ہیں، ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ اسلام کے ابتدائی دور میں اپنے شوہر سعید بن زید بن عمرو بن نفیل کے ساتھ اسلام لائیں، دارقطنی نے کتاب الاخوۃ میں روایت کیا ہے کہ ان کا نام امیمہ ہے، فرماتے ہیں: سعید بن زید سے ان کے ہاں عبدالرحمن پیدا ہوئے۔ ابو عمر(2) فرماتے ہیں: سیدنا عمر کے اسلام لانے کے بارے میں ان کی عجیب حدیث ہے۔ میں کہتا ہوں: اسے محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں اور ابونعیم نے اپنے طریق سے اور اسحاق بن عبد اللہ کے طریق سے بحوالہ ابان بن صالح اسے نقل کیا ہے۔ انہوں نے مجاہد سے، انہوں نے ابن عباس سے روایت کیا ہے، فرماتے ہیں: میں نے سیدنا عمر رضی اللہ عنہ سے ان کے اسلام لانے کے بارے میں پوچھا، انہوں نے فرمایا: میں سیدنا حمزہ رضی اللہ عنہ کے اسلام لانے کے تین دن بعد باہر نکلا، تو فلاں بن فلاں مخزومی کو پایا، میں نے اسے کہا: کیا تو نے اپنے آباء و اجداد کے دین کو چھوڑ کر محمد کے دین کو اختیار کر لیا ہے؟ اس نے کہا یہ دین تو اس شخص نے بھی اختیار کر لیا ہے جس کا مجھ سے بڑھ کر تم پر حق ہے۔ فرماتے ہیں: میں نے کہا: کون؟ انہوں نے کہا: تمہاری بہن اور بہنوئی، فرماتے ہیں: میں چلا، اور دروازے کو بند پایا، مجھے ہلکی ہلکی آواز سنائی دی۔ فرماتے ہیں: انہوں نے میرے لیے دروازہ کھولا، میں اندر گیا، اور کہا: یہ مجھے کس چیز کی آواز آ رہی تھی؟ کہنے لگیں: کچھ نہیں، بحث کرتے رہے، یہاں تک کہ میں نے اس کے سر پر مارا، کہنے لگیں: تمہارے نہ چاہتے ہوئے بھی ہم مسلمان ہو چکے ہیں، فرماتے ہیں: جب میں نے خون دیکھا تو مجھے شرم آئی، میں نے کہا: مجھے وہ کتاب دکھاؤ۔۔۔۔۔ پھر طویل قصہ ذکر کیا۔ واقدی نے بحوالہ فاطمہ بنت مسلم اشجعیہ بحوالہ فاطمہ خزاعیہ انہوں نے فاطمہ بنت خطاب سے نقل کیا ہے، کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: “میری امت اس وقت تک بھلائی پر رہے گی جب تک اس کے فاسق (کھلے عام گناہ کرنے والے) علماء میں دنیا کی محبت، جاہل قاریوں اور ظالموں کا ظہور نہیں ہو جاتا۔ جب یہ علامت ظاہر ہو جائے گی تو خدشہ ہے اللہ تعالیٰ انہیں عمومی عذاب میں مبتلا نہ کر دے۔ کنیتوں میں عنقریب آئے گا کہ زبیر فرماتے ہیں: کہ عبدالرحمن اکبر بن سعید بن زید کی والدہ یہ ہیں: ام جمیل بنت خطاب، گویا ان کا نام فاطمہ، لقب امیمہ، اور کنیت ام جمیل ہے، ابن سعد(3) کا قول ہے کہ کتاب النسب میں ہے جن سے سعید بن زید بن عمرو بن نفیل نے نکاح کیا تھا وہ رملہ ہیں، اور وہ ام جمیل بنت خطاب ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۴)، الاستيعاب (۱۸۹۲/۴) تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۸۹۲/۴)\n(3) الطبقات الکبریٰ (۱۹۵/۸)"}],[11548,"§۱۱۵۸۷ ۔ فاطمہ بنت سودہ\n(1) بن ابی نہشل، جہنیہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۶)، تجرید (۲۹۴/۲)"}],[11549,"§۱۱۵۸۸ ۔ فاطمہ بنت شریح الکلابیہ\n(1) ابن بشکوال نے بحوالہ ابی عبیدہ نقل کیا ہے کہ انہوں نے ازواج مطہرات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۲۹۴/۲)"}],[11550,"§۱۱۵۸۹ ۔ فاطمہ بنت شریک\nبن محماء، ان کے والد کے سوانح میں ان کا ذکر ہے۔"],[11551,"§۱۱۵۹۰ ۔ فاطمہ بنت شیبہ\n(1) بن ربیعہ بن عبد شمس عبشمیہ، عقیل بن ابی طالب نے ان سے نکاح کیا، ابن ہشام نے ذکر کیا ہے کہ عقیل حنین کے دن لڑائی کے بعد ان کے پاس آئے، تو انہوں نے کہا: تمہیں کیا غنیمت ملی؟ انہوں نے انہیں سوئی دی۔ اتنے میں نبی کریم صلی اللہ علیہ وسلم کے منادی نے کہا: “(مجاہدین! سن لو!) سوئی اور دھاگہ تک اجتماعی مال غنیمت میں جمع کرا دو!”(2) انہوں نے ان سے سوئی لی اور غنیمت میں رکھ دی۔ واقدی نے سیدہ فاطمہ بنت ولید بن عقبہ کے بارے میں یہ نقل کیا ہے، بعض کا قول ہے: عقیل کی زوجہ کا نام یہ ہے: فاطمہ بنت عقبہ جو ہند کی بہن ہیں، یہ ابن ابی ملیکہ سے منقول ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۷)، تجرید (۲۹۴/۲)\n(2) السیرۃ النبویۃ (۱۰۶/۴)، الطبقات الکبریٰ (۱۷۳/۸)"}],[11552,"§۱۱۵۹۱ ۔ فاطمہ بنت صفوان\n(1) بن امیہ بن محرث بن حمل بن شق بن رقبہ بن مخدج کنانیہ، عمرو بن ابی احیحہ سعید بن العاص کی زوجہ ہیں،(2) ابن اسحاق نے بنو امیہ سے حبشہ کی طرف ہجرت کرنے والوں میں ان کا نام لیا ہے۔ فرماتے ہیں: عمرو بن سعید ان کے ساتھ ان کی زوجہ فاطمہ بنت صفوان کنانیہ نے ہجرت کی اور وہیں وفات پا گئیں، ابن سعد(3) نے ان کا نسب بیان کیا ہے اور فرمایا: مکہ میں ابتدائی دور میں اسلام لائیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۸)، الاستيعاب (۳۵۰۶)، تجرید (۲۹۴/۲)\n(2) السیرۃ النبویۃ (۲۵۶/۱)\n(3) الطبقات الکبریٰ (۱۳۹/۸)"}],[11553,"§۱۱۵۹۲ ۔ فاطمہ بنت الضحاک\n(1) بن سفیان کلابیہ: ابو عمر(2) نے ان کا ذکر کیا ہے اور فرمایا: ابن اسحاق فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے ان سے ان کی بیٹی زینب کی وفات کے بعد نکاح کیا اور جب آیت تخیر نازل ہوئی تو انہیں اختیار دیا، انہوں نے دنیا کو اختیار کیا تو نبی کریم صلی اللہ علیہ وسلم نے انہیں جدا کر دیا، اس کے بعد وہ مینگنیاں چنا کرتی تھیں۔ اور فرماتیں: میں بدبخت ہوں، میں نے دنیا کو اختیار کیا ابو عمر کا قول ہے: یہ ہمارے نزدیک صحیح نہیں، کیونکہ شہاب ابو سلمہ کے حوالے سے اور حضرت عروہ سیدہ عائشہ کے حوالے سے روایت کرتے ہیں: کہ جب نبی کریم صلی اللہ علیہ وسلم نے اپنی ازواج کو اختیار دیا تو ان سے آغاز کیا، میں نے اللہ اور اس کے رسول کو اختیار کیا، فرماتے ہیں اور رسول اللہ صلی اللہ علیہ وسلم کی تمام ازواج نے اسی کی پیروی کی۔(3) حضرت قتادہ اور عکرمہ کا قول ہے: آپ صلی اللہ علیہ وسلم نے جب انہیں اختیار دیا اس وقت آپ صلی اللہ علیہ وسلم کے نکاح میں نو ازواج مطہرات تھیں، جو آپ صلی اللہ علیہ وسلم کی وفات کے وقت زندہ تھیں ایک جماعت کا قول ہے: جو کہتی تھیں میں بد بخت ہوں، انہوں نے پناہ چاہی تھی، اور پناہ مانگنے والی خاتون کے بارے میں بہت زیادہ اختلاف ہے۔ بعض کا قول ہے: ضحاک بن سفیان نے اپنی بیٹی فاطمہ کو آپ صلی اللہ علیہ وسلم کے ہاں نکاح کے لیے پیش کیا اور عرض کیا: کبھی اس کے سر درد نہیں ہوا، آپ نے فرمایا: مجھے اس کی ضرورت نہیں۔ بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے ان سے ۸ھ میں نکاح کیا تھا ابن عبدالبر کا کلام ختم ہوا۔ ان کے کلام کی تشریح کی ضرورت ہے اور بعض مقامات قابل مواخذہ ہیں کہ حدیث ابن شہاب جو انہوں نے ذکر کی، وہ صحیح میں ہے۔ (لیکن اس کے آخر میں ہے: میرے والد جانے لگے۔۔۔۔۔” اور رہا قتادہ کا قول تو اسے نقل کیا ہے۔۔۔۔۔ اور رہا عکرمہ کا قول تو اسے نقل کیا ہے۔۔۔۔ ان کا یہ قول کہ یہ وہی ہیں جو آپ صلی اللہ علیہ وسلم کی وفات کے وقت زندہ تھیں، اس میں تردد ہے، کیونکہ آیت تخیر۔۔۔۔۔۔۔۔۔ اور آپ صلی اللہ علیہ وسلم نے اس کے بعد نکاح کیا۔۔۔۔۔۔۔)(4) اور ان کا قول: کہ جو یہ کہتی تھیں کہ میں بدبخت ہوں وہ پناہ چاہنے والی تھیں، اس قول کو واقدی نے بحوالہ ابن مناح روایت کیا ہے فرماتے ہیں: انہوں نے رسول اللہ صلی اللہ علیہ وسلم سے پناہ چاہی، اور اس سے ابن اسحاق کا قول باطل نہیں ہوتا کہ کلابیہ نے اختیار کیا وہ کہتی تھیں: میں بدبخت ہوں، کیونکہ دونوں واقعات کو جمع کرنا ممکن ہے۔ رہا ان کا قول: کہ پناہ چاہنے والی میں بہت سا اختلاف ہے۔ وہ صحیح ہے، ابن سعد کا قول ہے: کلابیہ کے بارے میں اختلاف ہے، اور ان کے نام کے بارے میں اختلاف ہے: بعض کا قول ہے: فاطمہ بنت ضحاک بن سفیان، بعض نے کہا: عمرہ بنت یزید بن عبید، بعض کا قول ہے: سنا بنت سفیان بن عوف، یہ بھی قول ہے کہ یہ ایک ہیں اور ان کے نام میں اختلاف ہے، بعض نے کہا: تین ہیں، پھر واقدی نے مسنداً بواسطہ ابن ابی ذئب زہری سے نقل کیا، انہوں نے زہری سے نقل کیا ہے: فرماتے ہیں: وہ فاطمہ بنت ضحاک ہیں، آپ صلی اللہ علیہ وسلم ان کے پاس آئے تو انہوں نے آپ صلی اللہ علیہ وسلم سے پناہ مانگی آپ صلی اللہ علیہ وسلم نے انہیں طلاق دے دی وہ مینگنیاں چنا کرتی تھیں اور کہتیں: میں بدبخت ہوں۔ اسی مذکورہ سند سے بحوالہ زہری مسنداً ذکر کیا ہے، انہوں نے عروہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے کلابیہ سے نکاح کیا، جب وہ آپ صلی اللہ علیہ وسلم کے پاس لائی گئیں، آپ ان کے قریب آئے تو کہنے لگیں: میں آپ سے اللہ کی پناہ مانگتی ہوں، آپ صلی اللہ علیہ وسلم نے فرمایا: “تم نے بڑی ہستی کی پناہ مانگی ہے، اپنے گھر والوں کے پاس چلی جاؤ۔”(5) عبدالواحد بن ابی عون کے طریق سے بحوالہ امام مناح مروی ہے، فرماتی ہیں: جس عورت نے پناہ مانگی تھی وہ شدت غم کی وجہ سے اپنی عقل کھو بیٹھی تھی۔ وہ امہات المومنین سے ملنے آتی تو اجازت لیتے وقت کہتی! میں بدبخت آئی ہوں۔ اور بتاتی تھی کہ مجھے دھوکا دیا گیا ہے۔ عمرو بن شعیب کے طریق سے بحوالہ ان کے والد اور وہ اپنے دادا سے روایت کرتے ہیں کہ ان کی رخصتی ہوئی تھی اور جب آپ صلی اللہ علیہ وسلم نے اپنی ازواج کو اختیار دیا تو انہوں نے اپنی قوم کو پسند کیا آپ صلی اللہ علیہ وسلم نے انہیں جدا کر دیا، وہ مینگنیاں چنا کرتی تھیں اور کہتیں: میں بدبخت ہوں۔ بعض کا قول ہے: پناہ مانگنے والی سنا بنت نعمان بن ابی الجون تھیں، ابن سعد نے بحوالہ واقدی اسے مسنداً نقل کیا ہے، انہوں نے محمد بن یعقوب سے، انہوں نے متعب سے، انہوں نے عبدالواحد بن ابی عون سے روایت کیا ہے، بعض کا قول ہے: اسماء بنت نعمان بن ابی الجون، واقدی نے اسے مسنداً نقل کیا ہے بحوالہ عمرو بن صالح، انہوں نے سعید بن عبدالرحمن بن ابزیٰ سے، انہوں نے ہشام بن کلیبی سے، انہوں نے اپنے والد سے، انہوں نے ابو صالح سے، انہوں نے ابن عباس سے روایت کیا ہے۔ ابو اسید ساعدی کے طریق سے صحیح میں مذکور قصہ کی طرح ہے، اس کے آخر میں ہے، وہ کہتی تھیں، مجھے بدبخت کہو دوسرے طریق سے بحوالہ ابو اسید مروی ہے کہ وہ خاتون جنہوں نے پناہ چاہی تھی وہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پا گئیں۔ اور رہا ان کا قول کہ اس میں سے کچھ صحیح نہیں، عجیب ہے، کیونکہ صحیح میں ابو اسید ساعدی کی حدیث سے ان کا قصہ ثابت ہے۔ البتہ صحیح ہونے کی نفی سے مراد کلابیہ کے بارے میں یقینی قول کی نفی ہے۔ رہا ان کا قول کہ ضحاک بن سفیان نے آپ صلی اللہ علیہ وسلم کے ہاں اپنی بیٹی کو پیش کیا تھا، اور عرض کیا: اس کے سر میں درد نہیں ہوا۔ صحیح میں اسے نقل کیا گیا ہے۔ رہا یہ قول، بعض نے کہا ہے: آپ صلی اللہ علیہ وسلم نے ۸ھ میں ان سے نکاح کیا، ظاہر ہے کہ ضمیر کا مرجع سوانح والی شخصیت ہے۔ جس کا تقاضا ہے کہ اس کا متناقض قول پہلے گزر چکا ہے۔ وہ قول یہی ہے کہ آپ صلی اللہ علیہ وسلم نے اپنی صاحبزادی سیدہ زینب رضی اللہ عنہا کی وفات کے بعد ان سے نکاح کیا تھا۔ ابن سعد نے بحوالہ واقدی اسے مسنداً نقل کیا ہے، انہوں نے ابراہیم بن وثیمہ سے، انہوں نے ابی وجزہ سے اسے روایت کیا ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے کلابیہ سے ذی قعدہ ۸ھ میں حمراء الاسد سے واپسی پر نکاح کیا، اسماعیل بن مصعب ہے بحوالہ ان کے قبیلے کے کسی شیخ سے روایت ہے، وہ ۷۰ھ میں وفات پا گئیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۷۹)، الاستيعاب (۵۳۰۷)، تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۸۹۹/۴)\n(3) بخاری (الحدیث ۴۷۸۵، ۴۷۸۶)\n(4) بیاض فی الاصل (اصل مسودہ میں یہ سطر خالی ہیں۔ از مترجم)\n(5) بخاری (الحدیث ۵۲۵۴)، نسائی (الحدیث ۳۴۱۷)"}],[11554,"§۱۱۵۹۳ ۔ فاطمہ بنت ابی طالب\nبعض کا قول ہے: وہ ام ہانی ہیں، کنیتوں میں ان کا ذکر آئے گا۔ ابو نعیم نے ان کا ذکر کیا ہے۔"],[11555,"§۱۱۵۹۴ ۔ فاطمہ بنت عامر\nبن حذیمہ قرشیہ۔ سعید بن عامر جو مشہور صحابی ہیں ان کی بہن ہیں، مغیرہ بن ابو العاص کی زوجہ ہیں جو سیدنا عثمان بن عفان رضی اللہ عنہ کے چچا ہیں، ان سے عائشہ پیدا ہوئیں جن سے مروان نے نکاح کیا۔ جس سے عبدالملک پیدا ہوئے، زبیر بن بکار نے یہ ذکر کیا ہے۔"],[11556,"§۱۱۵۹۵ ۔ فاطمہ بنت عبداللہ\n(1) عثمان بن ابی العاص ثقفی کی والدہ ہیں۔ ابو عمر(2) نے ان کا ذکر کیا ہے، اور فرمایا: جب حضرت آمنہ کے ہاں نبی کریم صلی اللہ علیہ وسلم پیدا ہوئے تو وہ موجود تھیں، اس وقت رات تھی، فرماتی ہیں: گھر کی ہر شے روشن تھی، اور ستارے بہت قریب نظر آ رہے تھے، یہاں تک کہ میں کہہ رہی تھی: “وہ مجھ پر آ گریں گے۔” میں کہتا ہوں: ابو عمر نے اسے مسنداً نقل کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۱) تجرید (۲۹۴/۲)\n(2) الاستيعاب (۱۹۰۰/۴)"}],[11557,"§۱۱۵۹۶ ۔ فاطمہ بنت عقبہ\n(1) بن ربیعہ بن عبد شمس عبشمیہ۔ سیدہ ہند کی جو سیدہ ام معاویہ کی والدہ ہیں، بہن ہیں: ان سے ام محمد بن عجلان نے روایت کی اور وہ ان کی مولاۃ ہیں، یہ ابو عمر کا قول ہے۔ میں کہتا ہوں: ابن مندہ نے اسے ابو بکر بن عیاش کے طریق سے محمد بن عجلان سے بحوالہ ان کی والدہ مسنداً نقل کیا ہے، انہوں نے سیدہ فاطمہ رضی اللہ عنہا سے روایت کیا ہے۔ فرماتی ہیں، میں نے کہا: “یا رسول اللہ صلی اللہ علیہ وسلم! میں چاہتی تھیں دنیا کے تمام گھرانوں میں سے اللہ تعالیٰ آپ کے گھرانے کو ذلیل کرے”۔ (حدیث)(2) فرماتے ہیں: اسے ابن ابی اویس نے بحوالہ اپنے والد، انہوں نے ابن عجلان سے روایت کیا ہے، اور اس میں کچھ اضافہ نقل کیا ہے۔ طبرانی رحمہ اللہ نے یعقوب بن محمد کے طریق سے بحوالہ ابو بکر بن اویس، انہوں نے ابو ایوب سے جو قاسم کے مولیٰ ہیں، انہوں نے ابن عجلان سے، انہوں نے اپنے والد سے، انہوں نے فاطمہ بنت عقبہ سے روایت کی ہے کہ ابو حذیفہ بن عقبہ انہیں اور اپنی بہن کو ساتھ لے گئے ہم نے رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی، جب آپ نے شرائط لگائیں تو ہند آپ سے کہنے لگیں: کیا ان ممنوع باتوں میں سے آپ کو اپنی قوم کی عورتوں میں کسی بات کا علم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:(3) “ان سے بیعت کرو! یہی شرط ہے۔” ابن سعد(4) کا قول ہے: ان سے قرظہ بن عبد عمرو بن نوفل بن عبد مناف نے نکاح کیا، جس سے ولید، ہشام، مسلم، عقبہ، ابی برق، ظفر، آمنہ بنت قرظہ، اور فاختہ پیدا ہوئیں۔ فاختہ سے امیر معاویہ رضی اللہ عنہ نے نکاح کیا، پھر وہ اسلام لائیں اور بیعت کی، پھر ان سے ابو حذیفہ بن عقبہ بن ربیعہ نے نکاح کیا۔ ابن سعد نے صحیح سند سے بحوالہ ابن ابی ملیکہ نقل کیا ہے، فرماتے ہیں: عقیل بن ابو طالب نے فاطمہ بنت عقبہ بن ربیعہ سے نکاح کیا، جب وہ ان کے پاس آئے تو کہتیں: عقبہ بن ربیعہ کہاں (جنت میں یا جہنم) ہے؟ انہوں نے ان سے ایک دن کہا: جب انہیں غصہ دلایا، جب تم جہنم میں جاؤ گی تو تمہاری بائیں طرف ہوگا، دیکھ لینا۔ وہ کہنے لگیں: ہم دونوں ایک گھر میں نہیں رہ سکتے۔ سیدنا عثمان رضی اللہ عنہ کے پاس آئیں، آپ نے ابن عباس اور معاویہ رضی اللہ عنہم کو ان کے ساتھ روانہ کیا، جب یہ دونوں وہاں پہنچے، دیکھا دونوں نے صلح کر لی ہے۔ انہوں نے اسے اختصار کے ساتھ بحوالہ ابن عباس رضی اللہ عنہما موصولاً نقل کیا ہے، اور ان کی سند میں واقدی رحمہ اللہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۲) الاستيعاب (۳۵۰۹) تجرید (۲۹۵/۲)\n(2) مسلم (الحدیث: ۴۴۰۴) ابوداؤد (الحدیث: ۳۵۳۳)\n(3) المعجم الکبیر (۹۰۴/۲۲) مجمع الزوائد (۳۹/۶)\n(4) الطبقات الکبریٰ (۱۷۲/۸)"}],[11558,"§۱۱۵۹۷ ۔ فاطمہ بنت علقمہ\n(1) بن عبداللہ بن ابی قیس، ام معظم العامریہ، اپنے شوہر سلیط بن عمرو کے ساتھ حبشہ کی طرف ہجرت کی، ان کے ہاں سلیط بن سلیط نام پیدا ہوئے، ان کا یہی نام کنیت ابن سعد نے لکھی ہے۔ فرماتے ہیں: ان کی والدہ عاتکہ بنت اسعد بن عامر بن بیاضہ خزاعیہ ہیں، اور فرمایا: مکہ کے ابتدائی دور میں اسلام لائیں اور بیعت کی، ان کے والد کے سوانح میں گزر چکا ہے کہ وہ ام معظم ہیں، یہ ان کی کنیت ہے۔","",{"fn":"(1) تجرید (۲۹۵/۲)"}],[11559,"§۱۱۵۹۸ ۔ فاطمہ بنت عمرو بن حرام\n(1) انصاریہ۔ سیدنا جابر رضی اللہ عنہ کی پھوپھی ہیں، ان کے بھائی عمرو بن حرام کے سوانح میں ان کا نسب گزر چکا ہے، صحیح حدیث میں شعبہ کی روایت میں بحوالہ ابن المنکدر ان کا ذکر ثابت ہے، انہوں نے جابر سے روایت کی ہے، فرماتے ہیں: جب میرے والد قتل کیے گئے، تو میں ان کے چہرے سے مٹی صاف کرنے لگا اور لوگ مجھے منع کرنے لگے، میری پھوپھی فاطمہ بنت عمرو ان پر رونے لگیں۔ (الحدیث) کا یہ طیالسی کی روایت کے الفاظ بحوالہ شعبہ ہیں۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۸۳) الاستيعاب (۳۵۱۰) تجرید (۲۹۵/۲)\n(2) بخاری (الحدیث: ۱۲۴۴) مسلم (الحدیث: ۶۳۰۵)"}],[11560,"§۱۱۵۹۹ ۔ فاطمہ بنت عمرو بن حرم\n(1) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، اور بحوالہ مستغفری نقل کیا ہے کہ وہ فرماتے ہیں: انہیں شرف صحابیت حاصل ہے، ابو موسیٰ نے کہا ہے کہ یہ پہلے والی ہی ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۴)"}],[11561,"§۱۱۶۰۰ ۔ فاطمہ بنت قیس بن خالد\n(1) قرشیہ، فہریہ، ضحاک بن قیس کی بہن ہیں جن کے سوانح میں ان کا نسب گزر چکا ہے، عمر میں ان سے بڑی تھیں۔ ابو عمر(2) کا قول ہے: اولین مہاجرین میں سے تھیں، خوبصورت اور عقلمند تھیں، ابوبکر بن حفص مخزومی کے نکاح میں تھیں، انہوں نے طلاق دے دی، اس کے بعد اسامہ بن زید سے نکاح ہوا۔ میں کہتا ہوں: اس بارے میں صحیح(3) میں ان کی حدیث ہے، جب انہوں نے اپنے شوہر کے وکیل سے نفقہ طلب کیا، تو نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “ام شریک کے ہاں عدت گزارو۔” پھر فرمایا: “ابن ام مکتوم کے ہاں”۔ جب انہیں نکاح کے پیام آئے تو آپ نے اسامہ بن زید(4) کا مشورہ دیا، یہ مشہور قصہ ہے۔ یہ وہی ہیں جنہوں نے جساسہ کا طویل قصہ روایت کیا ہے، وہ اس طویل قصے کی روایت میں منفرد ہیں، جب وہ اپنے بھائی کو ملنے کوفہ آئیں جو امیر کوفہ تھے تو ان سے شعبی رحمہ اللہ نے روایت کی ہے جن میں حدیث جابر وغیرہ میں سے بعض سے میں مطلع ہوا۔ بعض کا قول ہے: وہ ضحاک سے دس برس بڑی ہیں، یہ ابو عمر کا قول ہے، فرماتے ہیں: ان کے گھر اہل شوریٰ جمع ہوئے جب سیدنا عمر رضی اللہ عنہ پر قاتلانہ حملہ ہوا تھا۔ ابن سعد(5) کا قول ہے: ان کی والدہ امیمہ بنت ربیعہ ہیں، جو بنو کنانہ سے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۵) الاستيعاب (۳۵۱۱) تجرید (۲۹۵/۲)\n(2) الاستيعاب (۹۰۱/۴)\n(3) مصنف عبد الرزاق (الحدیث: ۱۲۰۲۱) مستدرک (۵۵/۴) المعجم الکبیر (۹۲۸/۲۴)\n(4) ترمذی (۱۱۸۰)\n(5) الطبقات الکبریٰ (۲۰/۸)"}],[11562,"§۱۱۶۰۱ ۔ فاطمہ بنت قیس\nبعض کا قول ہے: وہ بنت ابی حیش ہیں، اور ابو جیش کا نام قیس ہے۔"],[11563,"§۱۱۶۰۲ ۔ فاطمہ بنت المجلل\n(1) بن عبداللہ بن ابی قیس بن عبدود بن نصر بن مالک بن حسل بن عامر بن لوی قرشیہ عامریہ، ان کی کنیت ام جمیل تھی، اور وہ اسی سے مشہور ہیں۔ ابن اسحاق(2) کا قول ہے: یونس بن بکیر وغیرہ کی روایت میں ہے، حبشہ کی طرف ہجرت کرنے والوں میں ان کا ذکر ہے کہ حاطب بن حارث نے ہجرت کی اور ان کے ساتھ ان کی زوجہ فاطمہ بنت محمل تھیں، ان کے شوہر وہاں وفات پاگئے، وہ اپنے دونوں بیٹوں کو لے کر دونوں کشتی والوں کے ساتھ مدینہ آئیں۔ عبداللہ بن حارث بن محمد بن حاطب نے اپنے والد سے، انہوں نے اپنے دادا سے روایت کی ہے، فرماتے ہیں: جب ہم حبشہ کی سرزمین سے آئے تو میری والدہ مجھے لے کر نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔ حدیث ذکر کی۔(3) جن کا ذکر محمد بن حاطب کے سوانح میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۶) الاستيعاب (۳۵۱۲) تجرید (۲۹۵/۲)\n(2) السیرۃ النبویۃ (۲۵۹/۱) (۶۴)\n(3) المعجم الکبیر (۵۳۵/۱۹) مجمع الزوائد (۴۱۵/۹) معرفۃ الصحابۃ (۶۶/۲)"}],[11564,"§۱۱۶۰۳ ۔ فاطمہ بنت منقذ\n(1) بن عمرو بن خنساء بن مبذول انصاریہ، بنو مازن بن نجار سے تھیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(2) نے بھی ان کا ذکر کیا اور فرمایا: وہ ام ولد تھیں، ان سے داؤد بن ابو داؤد بن عامر بن مالک بن خنساء نے نکاح کیا، جس سے اولاد ہوئی۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۷) الاستيعاب (۳۵۱۳) تجرید (۲۹۵/۲)\n(2) الطبقات الکبریٰ (۲۹۵/۲)"}],[11565,"§۱۱۶۰۴ ۔ فاطمہ بنت الولید\nبن عبد شمس بن ولید بن مغیرہ مخزومیہ، ان کے والد یمامہ میں قتل ہوئے، اور ام حکیم بنت ابو جہل ان کی والدہ ہیں، فاطمہ مذکورہ نے عثمان بن عفان سے نکاح کیا، جس سے سعید اور ولید پیدا ہوئے، بعض کا قول ہے: ان کا نام اسماء ہے۔"],[11566,"§۱۱۶۰۵ ۔ فاطمہ بنت الولید\n(1) بن عقبہ بن ربیعہ بن عبد شمس عبشمیہ، ان کے والد حالت کفر میں بدر میں قتل ہوئے۔ ان کی پھوپھی فاطمہ بنت عقبہ کا ذکر گزر چکا ہے، یہ ہجرت کرنے والی علم و فضل والی تھیں، ان کے چچا ابو حذیفہ بن عقبہ نے سالم سے ان کا نکاح کر دیا جنہیں مولیٰ ابو حذیفہ کہا جاتا تھا، وہ یمامہ میں شہید ہوئے۔ ابو عمر کا قول ہے: اس کے بعد حارث بن ہشام سے نکاح ہوا، یہی ان کا قول ہے جبکہ اس میں تامل ہے۔ جسے ابن الاثیر(2) نے بیان کیا ہے اور اس بات کو درست قرار دیا ہے کہ حارث بن ہشام کی اہلیہ ان کے بعد والی ہیں، واقعی یہی بات ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۸) الاستيعاب (۳۵۱۳) تجرید (۲۹۵/۲)\n(2) اسد الغابۃ (۳۷۲/۵)"}],[11567,"§۱۱۶۰۶ ۔ فاطمہ بنت الولید\n(1) بن مغیرہ بن عبداللہ بن عمرو بن مخزوم قرشیہ مخزومیہ، سیدنا خالد بن ولید کی بہن ہیں۔ ابن سعد(2) کا قول ہے۔ ان کی والدہ حکتمہ (ن ساکن اور ث کے ساتھ) بنت عبداللہ بن عمرو بن کعب کنانیہ ہیں، فتح کے دن اسلام لائیں اور بیعت کی، حارث بن ہشام کی زوجہ اور عبد الرحمن اور ام حکیم کی والدہ ہیں جو حارث کے بیٹے ہیں۔ ابو عمر(3) کا قول ہے، بعض نے کہا کہ سیدنا عمر رضی اللہ عنہ نے حارث کے بعد ان سے نکاح کیا اور اس میں تردد ہے۔ میں کہتا ہوں: ابن مندہ نے ان کے لیے عنوان قائم کیا ہے۔ فاطمہ بنت ولید قرشیہ، اور ان سے حدیث ازار نقل کی ہے، عقیلی نے اسے عبدالسلام بن حرب کے طریق سے، اسحاق بن عبداللہ بن ابو فروہ سے بحوالہ ابراہیم بن عباس بن حارث، انہوں نے ابو بکر بن حارث سے، انہوں نے فاطمہ بنت ولید سے جو ابوبکر کی والدہ ہیں، روایت کیا ہے کہ وہ ریشمی لباس کے جسے پہنتیں اور پھر ازار باندھتی تھیں، لوگوں نے کہا: اس کا کیا فائدہ؟ فرمانے لگیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا کہ انہوں نے بازار کا حکم دیا۔ ابن اثیر(4) کا قول ہے: یہ قول کہ ابوبکر کی والدہ ہیں یعنی ابن عبدالرحمن بن حارث بن ہشام، یہ ان کے والد کی والدہ ہیں، اور ابو بکر کی دادی ہیں، بات یہی ہے۔ ابن عساکر نے کہا ہے کہ فاطمہ بنت ولید بن مغیرہ، خالد کی بہن ہیں، انہیں شرف صحابیت حاصل ہے، اپنے شوہر حارث کے ساتھ شام گئیں ان کے بھائی خالد نے اپنے بعض معاملات میں ان سے مشورہ لیا۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے ایک حدیث روایت کی ہے، ان سے ان کے بیٹے ابوبکر بن عبد الرحمن نے روایت کی ہے پھر وہ حدیث ذکر کی، جس میں ازار باندھنے کا حکم ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۸۸) الاستيعاب (۳۵۱۴) تجرید (۲۹۶/۲)\n(2) الطبقات الکبریٰ (۱۹۰/۸)\n(3) الاستيعاب (۱۹۰۱/۴، ۱۹۰۲)\n(4) اسد الغابۃ (۳۷۳/۵)"}],[11568,"§۱۱۶۰۷ ۔ فاطمہ بنت یعار\nبعض کا قول ہے: وہ سالم مولی ابو حذیفہ کی مولاۃ ہیں۔"],[11569,"§۱۱۶۰۸ ۔ فاطمہ بنت الیمان العبسیہ\n(1) حذیفہ کی بہن ہیں، حذیفہ کے سوانح میں ان کا نسب گزر چکا ہے۔ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی کہ وہ خواتین کے ساتھ آپ صلی اللہ علیہ وسلم کی عیادت کرنے آئیں، ایک لٹکے ہوئے مشکیزے سے پانی قطرہ قطرہ آپ صلی اللہ علیہ وسلم پر گر رہا تھا جو بخار کی شدت کو کم کرنے کے لیے تھا، اس روایت میں ہے: “سب سے زیادہ مصائب انبیاء پر آتے ہیں پھر جو لوگ ان کے قریب ہیں”۔(2) ان سے ان کے بھتیجے ابو عبیدہ بن حذیفہ نے روایت کی، اور نسائی(3) اور ابن سعد نے قوی سند سے ان کی حدیث روایت کی، ہم نے عالی سند سے ابن مندہ کی کتاب معرفہ اور ابن مسعود بن فرات کے جزء میں اسے روایت کیا۔ ابن سعد(4) کا قول ہے: اسلام لائیں اور بیعت کی، منصور نے بحوالہ ربعی بن خراش فرمایا: میں نے مجاہد سے کہا: مجھ سے ربعی نے بحوالہ ایک خاتون، انہوں نے حذیفہ کی بہن سے روایت کیا، ان کی کئی بہنیں تھیں، جنہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا۔ مجاہد رحمہ اللہ کا قول ہے: ان خاتون نے ان کا زمانہ پایا۔ حدیث سونے(5) کے زیورات کی مذمت کے بارے میں ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۰) الاستيعاب (۳۵۱۵) تجرید (۲۹۶/۲)\n(2) اسد الغابۃ (۳۷۴/۵)\n(3) نسائی (الحدیث: ۵۱۵۲، ۵۱۵۳)\n(4) الطبقات الکبریٰ (۲۳۸/۸)\n(5) ابوداؤد (۴۲۳۷) مسند احمد (۳۹۶/۶)"}],[11570,"§۱۱۶۰۹ ۔ فرتنی\n(1) ان دو باندیوں میں سے ایک تھیں جنہیں ابن خطل نے گانا بجانا سکھایا تا کہ وہ نبی کریم صلی اللہ علیہ وسلم اور آپ کے اصحاب کی ہجو کریں، تو یہ ان لوگوں میں سے تھیں جن کا خون فتح مکہ کے روز آپ نے بے کار قرار دیا تھا (کوئی بھی انہیں قتل کر سکتا ہے) یہ اسلام لے آئیں اور گانا بجانا ترک کیا اور دوسری قتل ہوئی، یہ سہیلی کا قول ہے۔","",{"fn":"(1) تجرید (۲۹۶/۲)"}],[11571,"§۱۱۶۱۰ ۔ الفرعۃ بنت مالک الحُدریۃ\nفریعہ میں ان کے حالات آئیں گے۔"],[11572,"§۱۱۶۱۱ ۔ فروہ بنت الحارث العتواریہ\nعقیلہ کی والدہ ہیں، عقیلہ میں ان کا ذکر گزر چکا ہے۔ خطیب کی تحریر سے میں نے اسے ف اور راء ساکن کے ساتھ پڑھا ہے۔"],[11573,"§۱۱۶۱۲ ۔ فُریعہ بنت ابی امامہ\nاسعد بن زرارہ انصاریہ۔ رفاعہ میں ان کے حالات گزر چکے ہیں۔"],[11574,"§۱۱۶۱۳ ۔ فُریعہ بنت الحباب\n(1) ابن رافع بن معاویہ بن عبید بن جراح انصاریہ، بنو ابجر سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۹۳) تجرید (۲۹۶/۲)\n(2) المحبر (۴۲۲)"}],[11575,"§۱۱۶۱۴ ۔ فُریعہ بنت خالد\n(1) ابن حسین بن لوزان انصاریہ، سیدنا حسان بن ثابت رضی اللہ عنہ کی والدہ ہیں، اور انہیں کی طرف منسوب تھے، کہا جاتا: ابن فریعہ نے کہا، انہوں نے اپنے آپ کو اس شعر میں ان کی طرف منسوب کیا: “چادریں ہی چادریں ہو گئیں، جب وہ غالب آ گئے اور بڑے ہو گئے فریعہ کا بیٹا شہر کا امیر بن گیا۔” ابن سعد(2) نے بیعت کرنے والی صحابیات میں فریعہ میں ان کا ذکر کیا ہے۔ بعض کا قول ہے، ان کے والد کا نام عمرو ہے۔","",{"fn":"(1) تجرید (۲۹۶/۲)\n(2) الطبقات الکبریٰ (۲۷۱/۸)"}],[11576,"§۱۱۶۱۵ ۔ فُریعہ بنت زرارہ\nرفاعہ میں گزر چکی ہیں۔"],[11577,"§۱۱۶۱۶ ۔ فُریعہ بنت عمرو\n(1) ابن خنیس بن لوزان جو منذر بن عمرو کی بہن ہیں۔ ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ اور ان کے بھائی کا مشہور صحابہ رضی اللہ عنہم میں شمار ہے۔(2)","",{"fn":"(1) اسد الغابۃ (۷۱۹۵) تجرید (۲۹۶/۲)\n(2) الطبقات الکبریٰ (۲۷۱/۸)"}],[11578,"§۱۱۶۱۷ ۔ فُریعہ بنت عمرو\nابن لوزان سیدنا حسان کی والدہ ہیں، بعض کا قول ہے: بنت خالد، ان کا ذکر گزر چکا ہے۔"],[11579,"§۱۱۶۱۸ ۔ فُریعہ بنت قیس الأنصاریہ\n(1) بنو حجیجی سے ہیں، ابن اسحاق نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۶)"}],[11580,"§۱۱۶۱۹ ۔ فُریعہ بنت مالک بن الدُّخشم\n(1) بنو عوف بن خزرج سے ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۷) تجرید (۲۹۶/۲)\n(2) المحبر (۴۲۴)"}],[11581,"§۱۱۶۲۰ ۔ فُریعہ بنت مالک\n(1) ابن سنان خُدریہ، ابو سعید کی بہن ہیں۔ ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ اکثر کے نزدیک ایک ایسی ہی ہے۔ سنن نسائی(2) میں ان کی حدیث کے سیاق میں فارعہ ہے۔ اور طحاوی رحمہ اللہ میں فرعہ ہے، ان کی والدہ حبیبہ بنت عبداللہ بن ابی ہے۔ ان کی حدیث کا مدار سعد بن اسحاق بن کعب بن عجرہ پر ہے، انہوں نے اپنی پھوپھی زینب بنت کعب بن عجرہ سے روایت کی ہے کہ فریعہ بنت مالک بن سنان جو ابو سعید خدری کی بہن ہیں، انہوں نے انہیں بتایا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور آپ صلی اللہ علیہ وسلم سے پوچھا کہ کیا وہ بنو خدرہ میں اپنے گھر والوں کے پاس لوٹ سکتی ہیں، کیونکہ ان کے شوہر اپنے بھاگے ہوئے غلاموں کو تلاش کرنے نکلے ہیں، جہاں وہ قتل ہو گئے۔۔۔۔ پھر حدیث ذکر کی، اس روایت میں ہے: “اپنے گھر میں ٹھہرو یہاں تک کہ عدت پوری ہو جائے”۔ اس میں یہ بھی ہے کہ سیدنا عثمان رضی اللہ عنہ نے کسی کو بھیج کر مجھ سے اس بارے میں پوچھا، میں نے انہیں بتایا، انہوں نے اسی سے فیصلہ کیا۔(3) امام مالک رحمہ اللہ نے موطا میں اسے سعد بن اسحاق سے روایت کیا ہے اور الیاس بن مالک نے اپنے شیخ زہری سے اسے روایت کیا ہے، ابن مندہ کا قول ہے: ہمیں محمد بن یعقوب نیشاپوری نے بتایا کہ ہم سے محمد بن سلیمان بن حارث نے حدیث بیان کی، وہ فرماتے ہیں کہ ہم سے احمد بن عبد اللہ نساج نے، وہ فرماتے ہیں کہ ہم سے احمد بن سیف بن سعید نے وہ فرماتے ہیں کہ مجھے سے میرے والد نے بحوالہ یونس بن یزید، انہوں نے ابن شہاب سے وہ فرماتے ہیں کہ مجھ سے مالک بن انس نے حدیث بیان کی۔۔۔ پھر اسے ذکر کیا۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۸) الاستيعاب (۳۵۱۷)\n(2) ابوداؤد (الحدیث: ۲۳۰۰)\n(3) ابوداؤد، کتاب الطلاق، باب فی المتوفی عنہا زوجہا تنتقل (۲۳۰۰)"}],[11582,"§۱۱۶۲۱ ۔ فُریعہ بنت مُعوّذ\n(1) ابن عفراء انصاریہ، ربیع کی بہن ہیں، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر(2) کا قول ہے، انہیں شرف صحابیت حاصل ہے۔ ان کی حدیث شادی کے موقع پر ترنم سے اشعار پڑھنے اور دف بجانے کے بارے میں ہے جو اہل بصرہ سے مروی ہے، ابن مندہ کا قول ہے: خالد بن دینار نے ان کی حدیث بحوالہ ان کی والدہ جنہوں نے ان سے روایت کیا نقل کی ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۹) الاستيعاب (۳۵۱۸) تجرید (۲۹۷/۲)\n(2) الاستيعاب (۱۹۰۳/۴)"}],[11583,"§۱۱۶۲۲ ۔ قُریعہ بنت وَهَبْ الزُّہریہ\n(1) نبی کریم صلی اللہ علیہ وسلم نے اپنے ہاتھ سے ان کی طرف اشارہ کیا اور فرمایا: “جو چاہتا ہو کہ رسول اللہ صلی اللہ علیہ وسلم کی خالہ کو دیکھے تو وہ انہیں دیکھ لے۔” ابو موسیٰ(2) نے ذیل میں بحوالہ مستغفری ان کا ذکر کیا ہے اور فرمایا: اس پر اضافہ نہیں کیا۔ میں کہتا ہوں: فاختہ بنت عمرو کے سوانح میں ان کے کچھ حالات گزر چکے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۰) تجرید (۲۹۷/۲)\n(2) اسد الغابۃ (۳۷۵/۵)"}],[11584,"§۱۱۶۲۳ ۔ فُسْحُم\n(1) بنت اوس بن خولی بن عبداللہ بن حارث انصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن حبیب(2) کا قول ہے کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی اور بنو نجی سے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۱) تجرید (۲۹۷/۲)\n(2) المحبر (۴۲۴)"}],[11585,"§۱۱۶۲۴ ۔ فِضَّہ النوبیہ\n(1) سیدہ فاطمہ الزھراء کی باندی ہیں، ابو موسیٰ(2) نے ذیل میں اور ثعلبی رحمہ اللہ نے سورہ ﴿ھل اتی﴾ کی تفسیر میں عبداللہ ابن عبد الوہاب خوارزمی کے طریق سے جو احنف کے چچا زاد ہیں، انہوں نے احمد بن حماد مروزی سے، انہوں نے محبوب بن حمید سے اور ان سے روح بن عبادہ نے سوال کیا، انہوں نے قاسم بن بہرام سے، انہوں نے لیث بن ابو سلیم سے، انہوں نے مجاہد سے، انہوں نے ابن عباس رضی اللہ عنہما سے اللہ تعالیٰ کے اس ارشاد: ﴿وہ نذروں کو پورا کرتے ہیں﴾ (الآیۃ)(3) روایت کیا، فرماتے ہیں: سیدنا حسن اور حسین رضی اللہ عنہما بیمار ہوئے تو ان کے دادا، آپ صلی اللہ علیہ وسلم نے اور اہل عرب نے ان کی عیادت کی، انہوں نے ان کے والد سے کہا: اگر آپ نذر مان لیں؟ انہوں نے فرمایا: اللہ تعالیٰ جب انہیں شفاء دیں گے میں شکرانے کے تین روزے رکھوں گا۔ سیدہ فاطمہ رضی اللہ عنہا نے بھی یہی فرمایا اور ان کی لونڈی جنہیں فضہ تو بید کہا جاتا ہے، یہی فرمایا۔۔۔۔ پھر طویل حدیث ذکر کی۔ ذہبی رحمہ اللہ فرماتے ہیں: “یہ موضوع ہے” اور جو انہوں نے کہا یہ بات بعید نہیں۔ ابن صحر نے اپنے فوائد میں اور ابن بشکوال نے کتاب المستخیشین میں اپنے طریق سے، اس سند سے، حسین بن علاء کے طریق سے، جعفر بن محمد بن علی بن حسین بن علی سے، انہوں نے اپنے والد سے، انہوں نے سیدنا علی رضی اللہ عنہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی صاحبزادی سیدہ فاطمہ رضی اللہ عنہا کو خدمت کے لیے لونڈی دی جس کا نام فضہ نوبیہ تھا، سیدہ فاطمہ رضی اللہ عنہا کسی ایک کام کی اس سے شرط رکھتیں، رسول اللہ صلی اللہ علیہ وسلم نے اسے ایک دعا سکھائی جو دعا وہ کرتی، سیدہ فاطمہ رضی اللہ عنہا نے اس سے فرمایا: کیا تم آٹا گوندھوگی یا روٹی پکاؤ گی؟ اس نے کہا: اے میری مالکن! میں آٹا گوندھوں گی اور ایندھن کے لیے لکڑیاں لاؤں گی، وہ گئی اور لکڑیاں جمع کیں، اس کے ہاتھ میں لکڑیوں کا گٹھا تھا، اس نے اسے اٹھانا چاہا لیکن اٹھا نہ سکی، پھر اس نے ان کلمات کے ذریعہ دعا کی جو رسول اللہ صلی اللہ علیہ وسلم نے اسے سکھائے تھے، وہ یہ ہے: “اے اکیلے اللہ! اس جیسا کوئی نہیں، تو ہر ایک کو موت دے گا اور ہر ایک کو فنا کرے گا، وہ اپنے عرش پر تنہا ہے، اسے اونگھ آتی ہے اور نہ نیند۔” ایک اعرابی آیا گویا وہ ازدشنوءۃ کا تھا، اس نے لکڑیوں کا گٹھا اٹھایا اور سیدہ فاطمہ رضی اللہ عنہا کے دروازہ تک پہنچا دیا۔","",{"fn":"(1) الطبقات الکبریٰ (۲۸۰/۸)\n(2) اسد الغابۃ (۷۲۰۲) تجرید (۲۹۷/۲)\n(3) سورۃ الانسان الآیۃ (۷)"}],[11586,"§۱۱۶۲۵ ۔ فُکیہہ بنت السکن الأنصاریہ\n(1) بنو سواد سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(3) کا قول ہے: محمد بن عمر نے ذکر کیا کہ وہ اسلام لائیں اور بیعت کی، ابن سکن فرماتے ہیں: اسماء بنت یزید بن سکن، ان کی کنیت ام عامر ہے، بعض کا قول ہے: ام عامر کا نام فُکیہہ ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۳) تجرید (۲۹۷/۲)\n(2) المحبر (۴۲۸)\n(3) الطبقات الکبریٰ (۲۹۰/۸)"}],[11587,"§۱۱۶۲۶ ۔ فُکیہہ بنت عبید\n(1) ابن ولیم انصاریہ بنو ٹیم سے ہیں۔ قیس بن سعد بن عبادہ کی والدہ ہیں، جو ان کے والد کے چچا کی پرورش میں تھے، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۷۲۰۴) تجرید (۲۹۷/۲)\n(2) الطبقات الکبریٰ (۲۷۲/۸)"}],[11588,"§۱۱۶۲۷ ۔ فُکیہہ بنت المطلب\n(1) ابن خلدہ بن خلد انصاریہ، بنو زُریق سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۵) تجرید (۲۹۷/۲)\n(2) الطبقات الکبریٰ (۲۸۴/۸)"}],[11589,"§۱۱۶۲۸ ۔ فُکیہہ بنت یزید\nابن سکن، ام عامر، کنیتوں میں ان کا ذکر آئے گا۔"],[11590,"§۱۱۶۲۹ ۔ فُکیہہ بنت یسار\n(1) خطاب بن حارث بن محی کی زوجہ ہیں، ابن اسحاق(2) نے مہاجرات میں سے ابتدائی دور میں اسلام لانے والی صحابیات میں ان کا ذکر ہے، محمد بن عثمان بن ابی شیبہ نے اپنی تاریخ میں اور ابو نعیم نے اپنے طریق سے، زیاد بکائی کی روایت سے بحوالہ ابن اسحاق سے نقل کیا ہے۔ ابن سعد(3) کا قول ہے: اسلام کے ابتدائی دور میں مکہ میں اسلام لائیں اور بیعت کی اور دو ہجرتیں کیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۶) تجرید (۲۹۷/۲)\n(2) السیرۃ النبویۃ (۲۵۹/۱) (۲۶/۴)\n(3) الطبقات الکبریٰ (۱۷۹/۸)"}],[11591,"§۱۱۶۳۰ ۔ فاطمہ بنت الولید\nابن عبد شمس بن ولید بن مغیرہ بن عبداللہ بن عمر بن مخزوم ان کے والد یمامہ میں شہید ہوئے، ان کی والدہ ام حکیم بنت ابی جہل ہیں، ان سے سیدنا عثمان بن عفان رضی اللہ عنہ نے نکاح کیا، جس سے سعید اور ولید پیدا ہوئے۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[11592,"§۱۱۶۳۱ ۔ فَرْوَہ، ظفر النبی صلی اللہ علیہ وسلم\n(1) فرماتی ہیں، مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “جب تم اپنے بستر پر آؤ تو یہ سورت پڑھو(2) کہہ دو، اے کافرو!(3) کیونکہ یہ شرک سے برأت ہے۔” ابو احمد عسکری  نے ان کا ذکر کیا ہے۔ اسی طرح ابن اثیر  نے اپنے استدراک میں ان کا ذکر کیا ہے اور ذہبی رحمہ اللہ  نے بھی اسے برقرار رکھا ہے، جو خطا ہے جو تحریف سے پیدا ہوئی۔ انہوں نے جو کہا وہ بغیر تاویل و تانیث کے ہے، یہ حدیث فروہ بن نوفل کے لیے معروف ہے جو تابعین میں سے ایک شخص ہے، کسی راوی نے ابن اسحاق سے نقل کرنے میں غلطی کی ہے۔ فروہ بن نوفل، میں نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور کہا: صحیح وہی ہے جو اس کے علاوہ نے روایت کی، فرماتے ہیں: بحوالہ ابی اسحاق، انہوں نے فروہ بن نوفل دیلمی سے، انہوں نے اپنے والد سے روایت کیا، پھر اسے ذکر کیا، میں نے اسے حرف فاء کی قسم رابع میں بیان کر دیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۱۹۱) تجرید (۲۹۶/۲)\n(2) ابوداؤد (الحدیث: ۵۰۵۰) ترمذی (۲۴۰۲) مستدرک (۵۳۸/۲)\n(3) اسد الغابۃ (۳۷۴/۵)"}],[11593,"§۱۱۶۳۲ ۔ قُریعہ ام ابراہیم\n(1) بنت عبیط(2)، انہیں شرف صحابیت حاصل ہے۔ ابن اثیر نے استیعاب کے حاشیے میں اسے ذکر کیا ہے۔ اسی طرح تجرید میں ہے۔ اور اس کا استدراک وہم ہے۔ ابو عمر نے فارعہ میں ذکر کیا ہے۔ بنت ابی امامہ اسعد بن زرارہ، نبی کریم صلی اللہ علیہ وسلم نے نبیط بن جابر سے ان کا نکاح کر دیا، میں نے فارعہ کے سوانح میں ایک روایت ذکر کی ہے جس میں ان کا نام کسی نے فریعہ بتایا ہے۔ یہاں ذہبی کے بجائے ابن الاثیر پر زیادہ اعتراض ہوتا ہے۔ واللہ التوفیق!","",{"fn":"(1) تجرید (۲۹۶/۲)\n(2) تجرید (۱۹۵)"}],[11594,"§۱۱۶۳۳ ۔ قبیسہ بنت صَیفی\nابن صحر بن خنساء، بشر بن البراء بن معرور کی زوجہ ہیں، تجرید میں بھی ان کا ذکر ہے، حرف زاء میں زینب بنت صیفی کے سوانح میں گزر چکے ہیں، شاید وہ ان کی بہن ہیں۔"],[11595,"§۱۱۶۳۴ ۔ قُتیلہ\n(1) بعض کا قول ہے: تصغیر کے ساتھ، بنت عبد العزیٰ بن سعد بن نصر بن مالک بن حسل بن عامر بن لوی قرشیہ، عامریہ، اسماء بنت ابو بکر اور ان کے سگے بھائی عبداللہ کی والدہ ہیں۔ زبیر وغیرہ نے بھی ان کا نسب بیان کیا ہے۔ ابو موسیٰ نے ذیل میں فرمایا: قتیلہ بنت سعد بن عامر بن لوی، اسی طرح نسب کو مختصر کیا ہے اور اس میں سے ایک جماعت کو حذف کر دیا ہے، پھر فرمایا: مستغفری نے صحابیات میں ان کا ذکر کیا اور فرمایا: بعد میں اسلام لائیں، حاکم، ابو احمد نے کنیتوں میں ان کا نام لیا ہے۔ ان کی حدیث بحوالہ ہشام بن عروہ مروی ہے، انہوں نے اپنے والد سے، انہوں نے اسماء بنت ابو بکر صدیق سے روایت کی، فرماتی ہیں: میری والدہ میرے پاس آئیں اور قریش کے ساتھ معاہدہ کی مدت میں مشرکہ تھیں، میں نے رسول اللہ صلی اللہ علیہ وسلم سے ان سے صلہ رحمی کی اجازت طلب کی۔۔۔۔ (الحدیث)(2) علم یہ صحیح میں ہے، اور اس کے بعض طرق میں ہے، وہ صلہ رحمی کی رغبت رکھتی تھیں، ابو موسیٰ کا قول ہے، روایات میں ان کے اسلام کا ذکر نہیں، اور ان کے قول کہ وہ رغبت رکھتی تھیں، اس سے اسلام نہیں صلہ رحمی مراد ہے، اگر وہ مسلمان ہوتیں تو سیدہ اسماء رضی اللہ عنہا کو ان کے بارے میں صلہ رحمی کی اجازت طلب کرنے کی ضرورت نہ تھی، یہ ہو سکتا ہے کہ وہ اس کے بعد اسلام لائی ہوں۔ میں کہتا ہوں: اگر وہ فتح کے موقع تک زندہ تھیں تو ظاہر ہے کہ وہ اسلام لائیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۷) تجرید (۲۹۷/۲)\n(2) بخاری (الحدیث: ۲۶۲۰) مسند احمد (۳۴۷/۶) (۳۵۵) المعجم الکبیر (۲۰۳/۲۴)"}],[11596,"§۱۱۶۳۵ ۔ قُتیلہ بنت صیفی الجہنیہ\n(1) بعض کا قول ہے: انصاریہ۔ ابو عمر(2) کا قول ہے، اولین مہاجرات میں سے تھیں، ان سے عبداللہ بن یسار نے روایت کی، میں نے ان کے نسب میں انصاریہ نہیں پایا، اور ان کے اس قول کہ وہ مہاجرات میں سے ہیں، اس کی تردید کرتا ہے۔ ابن سعد(3) نے ان کی حدیث نقل کی ہے اور اس طرف اشارہ کیا ہے کہ ان کی اس کے علاوہ کوئی حدیث نہیں۔ اور طبرانی(4) نے مشعر کے طریق سے بحوالہ سعید بن خالد جدلی، انہوں نے عبداللہ بن سیار سے، انہوں نے قتیلہ سے روایت کی جو جہینہ کی ایک خاتون ہیں، فرماتی ہیں، ایک یہودی آیا اور ابن سعد کی روایت میں ہے، یہودی علماء میں سے ایک عالم نبی کریم صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: تم لوگ شرک کرتے ہو، کہتے ہو جو کچھ اللہ چاہے اور تو چاہے، اور تم کہتے ہو: کعبہ کے رب کی قسم۔ تو نبی کریم صلی اللہ علیہ وسلم نے انہیں حکم دیا کہ وہ کہیں: “جو کچھ اللہ چاہے پھر آپ چاہیں”۔(5) نسائی نے اسے نقل کیا ہے اور اس کی سند صحیح ہے، ابن مندہ نے اسے مسعودی کے طریق سے بحوالہ سعید، انہوں نے ابن سیار سے، انہوں نے قتیلہ بنت صیفی جہنیہ سے اسے روایت کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۰۸) تجرید (۲۹۷/۲)\n(2) الاستيعاب (۱۹۰۳/۴)\n(3) المعجم الکبیر (۵۱۲۵) الحدیث (۷۰۶/۲۵)\n(4) مسند احمد (۳۷۱/۶) (۳۷۲/۶)\n(5) اسد الغابۃ (۷۲۰۹) تجرید (۲۹۸/۲)"}],[11597,"§۱۱۶۳۶ ۔ قُتیلہ بنت العرباض\n(1) بنو مالک بن حسل سے ہیں، ان کا ذکر ہے، ابن مندہ نے ان کے مختصر سوانح ذکر کیے ہیں اور ابو نعیم نے ان کی پیروی کی ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۰) تجرید (۲۹۸/۲)"}],[11598,"§۱۱۶۳۷ ۔ قُتیلہ بنت عمرو\n(1) ابن ہلال کنانیہ، حجۃ الوداع میں نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، یہ ابن حبیب اور ابن سعد(2) کا قول ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۲۱۸/۸)\n(2) اسد الغابۃ (۷۲۱۲) الاستيعاب (۳۵۲۱) تجرید (۲۹۸/۲)"}],[11599,"§۱۱۶۳۸ ۔ قُتیلہ بنت النضر\nابن حارث بن علقمہ بن کلدہ بن عبد مناف بن عبد الدار بن قصی قرشیہ، عبداللہ بن حارث بن امیہ اصغر کی زوجہ تھیں۔ علی ابن عبداللہ اور ان کے بہن بھائیوں، ولید، محمد، اور ام حکم کی والدہ ہیں، ابو عمر کا قول ہے، واقدی فرماتے ہیں: یہ وہی ہیں جب ان کے والد نضر بن حارث کو بدر کے دن آپ صلی اللہ علیہ وسلم کے حکم پر قتل کر دیا گیا تو آپ صلی اللہ علیہ وسلم کے بارے میں اشعار کہے: “اے سوار! جھاؤ کا درخت پانچویں روز کی صبح تیرا مقام ہوگا اور تجھے توفیق دی جائے گی، اس صبح ایک میت کو یہ سلام پہنچا دینا کیونکہ ہمیشہ سلام شرفاء کے گلے کا ہار رہے ہیں، وہ سلام میری طرف سے اور ساتھ جھڑتے ہوئے آنسو جو اس کے پونچھنے والے کے لیے بہہ پڑے، اور دوسروں کا دم گھٹ رہا ہے، اگر میں نفر کو پکاروں، کیا وہ واقعی میری بات سن لے گا، کبھی نہیں۔ بھلا مردہ شخص جو بولتا نہیں وہ کیسے سن سکتا ہے، اس کے بھائیوں کی تلوار میں اسے نوچنے لگیں، اللہ کے لیے ان رشتہ داریوں کا خیال کرو جو آپس میں بٹی ہوئی ہیں، ایک شیر کو زبردستی موت کی جانب لے جایا جا رہا ہے وہ بیڑیوں میں جکڑا ہوا ہے وہ مشقت میں ہے۔ اے محمد صلی اللہ علیہ وسلم! آپ کی والدہ اپنی قوم کی انتہائی شریف خاتون تھیں اور ان کے خاوند خاندانی شریف آدمی تھے۔ آپ اگر احسان کر دیتے تو آپ کا کیا جاتا تھا، کئی دفعہ سخت دشمن اور کینہ ور نوجوان بھی احسان کر دیتا ہے۔ اگر آپ قرابت و رشتہ داری کی وجہ سے چھوڑ دیتے تو مدد قریب تھی، بلکہ وہ حقدار تھے اگر گردن چھوڑ دی جاتی۔(1) جب رسول اللہ صلی اللہ علیہ وسلم کو یہ اشعار پہنچے تو آپ صلی اللہ علیہ وسلم روئے یہاں تک کہ آپ صلی اللہ علیہ وسلم کی ریش مبارک تر ہو گئی اور فرمایا: “اگر ان کے قتل ہونے سے پہلے مجھے یہ اشعار پہنچتے تو میں اسے قتل کرنے کا حکم نہ دیتا۔” ابو عمر کا قول ہے: یہ عبداللہ بن ادریس کے الفاظ ہیں اور زبیر بن بکار کی روایت میں ہے، نبی کریم صلی اللہ علیہ وسلم پر رقت طاری ہو گئی یہاں تک کہ آپ صلی اللہ علیہ وسلم کی آنکھوں سے آنسو بہنے لگے، آپ صلی اللہ علیہ وسلم نے ابو بکر رضی اللہ عنہ سے فرمایا: “اے ابو بکر! اگر میں اس کے اشعار پہلے سن لیتا تو اس کے والد کے قتل کا حکم نہ دیتا۔” زبیر فرماتے ہیں: میں نے بعض اہل علم سے سنا ہے کہ وہ اشارہ بتاتے ہیں کہ یہ اشعار مصنوعی ہیں۔ میں کہتا ہوں: مجھے ان کے اسلام لانے کے بارے میں کوئی واضح روایت نہیں ملی۔ لیکن اگر وہ فتح کے موقع پر زندہ تھیں تو وہ صحابیات میں سے ہیں، میں نے جاحظ کی کتاب البیان کے آخر میں لکھا پایا ہے کہ ان کا نام “لیلیٰ” ہے، اور فرمایا کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کی چادر مبارک کھینچی، اس وقت آپ صلی اللہ علیہ وسلم طواف فرما رہے تھے۔ پھر یہ مذکورہ اشعار پڑھے۔","",{"fn":"(1) اسد الغابۃ (۳۸۰/۵) البیان والتبیین (۴۳/۴، ۴۴) نسب قریش عصب الزبیری (۲۵۵)"}],[11600,"§۱۱۶۳۹ ۔ قُرصافہ بنت الحارث\nابن عوف، بعض کا قول ہے: یہ بڑصاء کا نام ہے اور ان کی حدیث ان کے والد کے سوانح میں ہے۔"],[11601,"§۱۱۶۴۰ ۔ قُرَّۃ العین بنت عبادہ\n(1) بن فضلہ بن مالک بن عجلان انصاریہ، بنو عوف بن خزرج سے ہیں، سیدنا عبادہ بن صامت کی والدہ ہیں۔ ابن اثیر(2) نے ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۳) تجرید (۲۹۸/۲)\n(2) اسد الغابۃ (۳۸۰/۵)"}],[11602,"§۱۱۶۴۱ ۔ قُریبہ\n(1) بعض کا قول ہے: تصغیر کے ساتھ۔ بنت ابی امیہ المغیرہ مخزومیہ، سیدہ ام سلمہ رضی اللہ عنہا کی بہن ہیں، ان کے بھائی عبداللہ کے سوانح میں ان کا نسب گزر چکا ہے، سیدہ ام سلمہ رضی اللہ عنہا یوں فرماتی ہیں: جب میرے ہاں زینب کی ولادت ہوئی تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور مجھے نکاح کا پیغام دیا، پھر انہوں نے اپنے نکاح کا قصہ ذکر کیا، اور آپ صلی اللہ علیہ وسلم کے ان کے پاس آنے اور ان کے زینب بنت ام سلمہ کو دودھ پلانے کا قصہ بیان کیا، یہاں تک کہ آپ صلی اللہ علیہ وسلم ایک دن تشریف لائے اور انہیں نہیں پایا تو پوچھا: “زینب کہاں ہے؟” قریبہ ابھی بولی ہی تھیں کہ خادمہ نے بھی ان کا ساتھ دیتے ہوئے کہا کہ عمار بن یاسر (جو سیدہ ام سلمہ رضی اللہ عنہا کے رضاعی بھائی بنتے تھے) لے گئے ہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: “آج شب تمہارے ہاں آؤں گا۔”(2) پھر سیدہ ام سلمہ رضی اللہ عنہا کے ہاں تشریف لائے۔ بلاذری کا قول ہے ان سے معاویہ بن ابی سفیان نے اسلام لانے کے بعد نکاح کیا۔ ابن سعد(3) کا قول ہے: یہ قریبہ صغریٰ ہیں، ان کی والدہ عاتکہ بنت عقبہ بن ربیعہ ہیں، فرماتے ہیں: ان سے عبدالرحمن ابن ابو بکر نے نکاح کیا، جس سے عبداللہ، ام حکیم اور حفصہ پیدا ہوئیں۔ پھر اس روایت کی صحیح سند کو ابن ابی ملیکہ تک لے گئے ہیں، فرماتے ہیں: عبدالرحمن نے قریبہ سے جو ام سلمہ کی بہن ہیں، نکاح کیا، ان کے مزاج میں تیزی تھی، وہ ان سے ایک دن کہنے لگیں: اللہ کی قسم! مجھے آپ سے ڈر لگتا ہے۔ انہوں نے کہا: تمہارا معاملہ تمہارے اختیار میں ہے، کہنے لگیں: میں صدیق کے بیٹے کو چھوڑ کر کسی اور کو اختیار نہیں کروں گا، اور ان کے پاس رہیں۔ میں کہتا ہوں: صاحب جمال تھیں، عمر بن فتہ نے کتاب مکہ میں بحوالہ یعقوب بن قاسم طلحی، انہوں نے یحیی بن عبداللہ ابن ابی حارث زمعی سے نقل کیا ہے، فرماتے ہیں: جب مکہ فتح ہوا، نبی کریم صلی اللہ علیہ وسلم نے سعد بن عبادہ رضی اللہ عنہ سے فرمایا: جب انہوں نے کہا کہ ہم نے قریش کی عورتیں اتنی خوبصورتی پائی نہیں جتنا ان کے حسن و جمال کا چرچا تھا۔ تو آپ صلی اللہ علیہ وسلم نے یہ ارشاد فرمایا تھا: “کیا تم نے ابو امیہ بن مغیرہ کی بیٹیوں کو دیکھا ہے؟ کیا تم نے قریبہ کو دیکھا ہے؟” (الحدیث)","",{"fn":"(1) اسد الغابۃ (۷۲۱۴) تجرید (۲۹۸/۲)\n(2) مصنف عبد الرزاق (۱۰۶۴۴)\n(3) الطبقات الکبریٰ (۶۶/۸)"}],[11603,"§۱۱۶۴۲ ۔ قُریبہ بنت زید\n(1) ابن عبدربہ انصاریہ، بنو شم سے ہیں۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(3) کا قول ہے، عبداللہ بن زید کی بہن ہیں جنہیں اذان کا خواب دکھائی دیا تھا۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۶) تجرید (۲۹۸/۲)\n(2) المحبر (۴۲۱)\n(3) الطبقات الکبریٰ (۲۶۵/۸)"}],[11604,"§۱۱۶۴۳ ۔ قُریبہ بنت ابی سفیان\nابن حرب امویہ، سیدنا معاویہ رضی اللہ عنہ کی بہن ہیں۔ صاحب تاریخ مظفری نے ان کا ذکر کیا ہے۔ فرمایا: انہیں اہل بدر میں سے چودہ مردوں نے نکاح کا پیغام دیا، انہوں نے انکار کر دیا اور عقیل بن ابی طالب سے نکاح کیا، فرماتی ہیں: وہ بدر کے دن ان کے محبوب لوگوں کے ساتھ تھے، یعنی ان کے والد ان کے بھائی حنظلہ، دادا عتبہ، ان کے بھائی شیبہ، اور جو بدر کے معرکہ میں مشرکین کا ساتھ دے رہے تھے۔"],[11605,"§۱۱۶۴۴ ۔ قُریبہ بنت ابی قحافہ\n(1) سیدنا صدیق اکبر رضی اللہ عنہ کی بہن ہیں۔ ابن سعد نے ان کا ذکر کیا ہے، قیس بن سعد بن عبادہ نے ان سے نکاح کیا، اولاد نہ ہوئی، سیدہ ام فروہ کی سگی بہن ہیں۔","",{"fn":"(1) تجرید (۲۹۸/۲)"}],[11606,"§۱۱۶۴۵ ۔ قُریرہ بنت الحارث العُتواریہ\n(1) حرف عین میں ان کی بیٹی عقیلہ عتواریہ کے سوانح میں ان کا ذکر گزر چکا ہے۔(2)","",{"fn":"(1) الطبقات الکبریٰ (۱۸۱/۸)\n(2) الطبقات الکبریٰ (۷۲/۷) تجرید (۲۹۸/۲)"}],[11607,"§۱۱۶۴۶ ۔ قُسرہ بنت رؤاس الکندیہ\n(1) ابو نعیم نے ان کا ذکر کیا ہے، اور عبدالرحمن بن عمرو بن جبلہ کے طریق سے جو ایک متروک راوی ہیں نقل کیا ہے، فرماتے ہیں: ہم سے میسرہ بنت طفیل طائیہ نے بحوالہ ثعلبہ بنت عبداللہ، انہوں نے قسرہ کندیہ سے روایت کیا ہے۔ فرماتی ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: “اے قسرہ! گناہوں کے وقت اللہ کا ذکر کرو، وہ تمہیں مغفرت کے وقت یاد رکھے گا، اپنے خاوند کی اطاعت کرو، وہ دنیا اور آخرت کے شر سے تمہیں کافی ہوگی، اپنے والدین سے اچھا سلوک رکھو تمہارے گھر کی خیر و برکت بڑھے گی”۔(2) ابو عمر(3) کا قول ہے: قرہ، بعض نے زبر اور سین سے لکھا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۸) الاستيعاب (۳۵۲۲) تجرید (۲۹۸/۲)\n(2) جامع المسانید والسنن (۶۷/۱۶)\n(3) الاستيعاب (۱۹۰۶/۴)"}],[11608,"§۱۱۶۴۷ ۔ القُصواء\n(1) قاسم بن غنام کی دادی ہیں۔ مسند ابن سنجر میں ان کی حدیث ہے، اسی طرح تجرید میں ہے۔","",{"fn":"(1) تجرید (۲۹۸/۲)"}],[11609,"§۱۱۶۴۸ ۔ قُفیرہ\n(1) ہلالیہ، بعض کا قول ہے: ملیکہ، ابو علی غسانی نے الاستيعاب کے ذیل میں فرمایا: مسلم نے وحدان میں ان کا ذکر کیا ہے۔ اور فرمایا: عبد اللہ بن ابی حدرد کی زوجہ ہیں، ان سے اعرج کے علاوہ کسی نے روایت نہیں کیا۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۹) الاستيعاب (۳۵۲۳) تجرید (۲۹۸/۲)"}],[11610,"§۱۱۶۴۹ ۔ قُہطم بنت علقمہ\n(1) ابن عبد اللہ بن ابی قیس، سلیط بن عمرو کی زوجہ ہیں۔ ابن اسحاق(2) نے ذکر کیا ہے کہ انہوں نے اور ان کے شوہر نے حبشہ کی طرف ہجرت کی، پھر کشتی والوں کے ساتھ مدینہ کی طرف لوٹ آئے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۰) تجرید (۲۹۸/۲)\n(2) السیرۃ النبویۃ (۲۶۰/۱)"}],[11611,"§۱۱۶۵۰ ۔ قَیلہ بنت مخرمہ التمیمیہ\n(1) پھر بنو عنبر سے ہیں، جنہوں نے انہیں غنویہ کہا، ان سے لفظی غلطی ہوتی ہے۔ حریث بن حسان کے ساتھ نبی کریم صلی اللہ علیہ وسلم کی طرف ہجرت کی، جو بنو بکر بن وائل کے سفیر ہیں، ان کی حدیث عبداللہ بن حسان عنبری نے اپنی دونوں دادیوں صفیہ اور ذھیبہ سے جو علیہ کی بیٹیاں ہیں، روایت کی، وہ دونوں قبیلہ کی پرورش میں تھیں، اور قبیلہ ان کے والد کی دادی تھیں، وہ فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، پھر طویل حدیث ذکر کی، طبرانی(2) نے یہ طویل حدیث بیان کی۔ امام بخاری رحمہ اللہ نے “الادب المفرد” میں اس میں سے کچھ حصہ اور ابوداؤد(3) نے بھی ایک حصہ نقل کیا، اور ترمذی(4) نے مرفوع روایت کے شروع سے “یتعاونان” تک ذکر کی ہے، فرماتے ہیں: پھر طویل حدیث ذکر کی، اور فرمایا: ہم اسے عبداللہ بن حسان کی حدیث سے جانتے ہیں۔ ابو عمر(5) کا قول ہے، وہ طویل، فصیح اور حسن حدیث ہے، اور علم غریب الحدیث والوں نے اس کی اور شرح کی ہے۔ ابوعلی بن سکن فرماتے ہیں: ان سے طویل حدیث مروی ہے، اس میں فصیح کلام ہے، اور اس طریق سے اسے روایت کیا ہے، بحوالہ عبداللہ بن حسان، اسے مختصر بیان کیا اور فرمایا کہ اسے عبداللہ بن حسان کے علاوہ کسی نے روایت نہیں کیا، فرماتے ہیں: اس میں ہے: “قیلہ کی والدہ صفیہ بنت صیفی ہیں، جو اکثم بن صیفی کی بہن ہیں”۔ میں کہتا ہوں: طبرانی نے اور ابن مندہ نے اسے طویل نقل کیا ہے۔ یہ ابن مندہ کے تین طرق سے الفاظ ہیں، بحوالہ عبداللہ بن حسان، اس سند کے ساتھ کہ انہوں نے ان دونوں کو بتایا کہ وہ حبیب بن ازھر کی زوجہ تھیں جو بنو جناب کے ایک مرد ہیں، ان سے لڑکیاں پیدا ہوئیں، بعد میں حبیب کا انتقال ہو گیا تو بچیوں کے چاچا اثوب بن ازھر نے بھابھی سے بھتیجیاں چھین لیں۔ ان کی قوم نئی نئی مسلمان ہوئی تھی، وہ رسول اللہ صلی اللہ علیہ وسلم سے شرف صحابیت حاصل کرنا چاہتی تھیں تو اپنے گھر سے نکل پڑیں ان کی سب سے چھوٹی بیٹی رونے لگیں جس کا نام حدیباء تھا اس نے اونی لباس پہن رکھا تھا، موقعہ کو غنیمت جانا اور اسے ساتھ سوار کر لیا، اسی اثناء میں کہ وہ دونوں اونٹ کو ہلکی چال سے لے جارہی تھیں کہ اچانک ایک خرگوش سامنے آ گیا، حدیباء کہنے لگیں: “خیر سے محرومی شر سے رہائی”۔ اللہ کی قسم! اس بارے میں ہمیشہ تیری شان اثوب سے بلند رہے گی۔ پھر جب لومڑی سامنے آئی تو اس کا کوئی اور نام لیا اور اس کے متعلق بھی وہی بات کہی جو خرگوش کی بابت کی تھی۔ وہ دونوں دھیرے دھیرے اونٹ چلاتی جا رہی تھیں کہ یکا یک اونٹ بیٹھ گیا اور کانپنے لگا۔ حدیباء بولی: لگتا ہے آپ کو اور امانت تک اثوب کی پہنچ ہو جائے گی۔ فرماتی ہیں: میں نے اس سے عاجزانہ کہا: بتاؤ میں کیا کروں؟ وہ کہنے لگی: اپنے کپڑے الٹے پہنو اور اپنی پیٹھ کو پیٹ کی جانب لڑھکا لو۔ اپنے اونٹ کے ٹاٹ پلٹ دو، پھر اونٹ کا کالا کمیل پلٹ دیا اس کے بعد قلابازی کھائی جب میں یہ کام کر چکی تو اونٹ چنگا بھلا ہو کر کھڑا ہو گیا پھر بیٹھا اور پیشاب کرنے لگا۔ وہ کہنے لگی: اس پر اپنے کان لگاؤ، میں نے ایسا ہی کیا تو وہ پھر کانپنے لگا۔ کیا دیکھتی ہوں کہ اثوب ہمارے نقش قدم پر تلوار سونتے دوڑا آ رہا ہے۔ ہم نے بڑے بڑے گھروں کے پیچھے پناہ لی۔ اونٹ ایک درمیانی گھر کے برآمدے کا چکر لگا کر بیٹھ گیا وہ اونٹ بڑا رام و فرمانبردار تھا۔ پھر وہاں سے اٹھ کر اندر جا گھسا۔ اتنے میں اثوب تلوار لیے مجھ تک آپہنچا کہ تلوار کی نوک اس کے بالوں کو چھورہی تھی لگتا تھا ابھی وار کرنے کو ہے۔ مجھ سے کہتا ہے: اری کنیز! میری بھیجی مجھے دے دے۔ میں نے بچی اس کی طرف تھمادی جسے اس نے اپنے کندھے پر بٹھا لیا اور چلتا بنا۔ گھرانے کے لوگوں میں سے میں اس کی طبیعت سے زیادہ واقف تھی۔ پھر میں اپنی اس بہن کی جانب چل پڑی جس کی بنی شیبان میں شادی ہوئی تھی تا کہ رسول اللہ صلی اللہ علیہ وسلم کا ساتھ نصیب ہو جائے۔ ایک رات میں اس کے گھر میں تھی وہ سمجھ رہی تھی کہ میں سوئی پڑی ہوں، اتنے میں اس کا خاوند دیہاتی بیٹھک سے آ کر کہنے لگا: تیرے باپ کی قسم! میں نے قبیلہ کے لیے ایک سچا آدمی تلاش کر لیا ہے۔ میری بہن جھٹ سے بولی: کون؟ کہنے لگا: حریث بن حسان شیبانی، بکر بن وائل کا قاصد، اس پر میری بہن کہنے لگی: میرا کچھ نہ رہے۔ میری بہن سے مت کہنا۔ بھلا وہ بکر بن وائل کے آدمی کے ساتھ ایسی جگہ کیسے جائے گی جہاں اس کا سننے دیکھنے والا کوئی نہیں۔ کم از کم اس کی قوم کا کوئی اور مرد تو ساتھ ہوتا۔ وہ کہنے لگا: میں اس سے اس بات کا تذکرہ نہیں کروں گا۔ وہ بولی: میں بھی یہ بات بتانے کی نہیں۔ صبح ہوتے ہی میں نے اپنے اونٹ پر سامان باندھا، کسی کی آواز سنائی دی، میں نے اسے تلاش کیا تو وہ معمولی فاصلے پر تھا میں نے اس کے ساتھ جانے کا پوچھا، وہ کہنے لگا: ٹھیک ہے، اس کی سواریاں اس کے پاس بیٹھی تھیں۔ ہم اس بچے شخص کے ساتھ روانہ ہو گئے اور مدینہ پہنچے نبی کریم صلی اللہ علیہ وسلم نماز فجر پڑھا رہے تھے، جونہی صبح پھوٹی اس وقت نماز قائم کی گئی ستارے آسمان پر چمک رہے تھے، اندھیرا اتنا تھا کہ لوگوں کی پہچان نہیں ہو رہی تھی۔ میں نے مردوں کی صف میں نیت باندھ لی، میں چونکہ جاہلیت کے دور سے نئی نئی اسلام میں داخل ہوئی تھی، اسی صف میں سے ایک مرد مجھے کہنے لگا: کیا تو مرد ہے یا عورت؟ میں نے کہا: نہیں! میں عورت ہوں۔ وہ کہنے لگا: مجھے تو تو نے فتنہ میں ڈال دینا تھا، پیچھے عورتوں کی صف میں نماز پڑھ۔ میں نے دیکھا کہ حجروں کے پاس عورتوں کی صف بنی تھی، لیکن جب میں مسجد میں داخل ہوئی تھی اس وقت مجھے نظر نہ آئی۔ پھر میں ان میں شامل ہوگئی اور ان کے ساتھ ہی رہی۔ پھر جب سورج طلوع ہوا تو میں منبر کے قریب ہوگئی، جونہی مجھے کوئی چادر اور لباس والا مرد دکھائی دیتا تو میری نگاہیں ادھر لگ جائیں تا کہ میں رسول اللہ صلی اللہ علیہ وسلم کو دیکھ سکوں۔ جونہی سورج بلند ہوا، ایک شخص آ کر کہنے لگا: “السلام عليك يا رسول الله” آپ صلی اللہ علیہ وسلم نے فرمایا: “وعليك السلام و رحمة الله”۔ آپ ایک یا دو پرانے کپڑے جن پر زعفران لگی تھی زیب تن فرما تھے وہ تڑ تڑا رہے تھے۔ آپ صلی اللہ علیہ وسلم کے دست مبارک میں کھجور کی ایک شاخ تھی، جس کے سر پر دو پتوں کے علاوہ باقی خالی تھی، آپ صلی اللہ علیہ وسلم اکڑوں بیٹھے تھے۔ میں نے جب رسول اللہ صلی اللہ علیہ وسلم کو اس طرح عاجزی کی حالت میں بیٹھے دیکھا تو مجھ پر بے تحاشا رعب طاری ہو گیا۔ اور میں کانپنے لگی۔ آپ صلی اللہ علیہ وسلم کے پاس بیٹھے شخص نے کہا: اللہ کے رسول صلی اللہ علیہ وسلم! یہ بے چاری ڈرگئی ہے، آپ صلی اللہ علیہ وسلم نے مجھے دیکھے بغیر اشارہ کیا میں آپ کی پیٹھ پیچھے تھی: “اے مسکین عورت! وقار و اطمینان سے رہ”۔ آپ صلی اللہ علیہ وسلم نے جب یہ جملہ ارشاد فرمایا تو سارا خوف و ہراس اللہ تعالیٰ نے دور فرما دیا۔ میرے ساتھ آنے والا شخص آگے بڑھا، اسلام اور اپنی قوم کی امان کی خاطر بیعت کی۔ پھر کہنے لگا اللہ کے رسول صلی اللہ علیہ وسلم! ہمارے اور بنی تمیم کے درمیان ایک تحریر مقام دھناء کے متعلق لکھ دیں، جہاں سے ہمارے پاس صرف مسافر اور راہ گزر ہی آیا کرے۔ آپ علیہ السلام نے فرمایا: نوجوان! دھناء کے متعلق تحریر لکھ دو۔ میں نے جب دیکھا کہ آپ صلی اللہ علیہ وسلم کے اس کے بارے میں فرمان جاری کر چکے ہیں، مجھے خیال آیا ارے وہ تو میرا وطن اور میری جائے پیدائش میں ہے۔ میں جھٹ سے بولی: اللہ کے رسول صلی اللہ علیہ وسلم! ان صاحب نے آپ سے جب زمین کا سوال کیا تو برابری کا سوال نہیں کیا، حالانکہ وہ زمین تو اونٹوں کو باندھنے، بکریوں کو چرانے کی زمین ہے اور بنی تمیم کی عورتیں اور بچے تو اس کے ورے ہیں۔ اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: “نوجوان! ذرا رکنا! اس مسکین خاتون نے سچ کہا۔ مسلمان، مسلمان کا بھائی ہوتا ہے، درخت اور پانی ان کے لیے گنجائش رکھتے ہیں۔ اور وہ دونوں آگ جلانے میں ایک دوسرے سے تعاون کرتے ہیں۔” حریث نے جب دیکھا کہ اس کی منشا میں رکاوٹ پیدا ہوگئی تو وہ تالی بجا کر کہنے لگا: اری! میری اور تیری مثال تو یہ کہاوت ہے: اس کی موت اسے جدا کرنے والی ہے جسے وہ اپنے گھروں سے اٹھائے ہوئے ہے (ایک شخص کہیں سے بکری لایا لیکن ذبح کرنے کے لیے چھری نہ ملی، اچانک بکری نے کھروں سے زمین کریدی نیچے سے چھری برآمد ہوگئی)۔ میں نے کہا: اللہ کی قسم! اگر چہ تو تاریکیوں میں رہنما بن کر اور رفیق سفر کے لیے پاکدامن مرد ثابت ہوا ہے یہاں تک کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آ گئے لیکن یاد رکھو! جب تم نے اپنا حق مانگا ہے تو مجھے اپنا حق مانگنے پر ملامت کیوں کرتے ہو؟ اس نے کہا: دھناء میں تیرا کیا حق ہے؟ میں نے کہا: وہ میرے اونٹوں کے باندھنے کی جگہ ہے، جسے تم اپنی بیوی کے لیے مانگ رہے ہو۔ وہ بولا: یقیناً میں رسول اللہ صلی اللہ علیہ وسلم کو اس بات کا گواہ بنا کر کہتا ہوں کہ جب تک تم زندہ رہی میں تمہارا بھائی ہوں۔ اگر تم رسول اللہ صلی اللہ علیہ وسلم کے سامنے میری یہ تعریف کر دو۔ میں نے کہا: جب تم نے ہی اس کا آغاز کر دیا ہے تو میں بھی اس کی لاج رکھوں گی۔ رسول اللہ صلی اللہ علیہ وسلم فرمانے لگے: کیا اہل محبت کو ملامت کیا جاتا ہے کہ وہ خطہ ارض علیحدہ کر کے اور حجرہ کے پیچھے انتظار کرنے، فرماتی ہیں: میں تو رونے لگی اور رو کر عرض کرنے لگی: اللہ کے رسول! میں “حرام” کی اولاد میں سے تھی جس نے ربذہ میں آپ کی معیت میں جنگ کی پھر خیبر سے غلہ لینے گئے وہاں انہیں بخار ہوا جس سے وہ فوت ہو گئے۔ آپ علیہ السلام نے فرمایا: اگر تو بے چاری نہ ہوتی تو ہم تجھے چہرہ کے بل گھسیٹتے، کیا تم میں سے کسی عورت سے اتنا بھی نہیں ہو سکتا کہ وہ اپنی کسی سہیلی کے ساتھ دنیا میں اچھا برتاؤ کرے۔ جب اس میں اور جو اس کا زیادہ حقدار ہے کوئی حائل ہو جاتا ہے تو وہ افسوس کرتا ہے۔ پھر فرمایا: “اے میرے رب! جو کچھ میں نے جاری کیا اسے مجھے فراموش کرا دے اور جو میں نے باقی رکھا اس کے بارے میں میری مدد فرما۔ اس ذات کی قسم! جس کے دست قدرت میں میری جان ہے! تم عورتوں میں سے کوئی روتی ہے پھر اس کی سہیلی اس کے پاس پناہ طلب کرنے آتی ہے۔ اے اللہ کے بندو! اپنے بھائیوں کو اذیت و عذاب نہ پہنچاؤ۔” پھر چمڑے کے ایک ٹکڑا پر ان کے لیے تحریر لکھوائی: “قیلہ اور قبلہ کی بیٹیوں کو نہ ظلم کا نشانہ بنایا جائے اور نہ کسی غلط کام پر مجبور کیا جائے، ہر مومن و مسلمان ان کا اچھا مددگار ہے اور انہیں پریشان نہ کیا جائے۔”","",{"fn":"(1) اسد الغابۃ (۷۲۲۳) تجرید (۲۹۹/۲)\n(2) المعجم الکبیر (۲۵/۱)\n(3) ابوداؤد، کتاب الخراج والإمارۃ والفی، باب فی إقطاع الأرضین (۳۰۷۰)\n(4) ترمذی، کتاب الأدب، باب ما جاء فی الثوب الأخضر الحدیث (۲۸۱۴)\n(5) الاستيعاب (۱۹۰۶/۴)"}],[11612,"§۱۱۶۵۱ ۔ قَیلہ الأنماریہ\n(1) انہیں بنی انمار کی ماں اور بنی انمار کی بہن کہا جاتا تھا۔ طبری فرماتے ہیں: عقیلیہ، ابن ابی خیثمہ انصاری کا قول ہے، بنو انمار کی بہن، انہیں شرف صحابیت حاصل ہے، انہوں نے اور ابن ماجہ نے عبداللہ بن عثمان بن خیثم کے طریق سے جو انہوں نے ان سے روایت کی، حدیث نقل کی ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو مروہ کے پاس دیکھا، آپ اپنے عمرہ سے حدود حرم سے حدود حل میں داخل ہو رہے تھے۔ میں نے کہا: میں خرید و فروخت کرتی ہوں، اور خرید سے زیادہ بھاؤ کر لیتی ہوں، پھر مجھے مال کم کرنا پڑتا ہے۔۔۔۔ (الحدیث)(2) اس میں ہے: ایسا نہ کیا کرو۔ ابن سعد(3) نے اس طویل روایت کو ابن خیثم سے نقل کیا ہے، اور اسے ابن سکن نے نقل کیا ہے، ان کی روایت میں ہے کہ حضرت عبداللہ بن عثمان بن خیثم نے فرمایا کہ انہوں نے قبیلہ سے سنا، اور فاکہی فرماتے ہیں: ام انمار کا مکہ میں گھر ہے اور وہ پچھلے دور کی خواتین میں سے فضیلت و بہادری میں اپنا مقام رکھتی تھیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۱) الاستيعاب (۳۵۲۵) تجرید (۲۹۹/۲)\n(2) ابن ماجہ (۱۲۲۰۴) المعجم الکبیر (۴/۲۵) جامع المسانید والسنن (۶۸، ۶۹/۱۶)\n(3) الطبقات الکبریٰ (۳۱۱/۸)"}],[11613,"§۱۱۶۵۲ ۔ قَیلہ الخزاعیہ\n(1) ام سباع بن عبد العزیٰ بن عمرو بن نصلہ، بنو زھرہ کے حلیف تھے۔ ابن عبدالبر(2) نے ان کا ذکر کیا ہے اور فرمایا: ان کے بارے میں تردد ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۲) تجرید (۲۹۹/۲)\n(2) الاستيعاب (۱۹۰۶/۴)"}],[11614,"§۱۱۶۵۳ ۔ قَیلہ بنت قیس\n(1) ابن معدیکرب کندیہ، اشعث بن قیس کی بہن ہیں۔ یہ ابو عمر کا قول ہے۔ بعض کا قول ہے: قبیلہ، ان سے نبی کریم صلی اللہ علیہ وسلم نے واہ میں نکاح کیا، وہ وفات پا گئیں۔ آپ صلی اللہ علیہ وسلم کے پاس نہیں لائی گئیں، آپ صلی اللہ علیہ وسلم نے انہیں دیکھا، نہ رخصتی ہوئی، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم کا ان سے نکاح وفات سے دو ماہ قبل ہوا تھا، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے اپنی مرض وفات میں ان سے نکاح کیا، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے وصیت فرمائی کہ انہیں اختیار دیا جائے، اگر چاہیں تو ان پر حجاب لازم قرار دیا جائے اور امہات المؤمنین میں شامل ہوں، اور اگر چاہیں اور نکاح کر لیں، تو انہوں نے نکاح کو اختیار کیا تو ان سے عکرمہ نے حضرت موت میں نکاح کر لیا، جب سیدنا ابو بکر رضی اللہ عنہ کو یہ بات پہنچی تو فرمایا: میں چاہتا ہوں کہ ان دونوں کو ان کے گھر سمیت جلا دوں، تو سیدنا عمر رضی اللہ عنہ نے فرمایا: نہ وہ امہات المؤمنین میں سے ہے، نہ ہی اس کی رخصتی ہوئی ہے، اور اس کے لیے حجاب لازم قرار نہیں دیا گیا۔ بعض کا قول ہے: وہ یمن سے نکلنے سے قبل وفات پا گئیں۔ اس کے بعد ان سے عکرمہ نے نکاح کیا، بعض کا قول ہے، مرتد ہو گئیں اور سیدنا عمر رضی اللہ عنہ نے سیدنا ابو بکر رضی اللہ عنہ کے سامنے دلیل پیش کی کہ وہ ازواج مطہرات میں ان میں سے نہیں ہیں، اور فرمایا: عکرمہ کی ان سے اولاد نہ ہوئی۔ ان کے بارے میں بہت زیادہ اختلاف ہے۔ ابن عبدالبر کا کلام ختم ہوا۔ ابو نعیم نے اسحاق بن حبیب شہیدی کے طریق سے عبدالاعلیٰ سے، انہوں نے داؤد بن ابو ہند سے، انہوں نے عکرمہ سے، انہوں نے ابن عباس رضی اللہ عنہما سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے اشعث کی بہن قبیلہ سے نکاح کیا، تو اختیار دینے سے قبل وفات پا گئیں، اس موصول حدیث کی اسناد بھی قوی ہے۔(2) اسی طرح اسے عبدالوہاب ثقفی کے طریق سے بحوالہ داؤد شعمی مرسلاً نقل کیا ہے، اور اس کے الفاظ یہ ہیں۔۔۔۔ قیلہ بنت اشعث، آپ صلی اللہ علیہ وسلم کی وفات کے بعد عکرمہ نے ان سے نکاح کر لیا تو سیدنا ابو بکر رضی اللہ عنہ کو یہ بات ناگوار ہوئی، پھر سیدنا عمر رضی اللہ عنہ کی وہ بات نقل کی، جو گزر چکی ہے، اس کے آخر میں ہے، سیدنا ابو بکر رضی اللہ عنہ کو اطمینان ہوا اور خاموش ہو گئے۔(3)","",{"fn":"(1) اسد الغابۃ (۷۲۱۱) تجرید (۲۹۸/۲)\n(2) الاستيعاب (۱۹۰۴/۴)\n(3) اسد الغابۃ (۳۷۹/۵) الطبقات الکبریٰ (۱۰۵/۸، ۱۰۶)"}],[11615,"§۱۱۶۵۴ ۔ قُریبہ بنت الحارث العُتواریہ\n(1) ابن مندہ نے ان کی حدیث حفص بن عمر کے طریق سے بحوالہ بکار بن عبد العزیز، انہوں نے موسیٰ بن عبیدہ سے، وہ فرماتے ہیں کہ ہم سے یزید بن عبد الرحمن نے بحوالہ اپنی والدہ جحشہ بنت قرط، انہوں نے اپنی والدہ عقیلہ بنت عبید بن حارث، وہ فرماتے ہیں: میں اور میری والدہ قریبہ بنت حارث عتواریہ آئے، ان سے اسی طرح منقول ہے، اور صحیح قریرہ ہے، جیسا کہ حرف عین عقیلہ میں گزر چکا ہے، ابونعیم فرماتے ہیں: ابن مندہ نے قریبہ کا عنوان قائم کیا ہے، اور حدیث نقل کی جس میں فرمایا: قریرہ، اسی طرح طبرانی(2) وغیرہ نے نقل کیا ہے۔ میں کہتا ہوں: وہی صحیح ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۱۵) تجرید (۲۹۸/۲)\n(2) المعجم الکبیر (۸۵۴/۲۴)"}],[11616,"§۱۱۶۵۵ ۔ کبشہ بنت ابی امامہ\n(1) اسعد بن زرارہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، ان کے والد نے ان کے بارے نبی کریم صلی اللہ علیہ وسلم کو وصیت کی تھی تو ان سے عبد اللہ بن ابی حبیبہ نے نکاح کیا جو بنو اغر بن زید بن عطاف سے ہیں، وہ سیدنا اسعد کی صاحبزادیوں میں سب سے چھوٹی تھیں، بیعت کرنے والی صحابیات میں ان کا شمار ہے، ان کی بہن حبیبہ کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۴) تجرید (۲۹۹/۲)"}],[11617,"§۱۱۶۵۶ ۔ کبشہ بنت اوس\n(1) ابن شریق انصاریہ، بنو علمہ سے ہیں، خزیمہ بن ثابت کی والدہ ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۶) تجرید (۲۹۹/۲)"}],[11618,"§۱۱۶۵۷ ۔ کبشہ بنت ثابت\n(1) ابن حارثہ بن جلاس انصاریہ، بنو جدارہ سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(2) کا قول ہے، ان کی والدہ کا نام سلامہ ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۷) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۲۶۶/۸)"}],[11619,"§۱۱۶۵۸ ۔ کبشہ بنت ثابت\n(1) ابن علیک بن نعمان بن عمرو بن عتیک بن عمرو بن مبذول، ان کی کنیت ام سعید ہے۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ معاذہ بنت انس بن قیس بن عبید ہیں، ان سے یزید بن ابی الیسر، کعب بن عمرو نے نکاح کیا، جس سے سعید، عبدالرحمن اور ام کثیر پیدا ہوئے۔","",{"fn":"(1) تجرید (۲۹۹/۲)\n(2) الطبقات الکبریٰ (۲۶۶/۸)"}],[11620,"§۱۱۶۵۹ ۔ کبشہ بنت ثابت\n(1) ابن منذر بن حرام، سیدنا حسان کی باپ شریک بہن ہیں، بنو مالک بن نجار سے ہیں۔ ترمذی(2) اور ابو یعلیٰ نے یزید بن جابر کے طریق سے بحوالہ عبدالرحمن بن ابی عمرہ، انہوں نے اپنی دادی کبشہ سے ان کی حدیث روایت کی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے اور لٹکے ہوئے مشکیزے کے منہ سے پانی پیا، میں گئی اور جہاں سے نبی کریم صلی اللہ علیہ وسلم نے پانی پیا تھا اس کا منہ کاٹ لیا۔ اسی طرح ان کی حدیث میں ہے، اس میں ان کے والد اور نسب مذکور نہیں، ابوعروبہ نے ان کا نسب بیان کیا ہے، جیسا کہ میں نے ذکر کیا۔ اسے عبدالعزیز بن حسین نے بحوالہ یزید بن عبدالرحمن روایت کیا ہے، فرماتے ہیں: بحوالہ ان کی دادی بڑھیا صاحبہ کہ نبی کریم صلی اللہ علیہ وسلم نے کھڑے ہو کر پانی پیا۔ اسے ابن مندہ نے نقل کیا ہے، احتمال ہے کہ وہ ان سے ملے ہیں، اسے ابن وہب نے بحوالہ ابن لہیعہ، انہوں نے یزید سے روایت کیا ہے، فرماتے ہیں: بحوالہ ان کی دادی کبشہ، عنقریب ان کا تذکرہ آئے گا، ابن سعد(3) کا قول ہے: ان کی والدہ خطی بنت حارثہ بن لوزان ہیں، ان سے عمرو بن شخصن بن عمرو بن عتیک نے نکاح کیا، جس سے تعلیہ، ابو عمر اور حبیبہ پیدا ہوئے، اس کے بعد ان سے حارث بن ثعلبہ نے نکاح کیا، جس سے ام ثابت رملہ پیدا ہوئیں، اس کے بعد ان سے حارثہ بن نعمان نے نکاح کیا۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۵) تجرید (۲۹۹/۲)\n(2) ترمذی (الحدیث: ۱۸۹۲)\n(3) الطبقات الکبریٰ (۲۳۹/۸)"}],[11621,"§۱۱۶۶۰ ۔ کبشہ بنت حاطب\n(1) ابن قیس بن ہیٹہ، بنو معاویہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۸) الاستيعاب (۳۵۲۶) تجرید (۲۹۹/۲)"}],[11622,"§۱۱۶۶۱ ۔ کبشہ بنت رافع\n(1) ابن عبید بن ثعلبہ بن ابجر، وہ خدرہ ہیں، انصاریہ خدریہ، سیدنا سعد بن معاذ کی والدہ ہیں، ان کی وفات تک زندہ رہیں۔ ام سعد کے لیے سعد کے کھو جانے کا افسوس، اس نے مستقل الرائے اور ہمت آج گنوادی۔ ابن اسحاق(2) نے سیدنا سعد کی وفات کے موقعہ پر یہ اشعار نقل کیے ہیں، پھر ان سب نے ذکر کیا کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: “ہر بین کرنے والی عورت جھوٹ بولتی ہے سوائے سعد کا بین کرنے والی کے”۔(3)","",{"fn":"(1) اسد الغابۃ (۷۲۳۰) الاستيعاب (۳۵۲۸) تجرید (۲۹۹/۲)\n(2) السیرۃ النبویۃ (۱۹۸/۳)\n(3) اسد الغابۃ (۲۸۵/۵)"}],[11623,"§۱۱۶۶۲ ۔ کبشہ بنت عمرو\n(1) ابن عبد بن قمیہ بن عامر بن خزرج انصاریہ، بنو ساعدہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۱) تجرید (۳۰۰/۲)"}],[11624,"§۱۱۶۶۳ ۔ کبشہ بنت الفاکہ\n(1) ابن قیس انصاریہ زرقیم۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۲۸۵/۳)"}],[11625,"§۱۱۶۶۴ ۔ کبشہ بنت فروہ\n(1) ابن عمرو بن فروہ انصاریہ، بنو بیاضہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۲) تجرید (۳۰۰/۲)"}],[11626,"§۱۱۶۶۵ ۔ کبشہ بنت کعب\n(1) ابن مالک انصاریہ، عبداللہ بن ابی قتادہ کی زوجہ ہیں۔ ابن حبان کا قول ہے، انہیں شرف صحابیت حاصل ہے۔ مستغفری نے ان کی پیروی کی ہے، موطا اور سنن اربعہ میں بلی کے لعاب کے بارے میں بحوالہ ابی قتادہ ان کی حدیث مروی ہے۔ ابن سعد(2) کا قول ہے: ان سے ثابت بن ابی قتادہ نے نکاح کیا، جس سے اولاد ہوئی، ان کی والدہ صفیہ اہل یمن سے ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۳) تجرید (۳۰۰/۲)\n(2) ابوداؤد (۷۵) ترمذی (۹۲) نسائی (۶۸) (۳۳۹) ابن ماجہ (۳۶۷) مالک (۴۶) مسند احمد (۲۹۶/۵، ۳۰۳، ۳۰۹)"}],[11627,"§۱۱۶۶۶ ۔ کبشہ بنت مالک\nابن سنان، ابوسعد کی بہن ہیں، فریعہ ہیں، ان کا ذکر گزر چکا ہے۔"],[11628,"§۱۱۶۶۷ ۔ کبشہ بنت مالک\nابن قیس، کبشیہ میں ان کا ذکر آئے گا۔"],[11629,"§۱۱۶۶۸ ۔ کبشہ بنت معدیکرب\n(1) اشعث بن قیس کی پھوپھی ہیں، معاویہ بن خدیج جو معروف صحابی ہیں ان کی والدہ ہیں۔ دارقطنی(2) نے ان کا قصہ، ان کے بیٹے معاویہ کے طریق سے بیان کیا کہ انہوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے پاس آیا، میرے ساتھ میری والدہ کبشہ بنت معدیکرب تھیں جو اشعث کی پھوپھی ہیں، انہوں نے کہا: یا رسول اللہ! میں نے قسم کھائی ہے کہ بیت اللہ کا طواف گھٹنوں کے بل کروں گی، آپ صلی اللہ علیہ وسلم نے فرمایا: اپنے پاؤں پر ستر بار طواف کرو، سات اپنے ہاتھوں کی طرف سے اور سات اپنے پیروں کی طرف سے۔۔۔۔ اس کی سند ضعیف ہے۔ ابن دباغ وغیرہ نے استیعاب پر اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۳۵۱/۸)\n(2) سنن دارقطنی (۲۷۳/۲)"}],[11630,"§۱۱۶۶۹ ۔ کبشہ بنت معن\n(1) ابن عاصم انصاریہ، ابو قیس بن اسلت کی زوجہ تھیں، انہیں کبشہ کہا جاتا تھا۔ ابن جریج کا قول ہے جو انہوں نے عکرمہ سے نقل کیا ہے کہ ان کے بارے میں یہ آیت نازل ہوئی: تمہارے(2) لیے یہ حلال نہیں کہ تم زبردستی عورتوں کے وارث بن بیٹھو۔۔۔۔(3) ابوموسیٰ نے اسے مستغفری کے حوالے سے نقل کیا ہے، پھر ابو ثور کے طریق سے، انہوں نے ابن جریج سے نقل کیا ہے، میں نے اسے انساب میں کئی طرق سے ذکر کیا ہے۔(4)","",{"fn":"(1) الطبقات الکبریٰ (۳۵۱/۸)\n(2) اسد الغابۃ (۷۲۳۰۰) تجرید (۳۰۰/۲)\n(3) سورۃ النساء الآیۃ (۱۹)\n(4) تفسیر ابن کثیر (۲۱۴/۲)"}],[11631,"§۱۱۶۷۰ ۔ کبشہ بنت واقد\n(1) ابن عمرو بن عامر بن زید مناۃ اور عمرو بن اطنابہ ہیں، جو بنو حارث بن خزرج سے ہیں، ابن حبیب نے بیعت کرنے والی خواتین میں ان کا ذکر کیا ہے، وہ ام عبد اللہ بن رواحہ ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے، ان کے بارے میں منقول ہے: کبیشہ تصغیر کے ساتھ ہے، اس میں یہ اضافہ ہے، جب رواحہ کی وفات ہوئی تو ان سے قیس بن شماس نے نکاح کیا، جس سے ثابت پیدا ہوئے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۵) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۲۶۴/۸)"}],[11632,"§۱۱۶۷۱ ۔ کُبیرہ\n(1) بعض کا قول ہے: کثیرہ، ابن مندہ نے “ث” کے ساتھ نقل کیا ہے۔ ابو نعیم نے ان کی پیروی کی ہے، ابو موسیٰ نے ذیل میں ابن ماکولا کی پیروی کرتے ہوئے باء کے ساتھ ذکر کیا ہے۔ میں کہتا ہوں: ابن ماکولا خطیب پر سبقت لے گئے، اور فرمایا: کبیرہ، جو کبیرہ بنت ابوسفیان ہیں۔ انہیں شرف صحابیات اور روایت حاصل ہے، پھر محمد بن سلیمان بن سموال کے طریق سے بحوالہ بیٹی بن ابی ورقہ بن سعید، انہوں نے اپنے والد سے روایت کی، فرماتے ہیں: مجھ سے میری مولاۃ کبیرہ بنت ابی سفیان نے روایت کی۔ انہوں نے جاہلیت کا زمانہ پایا، اور بیعت کرنے والی صحابیات میں سے ہیں، فرماتی ہیں: یا رسول اللہ! میں نے جاہلیت میں اپنے چار بیٹوں کو زندہ دفن کیا تھا، آپ صلی اللہ علیہ وسلم نے فرمایا: چار غلام آزاد کر دو۔ انہوں نے ابوسعید اور ان کے بیٹے میسرہ، ام میسرہ کو آزاد کیا، خطیب فرماتے ہیں: انہوں نے چوتھے کا ذکر نہیں کیا، شاید وہ اس حدیث کے راوی ہیں: یعنی ابو ورقہ۔ ابن اثیر(2) کا قول ہے، جس میں انہوں نے سلف کی پیروی کی ہے کہ وہ خزاعیہ ہیں، بعض کا قول ہے: ثقفیہ، بعض نے کہا: کبیرہ بنت ابی سفیان، اور مذکورہ استاد کے ساتھ ایک اور حدیث روایت کی: “خاکستری رنگ کے جانور کا خون اللہ تعالیٰ کے نزدیک سیاہ رنگ والے جانور سے زیادہ پاکیزہ ہے”۔(3)","",{"fn":"(1) اسد الغابۃ (۷۲۳۶) تجرید (۳۰۰/۲)\n(2) اسد الغابۃ (۳۸۶/۵)\n(3) المعجم الکبیر (۲۵/۹) مجمع الزوائد (۱۸/۴)"}],[11633,"§۱۱۶۷۲ ۔ کُبیشہ بنت مالک\n(1) ابن قیس انصاریہ، بنو مازن سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ وہ شموس ہیں۔ ابن سعد(2) نے تصغیر کے بغیر ان کا ذکر کیا ہے اور فرمایا: ان کی والدہ سہیمہ بنت عویمر بن اسعد ہیں، ان سے ثعلبہ بن شخصن بن عمرو بن عتیک بن عمرو بن مبذول نے نکاح کیا، جس سے زینب پیدا ہوئیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۷) تجرید (۳۰۰/۲)\n(2) الطبقات الکبریٰ (۳۰۶/۸)"}],[11634,"§۱۱۶۷۳ ۔ کبشہ بنت معن\nابن عاصم، کبشہ (بغیر تصغیر) میں ان کے حالات گزر چکے ہیں۔"],[11635,"§۱۱۶۷۴ ۔ کثیرہ\nٹ کے ساتھ، بنت ابی سفیان، کبیرہ میں گزر چکی ہیں۔"],[11636,"§۱۱۶۷۵ ۔ کحیلہ\nطبرانی کی معجم کبیر میں حدیث ابوامامہ میں ان کا ذکر ہے۔"],[11637,"§۱۱۶۷۶ ۔ کریمہ بنت ابی حدرد الاسلمیہ\n(1) بعض کا قول ہے: انہیں شرف صحابیت حاصل ہے، ابن حبان اور مستغفری نے ان کا ذکر کیا ہے، بعض کا قول ہے: وہ ام درداء کبرئی ہیں، حالانکہ یہ وہ نہیں ہیں۔ ام درداء کیبرٹی کے بارے میں معروف ہے کہ ان کا نام خیرہ ہے جیسا کہ حرف خاء میں گزر چکا ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۳۹) الاستيعاب (۳۵۳۰) تجرید (۳۰۰/۲)"}],[11638,"§۱۱۶۷۷ ۔ کریمہ بنت کلثوم الحمیریہ\nعکاف بن وداعہ کے سوانح میں ان کا ذکر گزر چکا ہے، بعض کا قول ہے: وہ زینب بنت کلثوم ہیں۔"],[11639,"§۱۱۶۷۸ ۔ کُعیبہ\n(1) بنت سعید اسلمیہ، ابوعمر(2) نے بحوالہ واقدی ان کا ذکر کیا ہے کہ وہ خیبر میں آپ صلی اللہ علیہ وسلم کے ساتھ حاضر تھیں، رسول اللہ صلی اللہ علیہ وسلم نے ان کے لیے ایک آدمی کے حصے کے برابر حصہ عطا فرمایا، ابن سعد(3) کا قول ہے: یہ وہی ہیں جو مسجد میں ان کا خیمہ تھا، بیماروں اور زخمیوں کو دوا دیتیں، سیدنا سعد بن معاذ رضی اللہ عنہ کو جب تیر لگا تو ان کے زخموں کا علاج کرتی تھیں، یہاں تک کہ وہ وفات پاگئے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۱) الاستيعاب (۳۵۳۱) تجرید (۳۰۰/۲)\n(2) الاستيعاب (۱۹۰۷/۴)\n(3) المغازی (۶۸۵/۲)"}],[11640,"§۱۱۶۷۹ ۔ کلبہ بنت یثربی\n(1) انہیں شرف صحابیت حاصل ہے۔ تجرید میں اسی طرح ہے، بغیر اضافے کے میرا خیال ہے کہ یہ بعد والی ہیں، پھر میں نے ابراہیم حربی کے کلام میں اس کے بارے میں تصریح پائی ہے، انہوں نے ان کے والد کا نام وہی بتایا ہے جو اوروں نے بتایا ہے۔(2)","",{"fn":"(1) الطبقات الکبریٰ (۲۱۳/۸)\n(2) تجرید (۳۰۱/۲)"}],[11641,"§۱۱۶۸۰ ۔ کُلثُم\n(1) بعض کا قول ہے: کلیہ، بنت بُرھن۔ بنو عنبر بن تمیم سے ہیں۔ زینب بن ثعلبہ کی والدہ ہیں، طبرانی(2) نے کبیر میں زینب ابن ثعلبہ کے طریق سے نقل کیا ہے، فرماتے ہیں، مجھے میری والدہ کلیبہ بنت بُرشن عنبریہ نے بلایا اور کہا: اے میرے بیٹے! اس شخص نے میری اوڑھنے والی چادر لے لی ہے۔ میں اس شخص سے جا ملا اور اسے رسول اللہ صلی اللہ علیہ وسلم کے پاس لے آیا، میں نے عرض کی: اللہ کے رسول! اس نے میری والدہ کی چادر لے لی ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: اسے وہ چادر واپس کرو۔ ابونعیم نے ان کا ذکر کیا ہے، یہ طویل حدیث سے مختصر لیا گیا ہے۔ ابونعیم کا قول ہے، بعض نے کہا: ان کا نام کلیم ہے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۲) تجرید (۳۰۱/۲)\n(2) المعجم الکبیر (۲۵/۱۱)"}],[11642,"§۱۱۶۸۱ ۔ مکثم بنت محرز النجاریہ\n(1) سیدہ اسماء کی بہن ہیں، جن کا ذکر گزر چکا ہے۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۳۰۹/۸)"}],[11643,"§۱۱۶۸۲ ۔ کُلثم\nعبدالرحمن بن ابی عمرہ کی دادی ہیں، کبعہ میں ان کا ذکر گزر چکا ہے۔"],[11644,"§۱۱۶۸۳ ۔ کُنود بنت قرطہ\nفاختہ بنت قرطہ میں ان کا ذکر ہے۔"],[11645,"§۱۱۶۸۴ ۔ کُنود ام سارہ\nسارہ میں ان کا ذکر گزر چکا ہے۔"],[11646,"§۱۱۶۸۵ ۔ کُویسہ\n(1) یہ یتیمہ تھی جو نبی کریم صلی اللہ علیہ وسلم کی پرورش میں تھی۔ یہ کلیب بن عیسیٰ کا قول ہے، جو انہوں نے زُجلہ سے، انہوں نے ان سے روایت کیا ہے، تجرید میں اسی طرح مذکور ہے۔ انہوں نے اختصار میں انتہائی کمی کی ہے۔ زُجلہ، اہل شام کی ایک خاتون تھیں، انہوں نے ام درداء وغیرہ سے روایت کیا، خطیب نے مؤتلف میں ہیثم بن خارجہ کے طریق سے، انہوں نے کلیب بن عیسیٰ بن ابی حجر ثقفی سے روایت کیا، فرماتے ہیں: میں نے زُجلہ سے، جو معاویہ کی مولاۃ ہیں، فرماتے ہوئے سنا: میں نے ان یتیموں کا زمانہ پایا، جو نبی کریم صلی اللہ علیہ وسلم کی پرورش میں تھیں، ان میں سے ایک کا نام کویسہ تھا، انہوں نے یہ قصہ بیان کیا کہ عورتیں جنازہ کے پیچھے نہیں جاتی تھیں ہاں اگر کوئی عورت ماہواری یا حمل سے ہوتی تو وہ عید گاہ نہ جاتی جبکہ بقیہ خواتین عید گاہ جاتی تھیں۔ جب جنازہ رکھ دیا جاتا وہ عورت اپنا ہاتھ میت کے پیٹ پر رکھتی کہ آیا اس سے کوئی چیز تو نہیں نکلی، مرد اسے دیکھ رہے ہوتے، یہاں تک کہ جب وہ چھپ جاتی تو لوگ امام سے کہتے تکبیر کہے۔","",{"fn":"(1) الاستيعاب (۳۵۲۷) تجرید (۳۰۱/۲)"}],[11647,"§۱۱۶۸۶ ۔ کیسہ\nبنت حارث بن کریز بن عبد شمس، مسیلمہ کذاب کی زوجہ تھیں، اس کے بعد عبد اللہ بن عامر اکبر کے نکاح میں آئیں۔ زبیر بن بکار نے ان کا ذکر کیا ہے، اور ان کا نام قلمبند کیا ہے۔"],[11648,"§۱۱۶۸۷ ۔ کُبشہ بنت حکیم الثقفیہ\n(1) ام حکم بنت یحییٰ بن عقبہ کی دادی ہیں، ام حکیم نے ان سے روایت کیا کہ انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا، ابن مندہ نے اسی طرح ذکر کیا ہے۔ اور ابونعیم نے اسے ذکر کیا ہے، فرمایا: اس پر اضافہ نہیں کیا، یعنی ان کی حدیث نقل نہیں کی۔","",{"fn":"(1) اسد الغابۃ (۷۲۲۹) تجرید (۲۹۹/۲)"}],[11649,"§۱۱۶۸۸ ۔ کبشہ بنت مکشوح المرادیہ\nقیس کی بہن ہیں جو مشہور شہسوار ہیں، ابن شاہین نے ابان بن سعید بن العاص کے سوانح میں ان کا ذکر کیا ہے، وہ صاحب جمال خاتون تھیں، ان کے بھائی قیس بن ابان نے ان کا نکاح کر دیا، سیدنا ابو بکر صدیق رضی اللہ عنہ کی خلافت میں جب وہ یمن کے والی مقرر ہوئے تھے۔ ایک طویل حدیث میں یہ سلیمان انباری کے طریق سے بحوالہ نعمان بن بزرج منقول ہے۔"],[11650,"§۱۱۶۸۹ ۔ کبشہ بنت بُرتن\n(1) بعض کا قول ہے: بیر بی عنبریہ۔ ابوعمر نے حدیث زینب بنت ثعلبہ میں ان کا تذکرہ کیا ہے۔ اسی طرح تجرید میں ہے اور وہ غلطی ہے۔ یہ کلیہ تصغیر کے ساتھ ہے، جیسا کہ قریب ہی کلثم میں گزر چکا ہے۔","",{"fn":"(1) تجرید (۲۹۹/۳)"}],[11651,"§۱۱۶۹۰ ۔ لُبابہ بنت اسلم\n(1) ابن حریش بن عدی بن مجدعہ بن حارثہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، اور فرمایا: سیدنا سلمہ بن اشیاء کی سگی بہن ہیں۔ ان سے زید بن سعد بن زید اشہلی نے نکاح کیا۔","",{"fn":"(1) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۲۴۴/۸)"}],[11652,"§۱۱۶۹۱ ۔ لُبابہ بنت الحارث\n(1) ابن حزن بن بخیر بن ہرم بن رویبہ بن عبد اللہ بن ہلال بن عامر بن صعصعہ بلالیہ، ام الفضل سیدنا عباس بن عبدالمطلب کی زوجہ اور ان کی اولاد، فضل، عبد اللہ وغیرہ کی والدہ ہیں۔ یہ لبابہ کبریٰ ہیں جو اپنی کنیت سے مشہور اور اپنے نام سے پہچانی جاتی ہیں۔ کنیتوں میں ان کا ذکر آئے گا۔ ان کی والدہ خولہ بنت عوف قرشیہ ہیں۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۴) الاستيعاب (۳۵۳۲) تجرید (۳۰۱/۲)"}],[11653,"§۱۱۶۹۲ ۔ لُبابہ بنت الحارث ابن حزن ہلالیہ\n(1) ابن حزن ہلالیہ، اس سے پہلی صحابیہ کی بہن ہیں، یہ لبابہ صغریٰ ہیں، ان کا لقب عصماء تھا، ان کی والدہ فاختہ بنت عامر ثقفیہ ہیں اور یہ خالد بن ولید کی، جو مشہور صحابی ہیں، والدہ ہیں۔ ابو عمر(2) کا قول ہے: ان کے اسلام لانے اور صحابیہ ہونے میں تردد ہے۔ ابن اثیر(3) نے اسی کو برقرار رکھا ہے۔ یہ عجیب بات ہے، گویا انہوں نے ان کے شوہر ولید کی پہلے وفات کی جہت سے اسے بعید سمجھا ہے، کہ وہ ان کے ساتھ یہ تھوڑا عرصہ بعد وفات پاگئیں ہوں، یہ ضروری نہیں، کیونکہ ثابت ہو چکا ہے کہ وہ اپنے بیٹے خالد کی وفات کے بعد بھی زندہ رہیں۔ ان کا اس بارے میں قصہ ہے۔ ابو حذیفہ نے مبتدا والفتوح میں بحوالہ محمد بن اسحاق ذکر کیا ہے، فرماتے ہیں: جب سیدنا خالد بن ولید رضی اللہ عنہ کی وفات ہوئی تو سیدنا عمر رضی اللہ عنہ ان کے جنازے کے لیے نکلے تو ان کی والدہ یہ اشعار پڑھ رہی تھیں: “تم قوم کے لاکھوں میں سے بہتر ہو، جب تم لوگوں کے چہروں کے سامنے تھے۔” فرماتے ہیں، سیدنا عمر رضی اللہ عنہ نے فرمایا: تم نے سچ کہا، ایسا ہی تھا۔ سیف بن عمر نے ارتداد اور فتوح کے زمانے کے بارے میں اپنی سند سے فرمایا اور سیدنا خالد رضی اللہ عنہ کے الگ ہو جانے اور مدینہ میں مقیم ہونے کے بارے میں ذکر کیا ہے، فرماتے ہیں: جب سیدنا عمر رضی اللہ عنہ نے دیکھا کہ لوگوں کے فتنے میں پڑنے کا خدشہ ختم ہو گیا ہے تو انہوں نے ارادہ کیا کہ حج سے واپسی پر وہ انہیں عہدہ پر بحال کر دیں، ان کے ساتھ سیدنا خالد بن ولید رضی اللہ عنہ نکلے، انہوں نے مدینہ سے باہر پانی مانگا، تو فرمایا: میرے ہجرت کے مقام تک مجھے نیچے اتار دو۔ تو ان کی والدہ انہیں مدینہ لے آئیں۔ وہاں ان کی تیمار داری کی۔ سیدنا عمر رضی اللہ عنہ نے حج سے آنے والے ایک آدمی سے پوچھا: کیا خبر ہے؟ اس نے کہا: خالد کی حالت تشویشناک ہے۔ سیدنا عمر رضی اللہ عنہ نے تین راتوں کا سفر ایک رات میں طے کیا۔ ان کی وفات کے بعد سیدنا عمر رضی اللہ عنہ پہنچے، ان پر رقت طاری ہوگئی، إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ پڑھا۔ جب ان کی تجہیز ہوئی تو عورتیں رونے لگیں، آپ سے کہا گیا: کیا آپ انہیں نہیں روکتے؟ انہوں نے فرمایا: ابوسلیمان پر آنسو بہانے میں کوئی حرج نہیں جب تک مار دھاڑ اور آواز بلند نہ ہو۔ جب آپ کا جنازہ اٹھایا گیا تو ایک عورت احرام باندھے رو رہی تھی اور کہہ رہی تھی: تو لاکھوں میں بہتر ہے۔۔۔۔ جو شعر پہلے گزر چکا ہے، اس کے بعد ہے: “کیا بہادری؟ تو لیث مرۃ بن جہم ابی اشبال سے زیادہ بہادر تھا۔ کیا سخاوت؟ تو پہاڑوں کے درمیان جانے والے سیلاب سے زیادہ سخی تھا۔” تو سیدنا عمر رضی اللہ عنہ نے پوچھا: یہ کون ہے؟ کہا گیا: ان کی والدہ۔ آپ نے کہا: ان کی والدہ، اللہ کی قسم! تین مرتبہ فرمایا، تو کیا عورتوں سیدنا خالد جیسے شخص کی میت سے اٹھی تھیں۔ یہ اگر ابو حذیفہ کی روایت ہے تو وہ ضعیف ہے، اسی طرح سیف بھی ضعیف ہے، لیکن ابن سعد(4) نے ذکر کیا ہے، وہ ثقہ ہے، بحوالہ کثیر بن ہشام، انہوں نے جعفر بن بُرقان سے، انہوں نے یزید بن اصم سے، فرماتے ہیں: جب خالد بن ولید رضی اللہ عنہ وفات پاگئے تو ان کی والدہ ان پر روئیں، تو سیدنا عمر رضی اللہ عنہ نے فرمایا: اے ام خالد! کیا خالد یا اس کے اجر کی مصیبت پر آنسو بہاتی ہو؟ تمہیں ثابت قدم رہنا ہوگا یہاں تک کہ تم مہندی سے اپنا ہاتھ رنگ لو۔ یہ سند صحیح ہے۔ بخاری وغیرہ نے سیدنا عمر رضی اللہ عنہ کے قول کو تعلیقاً ذکر کیا ہے جس میں سیدنا خالد پر بلند آواز سے آنسو بہانے کا ذکر ہے۔ لیکن ان کی والدہ کا نام نہیں لیا۔ ان روایات سے معلوم ہوا کہ وہ نبی کریم صلی اللہ علیہ وسلم کے بعد بھی زندہ رہیں، کیا اس سے یہ گمان کیا جا سکتا ہے کہ وہ فتح کے بعد نبی کریم صلی اللہ علیہ وسلم کی وفات تک حالت کفر میں رہیں، یہ بعید ہے اور یہ قول اسے باطل کر دے گا کہ حرمین اور طائف میں حجۃ الوداع کے موقع پر سب لوگ اسلام لا چکے تھے اور حاضر تھے۔","",{"fn":"(1) اسد الغابۃ (۷۲۴۵) الاستيعاب (۳۵۳۳) تجرید (۳۰۱/۲)\n(2) الاستيعاب (۱۹۰۹/۴)\n(3) اسد الغابۃ (۳۹۰/۵)\n(4) الطبقات الکبریٰ (۲۴۶/۸)"}],[11654,"§۱۱۶۹۳ ۔ لبابہ بنت ابی لبابہ الانصاریہ\n(1)انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، ان کا ذکر موجود ہے۔ ابن مندہ نے مختصراً ان کا ذکر کیا ہے، ابو نعیم نے موسیٰ بن عبیدہ ربذی کے طریق سے جو ایک ضعیف راوی ہیں، بحوالہ سعید بن جبیر جو مولی ابولبابہ ہیں، اور یعقوب بن زید سے، انہوں نے لبابہ سے روایت کی، فرماتی ہیں: میں ان کے ساتھ تھی، وہ فرماتے تھے: اس اللہ کے دشمن کی مشکیں کس دو! جس نے اللہ اور اس کے رسول صلی اللہ علیہ وسلم سے خیانت کی ہے۔ ان کے پاس سے ان کے بھائی گزرے اور کہا: اے میرے بھائی! میرے پاس آؤ۔ انہوں نے کہا: نہیں، اللہ کی قسم! میں تم سے بات نہیں کروں گا یہاں تک کہ تم سے اللہ اور اس کا رسول صلی اللہ علیہ وسلم راضی ہو؟ ان کے بارے میں رسول اللہ صلی اللہ علیہ وسلم نے پوچھا، انہوں نے کہا: وہ مسجد میں ہیں۔ لوگوں نے ان کے بارے میں آپ صلی اللہ علیہ وسلم کو بتایا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر وہ میرے پاس آتا تو میرے لیے اس کے بارے میں کوئی واقعہ ہوتا۔\"(2) پھر یہ آیت نازل ہوئی: اے مومنو! تم اللہ اور رسول (صلی اللہ علیہ وسلم) سے خیانت نہ کرو، اور اپنی امانتوں میں خیانت نہ کرو۔۔۔۔(3) اور دوسری آیت اور دوسرے جنہیں اللہ کے حکم کی امید ہے۔۔۔۔(4)","",{"fn":"(1) اسد الغابہ (۷۲۴۶) تجرید (۳۰۱/۲)\n(2) السیرۃ النبویۃ (۱۸۷/۳) دلائل النبوۃ (۱۶/۴)\n(3) سورۃ الانفال الآیۃ (۲۷)\n(4) سورۃ التوبۃ الآیۃ (۱۰۶)"}],[11655,"§۱۱۶۹۴ ۔ لبنی بنت ثابت\n(1)ابن منذر بن حزام انصاریہ خزرجیہ، سیدنا حسان رضی اللہ عنہ جو مشہور شاعر ہیں ان کی بہن ہیں، ابن سعد نے ذکر کیا ہے کہ انہوں نے اور ان کی بہن کبشہ نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، لبنی اوس بن ثابت کی سگی بہن تھیں۔","",{"fn":"(1) تجرید (۳۰۱/۲)"}],[11656,"§۱۱۶۹۵ ۔ لبنی بنت الخطیم الانصاریہ\n(1)اوسیہ، قیس بن خطیم کی جو شاعر ہیں، بہن ہیں، عبد قیس بن زید بن عامر ظفری کے نکاح میں تھیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، اور ابن سعد(2) کا قول ہے، ان کی والدہ ام قیس، قریبہ بنت قیس بن قدیم بن امیہ بن سنان، سلمیہ ہیں۔ ان سے عبداللہ بن نہیک بن اساف نے نکاح کیا، جس سے اولاد ہوئی، لبنی اسلام لائیں اور بیعت کی، ان کی بہن لیلیٰ کا ذکر عنقریب آئے گا۔","",{"fn":"(1) اسد الغابہ (۷۲۴۷) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۱۰۰/۸)"}],[11657,"§۱۱۶۹۶ ۔ لبنی بنت قیطی\n(1)ابن قیس بن لوذان بن ثعلبہ بن عدی بن مجدعہ بن حارثہ انصاریہ۔ ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۲/۲)\n(2) الطبقات الکبریٰ (۲۴۵/۸)"}],[11658,"§۱۱۶۹۷ ۔ لبینہ\nبنو مؤمل بن حبیب بن تمیم بن عبد اللہ بن قرط بن رزاح بن عدی بن کعب کی باندی ہیں، یہ ان کمزور لوگوں میں سے تھیں جنہیں عذاب دیا جاتا تھا، اور ان سات لوگوں میں سے ہیں جنہیں سیدنا ابو بکر رضی اللہ عنہ نے خریدا، ام عمیس میں ان کا ذکر آئے گا۔ اکثر روایات میں ان کا نام مذکور نہیں۔ بلاذری رحمہ اللہ نے بحوالہ ابوالبختری ان کا نام لیا ہے۔"],[11659,"§۱۱۶۹۸ ۔ لبیس بنت عمرو\n(1)ابن حرام انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے اور فرمایا: ان کی والدہ قراد بنت موہبہ بن عدی بن مجدعہ بن حازم ہیں، ان سے ابو ثابت بن عبد بن عبد عمرو بن قبطی نے نکاح کیا پھر قیس بن قیس بن لوذان کے نکاح میں آئیں۔","",{"fn":"(1) اسد الغابہ (۲۵۸/۶) تجرید (۳۰۱/۲)"}],[11660,"§۱۱۶۹۹ ۔ لبیسہ بنت عمرو الانصاریہ\n(1)ام عمارہ ہیں۔ طبرانی(2) نے حرف لام میں ان کا ذکر کیا ہے، اور ابن نقطہ نے اسی پر اعتماد کیا ہے، مشہور ہے کہ نون کے ساتھ ہے، اپنی کنیت سے مشہور ہیں، عنقریب ان کا ذکر آئے گا، بعض کا قول ہے: وہ لبیسہ ہیں، جو نسیبہ کے علاوہ ہیں وہ تو بنت حرب ہیں۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۷۲۴۸) (۲۵۸/۶) تجرید (۳۰۲/۲)\n(2) المعجم الکبیر (۳۰/۲۵)"}],[11661,"§۱۱۷۰۰ ۔ لہیمہ\n(1)سیدنا عمر بن خطاب رضی اللہ عنہ کی باندی اور ام ولد ہیں، اور ان کی صاحبزادی سیدہ حفصہ رضی اللہ عنہا کی خدمت کیا کرتی تھیں۔ ابن ماکولا(2) کا قول ہے: ام عبد الرحمن بن عمر ہیں، ان کی کنیت ابو شحمہ ہے، بعض کا قول ہے: ان کا نام نہیمہ ہے، مستغفری نے ان کا ذکر کیا اور فرمایا: انہیں شرف صحابیت حاصل ہے، ابراہیم بن موسیٰ بن تیم کی روایت سے منقول ہے، فرمایا: مجھ سے میرے چچا زکریا بن یحییٰ نے روایت کی، فرمایا: مجھ سے میرے بھتیجے ابن شہاب نے بحوالہ اپنے چچا روایت کی، فرماتے ہیں: مجھ سے اہل علم میں سے کچھ لوگوں نے روایت کی کہ سیدہ حفصہ رضی اللہ عنہا جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں، لہیمہ ام ولد سیدنا عمر رضی اللہ عنہ کو اس دن، جبکہ رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے، بھیجا اور کہا: آپ صلی اللہ علیہ وسلم میرے پاس سے تشریف لے گئے ہیں، اور کافی دیر ہو گئی ہے نہیں آئے۔ دیکھو وہ اپنی کس زوجہ کے پاس ہیں؟ سیدہ لہیمہ گئیں، اور آپ صلی اللہ علیہ وسلم کو سیدہ صفیہ رضی اللہ عنہا کے ہاں پایا، انہوں نے آ کر سیدہ حفصہ رضی اللہ عنہا کو بتایا، سیدہ حفصہ رضی اللہ عنہا کہنے لگیں: یہودیہ کے پاس بیٹھے ہیں۔ پھر لہیمہ کو حکم دیا کہ وہ سیدہ صفیہ رضی اللہ عنہا کے پاس جائیں، یہاں تک کہ نبی کریم صلی اللہ علیہ وسلم ان کے پاس سے تشریف لے جائیں، اور انہیں (صفیہ رضی اللہ عنہا) کو بتاؤ جو کچھ حفصہ نے کہا ہے، تو سیدہ صفیہ رضی اللہ عنہا نے فرمایا: اللہ کی قسم! میں حضرت ہارون رضی اللہ عنہ کی بیٹی ہوں اور میرے چچا حضرت موسیٰ علیہ السلام ہیں، اور میرے شوہر رسول اللہ صلی اللہ علیہ وسلم ہیں اور کوئی مجھ سے افضل نہیں، آپ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے تو وہ رو رہی تھیں۔ آپ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"تمہیں کیا ہوا؟\" انہوں نے آپ صلی اللہ علیہ وسلم کو بتایا جو انہیں لہیمہ نے حفصہ کے حوالے سے بتایا تھا، اور جو کچھ انہوں نے ان سے کہا، رسول اللہ صلی اللہ علیہ وسلم نے ان کی تصدیق کی۔ جب سیدہ حفصہ رضی اللہ عنہا نے یہ دیکھا تو فرمانے لگیں: اللہ کی قسم! میں سیدہ صفیہ رضی اللہ عنہا کو کبھی ایذاء نہیں دوں گی۔(3)","",{"fn":"(1) اسد الغابہ (۷۲۵۰) تجرید (۳۰۲/۲)\n(2) الاکمال (۸۳/۱)\n(3) جامع المسانید والسنن (۸۴/۱۶)"}],[11662,"§۱۱۷۰۱ ۔ لیلی بنت الاطنابہ\n(1)ابن منصور بن متی، انصاریہ، بنو شیلی سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا نام لیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۱) تجرید (۳۰۲/۲)"}],[11663,"§۱۱۷۰۲ ۔ لیلی بنت بلال\n(1)یا نبیل انصاریہ ابو لیلی کی بہن ہیں، اور عبدالرحمن بن ابو لیلی کی پھوپھی ہیں۔ ابو عمر(2) کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی اور آپ صلی اللہ علیہ وسلم سے روایت کی۔","",{"fn":"(1) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۸۱۰/۴)"}],[11664,"§۱۱۷۰۳ ۔ لیلی بنت ثابت\n(1)ابن منذر بن عمرو بن حرام، سیدنا حسان رضی اللہ عنہ کی بہن ہیں۔ ابن حبیب نے ان کا بھی ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۲) تجرید (۳۰۲/۲)"}],[11665,"§۱۱۷۰۴ ۔ لیلی بنت ابی حثمہ\n(1)ابن حذیفہ بن غانم بن عامر بن عبداللہ بن عبید بن عویج بن کعب بن لوی قرشیہ عدویہ، سیدنا سلیمان رضی اللہ عنہ کی بہن اور عامر بن ربیعہ عنبری کی زوجہ ہیں ان سے عبداللہ پیدا ہوئے، ابن سعد کا قول ہے: اسلام کے ابتدائی دور میں اسلام لائیں اور بیعت کی، اولین مہاجرات میں سے ہیں۔ حبشہ کی طرف دو ہجرتیں کیں، پھر مدینہ کی طرف ہجرت کی، بعض کا قول ہے: یہ پہلی مسافر خاتون ہیں جو ہجرت کر کے مدینہ آئیں، بعض نے کہا: ام سلمہ ہیں۔ ابن اسحاق نے یونس بن بکیر وغیرہ کی روایت سے جو ان سے مروی ہے، انہوں نے عبدالرحمن بن حارث سے، انہوں نے عبد العزیز بن عبد اللہ بن عامر بن ربیعہ سے، انہوں نے اپنی والدہ سے روایت کی، فرماتی ہیں: سیدنا عمر بن خطاب رضی اللہ عنہ ہمارے اسلام لانے کے بارے میں لوگوں میں سب سے زیادہ سخت تھے، جب ہم نے حبشہ کی سرزمین کی طرف نکلنے کا ارادہ کیا تو سیدنا عمر رضی اللہ عنہ ہمارے پاس آئے اور میں اپنے اونٹ پر تھی۔ انہوں نے پوچھا: اے ام عبداللہ! کہاں کا ارادہ ہے؟ میں نے کہا: تم لوگ ہمارے دین کی وجہ سے ہمیں ایذاء دیتے ہو، ہم اللہ کی زمین میں جائیں گے، انہوں نے کہا: اللہ تمہارا ساتھی ہو، پھر وہ چلے گئے، تو میرے پاس میرے شوہر عامر بن ربیعہ آئے، میں نے جب انہیں ان لوگوں کی بات بتائی تو وہ مجھے کہنے لگے: کیا تمہیں ان کے مسلمان ہونے کی امید ہے، پھر انہوں نے قصہ ذکر کیا۔(2) لیث بن سعد نے بحوالہ محمد بن عجلان روایت کیا ہے کہ عبداللہ بن عامر کے موالی میں سے ایک آدمی نے بحوالہ عبداللہ بن عامر روایت کیا، فرماتے ہیں: میری والدہ نے ایک دن مجھے بلایا اور رسول اللہ صلی اللہ علیہ وسلم ہمارے گھر میں تشریف فرما تھے، انہوں نے مجھ سے کہا: ادھر آؤ، میں تمہیں چیز دوں؟ ان سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: تم نے کیا چیز دینے کا ارادہ کیا تھا؟ انہوں نے کہا: میں نے اسے کھجور دی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اگر تم اسے کچھ نہ دیتی تو تمہارے نامہ اعمال میں ایک جھوٹ لکھا جاتا\"۔(3) اسے سراج نے بحوالہ بقیہ ان سے روایت کیا ہے اور لیث نے حیوۃ بن شریح اور یحییٰ بن ایوب، حاتم بن اسماعیل کی پیروی کی ہے اور بحوالہ یحییٰ بن ایوب جو مولی زیاد ہیں، اور وہ روایت ابن مندہ کے ہاں ان کے طریق سے مروی ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۳) الاستيعاب (۳۵۳۴) تجرید (۳۰۲/۲)\n(2) المعجم الکبیر (۴۷/۲۵) مجمع الزوائد (۲۴/۶) السیرۃ النبویۃ (۲۷۰/۱، ۲۷۱)\n(3) ابوداؤد (۴۴۹۱) مسند احمد (۴۴۷/۳) السنن الکبریٰ (۱۹۸/۱۰)"}],[11666,"§۱۱۷۰۵ ۔ لیلی بنت حکیم\n(1)انصاریہ اوسیہ۔ ابو عمر(2) کا قول ہے: ابو احمد بن صالح مصری نے ازواج النبی صلی اللہ علیہ وسلم میں ان کا ذکر کیا ہے۔ ان کے علاوہ اور کسی نے ان کا ذکر نہیں کیا۔ ابن اثیر(3) نے اسے جائز کہا ہے کہ یہ بعد والی ہوں، کیونکہ حکیم خطیم سے مشابہ ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۴) الاستيعاب (۳۵۳۵) تجرید (۳۰۲/۲)\n(2) الاستيعاب (۱۹۰۹/۴)\n(3) اسد الغابہ (۳۹۲/۵)"}],[11667,"§۱۱۷۰۶ ۔ لیلی بنت الخطیم\n(1)ابن عدی بن عمرو بن سواد بن ظفر انصاریہ اوسی، پھر ظفریہ ابو علی الجیانی نے استیعاب پر اپنے استدراک میں ان کا ذکر کیا ہے اور فرمایا: ابن ابی خیثمہ نے ان کا ذکر کیا ہے اور فرمایا: وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہا: میں لیلی بنت خطیم ہوں، میں آپ پر اپنا نفس پیش کرنے آئی ہوں، مجھ سے نکاح کر لیجئے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے ایسا کیا\"۔(2) پھر میں اپنی قوم کے پاس واپس گئی، وہ کہنے لگے: تم نے برا کیا، تو غیرت مند خاتون ہے جبکہ وہ صاحب ازواج ہیں۔ جاؤ ان سے خلع لے لو۔ وہ واپس آ کر کہنے لگی: میں اپنا معاملہ ختم کرنا چاہتی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے کر دیا\"۔ میں نے کہا: ابن سعد(3) نے بحوالہ ابن عباس رضی اللہ عنہما ایک سند سے جس میں کلبی بھی ہیں، یہ ذکر کیا ہے۔ انہوں نے ان سے زیادہ روایت کیا ہے، اس کے شروع میں ہے: لیلی بنت خطیم نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور آپ صلی اللہ علیہ وسلم سورج کی طرف اپنی کمر کئے ہوئے تھے۔ انہوں نے آپ صلی اللہ علیہ وسلم کے کندھے پر مارا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کون ہے؟ شیر کا لقمہ\" آپ اکثر یہ جملہ فرمایا کرتے تھے۔ اس کے آخر میں ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: میں نے معاملہ ختم کیا۔ فرماتے ہیں: ان سے مسعود بن اوس بن سواد بن ظفر نے نکاح کیا، اس سے اولاد ہوئی، بیان کیا گیا ہے کہ وہ مدینہ کے ایک باغ میں غسل کر رہی تھیں، ان پر اچانک ایک بھیڑیے نے حملہ کر دیا کافی زخمی ہو گئیں، کوئی پہنچ گیا لیکن وفات پا گئیں۔ پھر واقدی سے بحوالہ محمد بن صالح بن دینار، انہوں نے عاصم بن عمر بن قتادہ سے مسنداً نقل کیا ہے، فرماتے ہیں: لیلی بنت خطیم نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا تھا، آپ صلی اللہ علیہ وسلم نے انہیں قبول کر لیا۔ اپنے خاوندوں پر بڑے برے طریقے سے سوار ہوتی تھی بھی بد اخلاق، پھر اسی قصے کا مفہوم ذکر کیا، البتہ اس کے آخر میں اس کا تذکرہ نہیں کیا۔ انہوں نے اپنی روایت میں فرمایا کہ یہ کہنے لگیں: آپ اللہ کے نبی ہیں، اللہ نے آپ کے لیے (زیادہ) عورتیں حلال کی ہیں، میں زبان دراز عورت ہوں، سوکنوں کے بارے میں صبر نہیں کر سکتی اور آپ سے ہبہ واپس لے لیا۔ ابن ابی عون کے طریق سے ہے کہ لیلی نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا اور کئی عورتوں نے اپنے نفس نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیئے، یہ نہیں سنا گیا کہ نبی کریم صلی اللہ علیہ وسلم نے ان میں سے کسی کو قبول کیا ہو، فرماتے ہیں: ان کی والدہ اونچی حویلی والی بنت پیشہ بن حارث ہیں۔ ابن سعد رحمہ اللہ نے بحوالہ واقدی رحمہ اللہ اور میرا خیال ہے بحوالہ عاصم بن عمر بن قتادہ روایت کیا ہے، فرماتے ہیں: سب سے پہلے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والی ام سعد بن معاذ ہیں۔ وہ کبشہ بنت ابی رافع بن عبید، بنو ظفر سے لیلی بنت خطیم، بنو عمرو بن عوف سے لیلی، مریم اور سہیمہ جو ابو سفیان رضی اللہ عنہ کی بیٹیاں ہیں، انہیں ابوالبنات کہا جاتا تھا۔۔۔۔ (الحدیث) ابن سعد نے بھی روایت کیا ہے کہ مسعود بن اوس نے جاہلیت میں ان سے نکاح کیا، جس سے عمرہ اور عمیرہ پیدا ہوئے۔ انہیں شیر کا لقمہ کہا جاتا تھا، وہ پہلی خاتون تھیں، جنہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ان کے ساتھ ان کی دونوں بیٹیاں، ان کی دو نواسیاں بھی تھیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم کے لیے اپنے نفس کو ہبہ کر دیا، پھر بنو ظفر نے کہا: یہ ہبہ واپس کر دیں تو آپ نے یہ ہبہ واپس کر دیا۔","",{"fn":"(1) اسد الغابہ (۷۲۵۵) تجرید (۳۰۲/۲)\n(2) جامع المسانید والسنن (۸۷/۱۶)\n(3) الطبقات الکبریٰ (۱۰۸، ۱۰۷/۸)"}],[11668,"§۱۱۷۰۷ ۔ لیلی بنت رافع\n(1)ابن عمرو انصاریہ، ابو عبس بن حرب کی والدہ ہیں۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، فرماتے ہیں: ان کی والدہ ام البراء بنت سلمہ بن غزفطہ ہیں۔","",{"fn":"(1) تجرید (۳۰۲/۲)"}],[11669,"§۱۱۷۰۸ ۔ لیلی بنت ربعی\n(1)ابن عامر بن خالدہ انصاریہ، بنو بیاضہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۶) تجرید (۳۰۲/۲)"}],[11670,"§۱۱۷۰۹ ۔ لیلی بنت رئاب\n(1)ابن حنیف انصاریہ، بنو عوف بن خزرج سے ہیں۔ ابن حبیب نے بھی ان کا ذکر کیا ہے۔ عتبان بن مالک کی زوجہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۵۷) تجرید (۳۰۲/۲)"}],[11671,"§۱۱۷۱۰ ۔ لیلی بنت ابی سفیان\n(1)ابن حارث بن قیس بن زید بن امیہ، انصاریہ، اشہلیہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، لیلی بنت خطیم کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۹) تجرید (۳۰۲/۲)"}],[11672,"§۱۱۷۱۱ ۔ لیلی بنت سماک\nابن ثابت بن سفیان بن عدی بن عمرو بن امرئی القیس بن مالک آغر۔ ابن سعد نے بحوالہ واقدی روایت کیا ہے کہ وہ فرماتے ہیں: اسلام لائیں اور بیعت کی، فرماتے ہیں: ان کے علاوہ کسی اور نے ان کا ذکر نہیں کیا۔ میں کہتا ہوں: ام ثابت بنت قیس بن شماس کے سوانح میں آئے گا جو قیس کی بہن ہیں کہ ثابت بن سفیان سے ان کا بیٹا سماک پیدا ہوا، اس وجہ سے لیلی، ان کے والد سماک اور والدہ ام ثابت تینوں ترتیب وار صحابی تھے۔"],[11673,"§۱۱۷۱۲ ۔ لیلی بنت سماک\n(1)ابن ثابت بن سنان بن جشم بن عمرو بن امرئی القیس انصاریہ بن حارث بن خزرج سے ہیں، ابن حبیب نے بھی ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۰) تجرید (۳۰۲/۲)"}],[11674,"§۱۱۷۱۳ ۔ لیلی بنت طباۃ\n(1)ابن معیص انصاریہ۔ ابن سعد نے ان کا ذکر کیا ہے، تجرید میں اسی طرح ہے، فرماتے ہیں: ہوسکتا ہے یہ لیلی بنت اطنابہ پہلے والی ہوں جن کا نام لیلی ہے۔","",{"fn":"(1) تجرید (۳۰۲/۲)"}],[11675,"§۱۱۷۱۴ ۔ لیلی بنت عبادہ الانصاریہ\n(1)ساعدیہ، عبادہ بن عبادہ کی بہن ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۲) تجرید (۳۰۳/۲)"}],[11676,"§۱۱۷۱۵ ۔ لیلی بنت عبداللہ العدویہ\n(1)وہ شفاء ہیں، جن کا ذکر گزر چکا ہے۔ مستغفری نے بحوالہ ابن حبان ان کا نام لیا ہے۔","",{"fn":"(1) نسب قریش (۳۶۳) جمہرۃ انساب العرب (۱۵۰) اسد الغابہ (۳۹۳/۵)"}],[11677,"§۱۱۷۱۶ ۔ لیلی بنت عطارد\nابن حاجب تمیمیہ۔ عبداللہ بن ابی ربیعہ کی، جو صحابی ہیں، والدہ ہیں اور عبد الرحمن کی والدہ ہیں۔ زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[11678,"§۱۱۷۱۷ ۔ لیلی بنت قائف الثقفیہ\n(1)امام احمد رحمہ اللہ(2) اور ابوداؤد نے محمد بن اسحاق کے طریق سے بحوالہ نوح بن حکیم ثقفی ان کی حدیث نقل کی ہے، انہوں نے عروہ بن مسعود کی اولاد میں سے ایک آدمی سے جسے داؤد کہا جاتا ہے روایت کی، ام حبیبہ بنت ابی سفیان کے بیٹے تھے، انہوں نے لیلی بنت قائف سے روایت کی، انہوں نے ذکر کیا کہ وہ فرماتی ہیں: میں ام کلثوم بنت نبی کریم صلی اللہ علیہ وسلم کے غسل دینے والی عورتوں میں تھی۔ سب سے پہلے آپ صلی اللہ علیہ وسلم نے مجھے ان کے کفن میں سے ازار پھر قمیص، پھر اوڑھنی دی، پھر لفافہ، پھر ایک کپڑے میں کفن دے دیا گیا۔ (الحدیث) میں کہتا ہوں: داؤد جن کا تذکرہ ہے، ابن عاصم بن عروہ بن مسعود ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۶) الاستيعاب (۳۵۳۸) تجرید (۳۰۳/۲)\n(2) مسند احمد (۳۸۰/۶)"}],[11679,"§۱۱۷۱۸ ۔ لیلی بنت النضر العبدریہ\nحرف قاف میں قتیلہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11680,"§۱۱۷۱۹ ۔ لیلی بنت نہیک\n(1)بن اساف بن عدی بن زید بن جشم انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ براء کی بہن ہیں۔ ابن سعد(2) کا قول ہے: ان سے سہل بن ربیع بن عمرو بن عدی نے نکاح کیا، ان کی والدہ ام عبداللہ بن اسلم بن خریش بن مجدعہ ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۷) تجرید (۳۰۳/۲)\n(2) الطبقات الکبریٰ (۲۳۹/۸)"}],[11681,"§۱۱۷۲۰ ۔ لیلی بنت یسار\nمعقل بن یسار کی بہن کا ایک نام ہے۔ جن کے بارے میں آیت نازل ہوئی: تم انہیں روکو نہیں کہ اپنے شوہروں سے نکاح کریں۔(1) سہیلی نے مبہمات القرآن میں ان کا نام لیا ہے، اور منذری نے ان کی پیروی کی ہے۔ راجح یہی ہے کہ ان کا نام جمیل ہے جیسا کہ حرف جیم میں گزر چکا ہے۔","",{"fn":"(1) سورۃ البقرۃ الآیۃ (۲۳۲)"}],[11682,"§۱۱۷۲۱ ۔ لیلی السدوسیہ\n(1)بشیر بن خصاصیہ کی زوجہ ہیں، انہیں جہدمہ کہا جاتا تھا۔ بعض نے کہا کہ وہ ان کے علاوہ ہیں، جہدمہ میں اس کا بیان گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۵۸) الاستيعاب (۳۵۳۹) تجرید (۳۰۲/۲)"}],[11683,"§۱۱۷۲۲ ۔ لیلی بنت یعار\nیہ ایک ہیں جن کے بارے میں کہا گیا کہ انہوں نے سالم مولی ابو حذیفہ کو آزاد کیا۔"],[11684,"§۱۱۷۲۳ ۔ لیلی الغفاریہ\n(1)ابو عمر(2) کا قول ہے: نبی کریم صلی اللہ علیہ وسلم کے ساتھ غزوات میں شامل ہوئی تھیں، زخمیوں کا علاج کرتیں اور مریضوں کے پاس ٹھہرتی تھیں۔ ان کی حدیث ہے کہ نبی کریم صلی اللہ علیہ وسلم نے سیدہ عائشہ رضی اللہ عنہا سے فرمایا: \"یہ علی ہیں، لوگوں میں سب سے پہلے ایمان لانے والے\"۔(3) ان سے محمد بن قاسم طائی نے روایت کی۔ میں کہتا ہوں: پہلی روایت کے بارے میں حرف الف کی آخری قسم میں امامہ بنت ابی الحکم میں تنبیہ گزر چکی ہے۔ عقیلی نے موسیٰ بن قاسم کے سوانح میں جو ضعیف راوی ہیں، اور ابن مندہ نے علی بن ہاشم بن برید کی روایت سے نقل کیا ہے کہ مجھ سے میرے والد نے، فرماتے ہیں: ہم سے موسیٰ بن قاسم نے، فرماتے ہیں: مجھ سے لیلی غفاریہ نے روایت کی، فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ غزوات میں شریک ہوتی، زخمیوں کا علاج اور مریضوں کی تیمارداری کرتی تھی۔(4) جب سیدنا علی رضی اللہ عنہ بصرہ کی طرف نکلے اور میں آپ صلی اللہ علیہ وسلم کے ساتھ نکلی، جب میں نے سیدہ عائشہ رضی اللہ عنہا کو دیکھا تو ان کے پاس آئی اور کہا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم سے سیدنا علی رضی اللہ عنہ کی فضیلت میں کوئی حدیث سنی ہے؟ فرماتی ہیں: جی ہاں! وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے اور آپ صلی اللہ علیہ وسلم میرے پاس تھے، انہوں نے پرانی چادر اوڑھ رکھی تھی پھر وہ ہمارے درمیان بیٹھ گئے۔ میں نے کہا: تمہیں اس سے زیادہ کھلی جگہ نہیں ملی؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"اے عائشہ! میرے بھائی کو چھوڑ دو، وہ لوگوں میں سب سے پہلے اسلام لایا، اور آخری وقت میں میرا ساتھ دیا، اور قیامت کے دن سب سے پہلے مجھ سے ملے گا۔\" عقیلی کا قول ہے، یہ حدیث موسیٰ بن قاسم سے مروی ہے، اور بخاری رحمہ اللہ فرماتے ہیں: اس کی پیروی نہیں کی جائے گی۔ اس سند میں عبد السلام بن صالح، ابو الصلت ہیں۔ محدثین نے انہیں جھوٹا قرار دیا ہے، اور آخری روایت کے بارے میں تجرید میں ہے: وہ باطل ہے۔ میں کہتا ہوں: محمد بن قاسم، وہ طالیسکانی ہیں، طائی نہیں۔ اور وہ متروک راوی ہے، وہ موسیٰ بن قاسم کے علاوہ ہیں۔ اسی طرح کی روایت معاذہ سے مروی ہے۔ تفسیر ابن مردویہ میں ہے، اسے ابو موسیٰ نے اپنے طریق سے نقل کیا ہے، پھر یعلی بن عبید کی روایت سے بحوالہ حارث بن ابی رجال، انہوں نے عمرہ سے روایت کیا ہے، فرماتی ہیں: معاذہ غفاریہ فرماتی ہیں: میں نبی کریم صلی اللہ علیہ وسلم کی رفاقت میں تھی، آپ صلی اللہ علیہ وسلم کے ساتھ سفر میں نکلتی، مریضوں کی تیمارداری کرتی اور زخمیوں کا علاج کرتی تھی، میں سیدہ عائشہ رضی اللہ عنہا کے گھر میں رسول اللہ صلی اللہ علیہ وسلم کے پاس گئی، اور سیدنا علی رضی اللہ عنہ گھر سے باہر تھے، میں نے سنا آپ صلی اللہ علیہ وسلم سیدہ عائشہ رضی اللہ عنہا سے فرما رہے تھے: \"یہ مردوں میں مجھے سب سے زیادہ محبوب ہے، اور میرے نزدیک معزز ہے، اس کا حق پہچانو! اور اس کے مرتبے کا اکرام کرو۔۔۔۔\" (الحدیث) اس میں ہے: \"سیدنا علی رضی اللہ عنہ کو دیکھنا عبادت ہے۔\" میں کہتا ہوں: حارث ضعیف ہیں، یہ وہی حدیث ہے جس کی طرف ابو عمر نے اشارہ کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۵) الاستيعاب (۳۵۴۰) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۰/۴)\n(3) الضعفاء الکبیر (۱۷۳۷/۴)\n(4) المعجم الکبیر (۴۵/۲۵) مجمع الزوائد (۳۲۴/۵) جامع المسانید والسنن (۸۹/۱۶)"}],[11685,"§۱۱۷۲۴ ۔ لیلی\n(1)عبد الرحمن بن ابی لیلی کی پھوپھی ہیں، لیلی بنت بلال میں تذکرہ ہوا ہے۔ ابی لیلی کے سوانح میں گزر چکا ہے کہ ان کے اور ان کے والد کے نام میں بہت زیادہ اختلاف ہے، صحیح یہ ہے کہ ان کے والد کا نام بلال یا بلیل ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۴) الاستيعاب (۳۵۳۷) تجرید (۳۰۲/۲)"}],[11686,"§۱۱۷۲۵ ۔ لیلی\n(1)سیدہ عائشہ رضی اللہ عنہا کی مولاۃ ہیں، ابو عمر(2) کا قول ہے: ان کی حدیث کی اسناد قائم نہیں، ان سے ابو عبداللہ مدنی نے روایت کی اور وہ مجہول راوی ہے۔ میں کہتا ہوں: مستغفری نے عبد الکریم النجار کے طریق سے ابی عبداللہ مدنی سے بحوالہ سیدہ عائشہ رضی اللہ عنہا ان کی دربان اور مولاۃ نقل کیا ہے، فرماتی ہیں، میں نے کہا: یا رسول اللہ صلی اللہ علیہ وسلم! آپ قضائے حاجت کے لیے تشریف لے جاتے ہیں، میں آپ کے بعد جاتی ہوں، میں وہاں کچھ نہیں دیکھتی البتہ مشک کی خوشبو پاتی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ہم انبیاء کی جماعت کے اجسام اہل جنت کی ارواح پر پلتے بڑھتے ہیں، ہمارے جسموں میں سے جو چیز(3) نکلے زمین اسے نگل لیتی ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۶۱) الاستيعاب (۳۵۳۹) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۰/۴)\n(3) جامع المسانید والسنن (۹۱/۱۶)"}],[11687,"§۱۱۷۲۶ ۔ لیلی\n(1)ان سے حبیب بن زید نے روایت کی ہے ابو یعلیٰ نے تجرید سے ان کی حدیث لی ہے۔","",{"fn":"(1) تجرید (۳۰۳/۲)"}],[11688,"§۱۱۷۲۷ ۔ لینہ\nجزء بن دیزیل صغیر میں ان کی حدیث ہے۔"],[11689,"§۱۱۷۲۸ ۔ لینہ\nقباء کی جگہ کی مالکن ہیں: عمر بن شبہ نے اخبار مدینہ میں صحیح سند سے، جسے وہ عروہ تک لے گئے ہیں نقل کیا ہے، فرماتے ہیں: مسجد قباء کی جگہ لینہ نامی ایک خاتون کی ملکیت تھی، وہ وہاں اپنا گدھا باندھتی تھیں، سعد بن خیثمہ نے اس میں مسجد بنائی تو مسجد ضرار والے کہنے لگے، کیا ہم لینہ کے گدھے کے اصطبل میں نماز پڑھیں؟ اللہ کی قسم نہیں، ہم ایک علیحدہ مسجد بنائیں گے اور اس میں نماز پڑھیں گے یہاں تک کہ ابو عامر آ کر ہماری امامت کروائیں اس بارے میں اللہ تعالیٰ نے یہ آیت نازل فرمائی: \"وہ لوگ جنہوں نے مسجد ضرار بنائی۔۔۔۔\"(1) الآیۃ","",{"fn":"(1) سورۃ التوبۃ الآیۃ (۱۰۷)"}],[11690,"§۱۱۷۲۹ ۔ لیلی بنت الجودی\nابن عدی بن عمرو بن ابی عمرو، غسانی، عبد الرحمن بن ابو بکر صدیق کی زوجہ ہیں، انہوں نے نبوت کا زمانہ پایا، انہوں نے انہیں جاہلیت میں دیکھا تھا، انہیں پسند آئیں، جب دمشق فتح ہوا تو وہ وہاں گئیں، انہیں ان کی طرف رغبت تھی، جو ایک طویل قصے میں ہے، زبیر بن بکار نے ان کے سوانح میں ان کا ذکر کیا ہے۔ فرمایا: وہ تجارت کے لیے دمشق آئے، اور انہیں چٹائی پر بیٹھے دیکھا، اور ان کے گرد لڑکیاں تھیں، جب ان لوگوں نے شام میں جہاد کیا تو سیدنا عمر رضی اللہ عنہ نے ان کی طرف خط لکھا، میں نے عبد الرحمن بن ابو بکر کو غنیمت میں لیلی بنت جودی دی، جب انہوں نے ان کو قیدی بنایا تو انہیں دے دیا، وہ انہیں لے کر مدینہ آئے، سیدہ عائشہ رضی اللہ عنہا فرماتی ہیں: ان کی محبت ان کے دل میں گھر کر گئی تھی اور جب میں انہیں ملامت کرتی تھی تو وہ کہتے: اے میری بہن! مجھے چھوڑ دو، میں اس کے دانتوں سے انار کے دانے چوستا ہوں، کافی عرصہ گزر گیا، میں ان سے اس بارے میں گفتگو کرتی تھی، ان کا اس پر یہ احسان تھا کہ انہیں ان کے گھر والوں کی طرف لوٹا دیا، میں ان سے کہتی: تم نے محبت کی تو انتہا کی، اور نفرت کی تو انتہا کی، ان کے بارے میں عبد الرحمن کے مشہور اشعار ہیں: \"میں لیلی کو یاد کرتا جبکہ ہمارے درمیان گھر کا چھجہ (سقیفہ) تھا۔ جودی کی بیٹی لیلی اور مجھے کیا ہوا۔\" زبیر کی روایت میں اسی طرح مذکور ہے۔ عمر بن شبہ کی روایت میں بحوالہ صلت بن مسعود، انہوں نے احمد بن شبویہ سے، انہوں نے سلیمان بن صالح سے، انہوں نے ابن مبارک سے، انہوں نے مصعب بن ثابت سے، انہوں نے عروہ بن زبیر سے روایت کیا ہے: ابو بکر نے انہیں غنیمت میں یہ عطا کیں۔ ہم نے امالی المحاملی کے جزء تاسع کے آخر میں اہل بغداد کی ان سے روایت سے اپنی سند کے ساتھ جسے وہ ابن ابی زناد تک لے گئے ہیں، بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے روایت کیا ہے کہ عبد الرحمن بن ابو بکر اپنے والد کی خلافت کے آخری ایام میں، اسلام کے ابتدائی سالوں میں دمشق آئے، انہوں نے لیلی بنت جودی کو دیکھا، انہوں نے ان سے خوبصورت عورت نہیں دیکھی، اور ان کے بارے میں یہ شعر کہا: میں نے لیلی کو یاد کیا۔۔۔۔ اشعار سیدنا عمر رضی اللہ عنہ نے اپنے عامل کی طرف لکھا: اگر تمہیں اللہ تعالیٰ دمشق پر فتح دیں تو جودی کی بیٹی کو عبد الرحمن کے سپرد کر دینا، انہوں نے ان کے سپرد کر دیا، وہ انہیں لے کر آئے اور اپنے خاندان کی خواتین کے پاس چھوڑا پھر روایت ذکر کی، اس میں ان کا یہ قول بھی ہے گویا میں اس کے دانتوں سے انار کے دانے چوستا ہوں، فرماتی ہیں: انہوں نے کوئی ایسا کام کیا کہ ان کے دانت گر گئے تو انہیں چھوڑ دیا پھر ان کے گھر والوں کی طرف لوٹا دیا۔ یہ اس روایت کے آخری الفاظ ہیں، یہ محاملی کی آخری مجلس تھی، جس میں انہوں نے املاء کروائی۔"],[11691,"§۱۱۷۳۰ ۔ لیلی بنت حابس التمیمیہ\nاقرع بن حابس کی بہن ہیں، جو مشہور صحابی ہیں۔ غالب بن صعصعہ بن معاویہ کی والدہ ہیں، جو مشہور شاعر فرزدق کے والد ہیں: انہوں نے نبوت کا زمانہ پایا، فرزدق نے اپنے والد کے مرثیہ میں ان کا ذکر کیا ہے، کہتے ہیں: \"صبر اس بات سے انکاری ہے کہ میں طلوع ہوتے بدر اور سورج کو نہ دیکھوں، جب دیکھتا ہوں تو مجھے غالب کی یاد دلاتے ہیں۔ دونوں ابن لیلی کے مشابہ تھے جو ابن لیلی کے مشابہ ہوگا ستاروں کی روشنی میں داخل ہو جائے گا۔\""],[11692,"§۱۱۷۳۱ ۔ لیلی بنت حکیم\n(1)ابن اثیر کا کلام گزر چکا ہے، انہوں نے کہا ہے کہ ممکن ہے کہ بنت خطیم ہوں، یوں ان سے لفظی غلطی ہوئی۔ جہاں تک مجھے معلوم ہوا ہے یہ یہی لیلی بنت حکیم ہی ہیں۔ واللہ اعلم","",{"fn":"(1) اسد الغابہ (۷۲۵۴)، تجرید (۳۰۲/۲)"}],[11693,"§۱۱۷۳۲ ۔ الماردہ\nحکیم بن حزام کی حدیث میں ان کا ذکر ہے، جو مسند ابی یعلیٰ میں ہے، بعض کا قول ہے: المرادیہ"],[11694,"§۱۱۷۳۳ ۔ ماریہ القبطیہ\n(1)رسول اللہ صلی اللہ علیہ وسلم کی ام ولد ہیں، ابن سعد(2) نے عبداللہ بن عبد الرحمن بن ابی صعصعہ کے طریق سے ذکر کیا ہے فرماتے ہیں: اسکندریہ کے بادشاہ مقوقس نے ۷ھ میں رسول اللہ صلی اللہ علیہ وسلم کے پاس سیدہ ماریہ، ان کی بہن سیرین، ہزار مثقال سونا، بیس ملائم کپڑے، دلدل نامی خچر، اور عفیر نامی گدھا بھیجا، بعض نے کہا: یعفور، ان کے ساتھ ایک خصی تھا جسے مابور کہا جاتا تھا۔ وہ بہت بوڑھا اور سیدہ ماریہ کا بھائی تھا، یہ تمام چیزیں حاطب بن ابی بلتعہ کے ساتھ بھیجیں، حاطب بن ابی بلتعہ نے ماریہ پر اسلام پیش کیا اور اس کی ترغیب دی، انہوں نے اور ان کی بہن نے اسلام قبول کر لیا، جبکہ خصی اپنے دین پر رہا، بعد میں وہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں اسلام لے آیا، سیدہ ماریہ رضی اللہ عنہا سفید رنگت اور خوبصورت تھیں، رسول اللہ صلی اللہ علیہ وسلم نے انہیں مدینہ کے بالائی حصہ میں ٹھہرایا، جو اس مال میں تھا جسے سریہ(3) ام ابراہیم کہا جاتا تھا آپ وہیں ان کے پاس آتے جاتے باندی ہونے کی وجہ سے ان سے شب باشی کرتے۔ (اگر چہ وہ آپ کی باندی تھیں لیکن ان سے آزاد عورتوں کی طرح سلوک کرتے یہی وجہ ہے کہ) ان پر پردہ لازم کر دیا، وہاں ان کے ہاں ذی الحجہ ۸ھ میں رسول اللہ صلی اللہ علیہ وسلم کے صاحبزادے کی ولادت ہوئی۔ عمرہ کے طریق سے بحوالہ عائشہ مروی ہے۔ فرماتی ہیں: ماریہ کے علاوہ کسی عورت کو مجھ سے زیادہ مقام نہیں ملا۔ یہ اس لیے کہ وہ بہت حسین و جمیل تھیں، اس لیے رسول اللہ صلی اللہ علیہ وسلم کو پسند تھیں پہلے پہل جب آپ تشریف لائے تو سیدنا حارثہ بن نعمان کے گھر انہیں ٹھہرایا۔ وہ ہمارے پڑوس میں تھیں، آپ صلی اللہ علیہ وسلم دن اور رات کے اکثر اوقات ان کے پاس رہتے، یہاں تک کہ ہمیں خدشہ ہونے لگا، یہاں تک کہ میں جزع فزع کرنے لگی تو آپ صلی اللہ علیہ وسلم نے انہیں مدینے کے بالائی حصے میں منتقل کر دیا وہیں آپ کا آنا جانا ہوتا، یہ بھی ہمیں گراں گزرتا۔ مسند میں بحوالہ واقدی مروی ہے، سیدہ ماریہ رضی اللہ عنہا حجرے کے پاس حاضر ہونے والوں میں سے تھیں۔ بلاذری کا قول ہے: سیدہ ماریہ رضی اللہ عنہا کی والدہ رومی تھیں اور سیدہ ماریہ سفید رنگت، گھنگریالے بالوں والی حسن و جمیل تھیں۔ بزار نے حسن سند سے بحوالہ عبداللہ بن بریدہ انہوں نے اپنے والد سے نقل کیا ہے، فرماتے ہیں: قبط کے امیر نے رسول اللہ صلی اللہ علیہ وسلم کو دو لونڈیاں اور ایک خچر ہدیہ دیا، آپ صلی اللہ علیہ وسلم مدینہ میں خچر پر سوار ہوتے تھے اور دونوں لونڈیوں میں سے ایک کو اپنے لیے مخصوص کر لیا، ان کے بیٹے ابراہیم کے سوانح میں ان کا ذکر گزر چکا ہے، مابور نصیبی کے سوانح اور صالح کے سوانح میں بھی ان کا تذکرہ ہے۔ واقدی کا قول ہے: مجھ سے موسیٰ بن محمد بن ابراہیم نے بحوالہ اپنے والد روایت کیا ہے، فرماتے ہیں: سیدنا ابو بکر رضی اللہ عنہ سیدہ ماریہ رضی اللہ عنہا کو خرچ بھیجتے تھے، یہاں تک کہ ان کی وفات ہو گئی پھر سیدنا عمر رضی اللہ عنہ انہیں خرچ بھیجتے یہاں تک کہ ان کی خلافت میں وہ وفات پا گئیں۔ واقدی کا قول ہے: محرم ۱۶ھ میں فوت ہوئیں، سیدنا عمر رضی اللہ عنہ ان کے جنازے کے لیے لوگوں کو جمع کر رہے تھے، اور ان پر بقیع میں نماز جنازہ پڑھی، ابن مندہ کا قول ہے: سیدہ ماریہ رضی اللہ عنہا نبی کریم صلی اللہ علیہ وسلم کی وفات کے پانچ برس بعد فوت ہوئیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۸)، الاستيعاب (۳۵۴۳)، تجرید (۳۰۳/۲)\n(2) الطبقات الکبریٰ (۱۵۳/۸، ۱۵۶)\n(3) السیر والمغازی (۲۷۱)"}],[11695,"§۱۱۷۳۴ ۔ ماریہ\n(1)نبی کریم صلی اللہ علیہ وسلم کی خادمہ تھیں، ابو عمر(2) کا قول ہے: ان کی کنیت ام رباب تھی، اہل بصرہ کے پاس ان کی حدیث ہے کہ وہ نبی صلی اللہ علیہ وسلم کے لیے جھکیں یہاں تک کہ آپ ان کا سہارا لے کر دیوار پر چڑھے جس رات مشرکوں سے آپ جان بچا کر نکلے تھے۔ میں کہتا ہوں: اسے ابن مندہ نے یعلی بن اسد کے طریق سے بحوالہ عبداللہ بن حبیب، انہوں نے ام سلیمان سے، انہوں نے اپنی والدہ سے، انہوں نے ان کی دادی ماریہ سے روایت کی، فرماتی ہیں: وہ نبی کریم صلی اللہ علیہ وسلم کے لیے جھکیں۔۔۔۔ پھر حدیث ذکر کی۔ ان کے لیے یہ عنوان قائم کیا، ماریہ، نبی کریم صلی اللہ علیہ وسلم کی باندی۔ میں کہتا ہوں: آگے آئے گا کہ ان کی والدہ کا نام مرضیہ ہے اور یہ کہ وہ صحابیہ ہیں، رہیں ام سلیمان تو مجھے ان کا نام معلوم نہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۶۹) الاستيعاب (۳۵۴۲) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۳/۴)"}],[11696,"§۱۱۷۳۵ ۔ ماریہ\n(1)نبی کریم صلی اللہ علیہ وسلم کی خادمہ ہیں۔(2) ان سے ایک حدیث منقول ہے، جو اہل کوفہ کے ہاں ہے۔ اسے ابوبکر بن عیاش نے بحوالہ مثنی بن صالح، انہوں نے ان کی دادی ماریہ سے روایت کیا ہے، فرماتی ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم سے مصافحہ کیا، میں نے(3) آپ کی ہتھیلی مبارک سے زیادہ ملائم کسی کا ہاتھ نہیں دیکھا۔ ابو عمر نے ان سے پہلے والی میں فرمایا: مجھے معلوم نہیں، وہ یہی ہیں یا اس کے علاوہ ہیں؟ میں کہتا ہوں: انہوں نے یہ ساری بات ابن سکن کے کلام سے لی ہے۔ ابن سکن کا قول ہے: ماریہ نبی کریم صلی اللہ علیہ وسلم کی مولاۃ، ان سے حدیث مروی ہے جو اہل کوفہ سے منقول ہے، مجھے معلوم نہیں کہ ان سے ابن عباس کے علاوہ کسی نے روایت کی ہو، پھر اسے دو طریق سے ان کے حوالے سے حدیث روایت کی، پھر فرماتے ہیں: سیدہ ماریہ سے ایک اور حدیث مروی ہے، بصریوں نے اسے روایت کیا ہے، مجھے معلوم نہیں کیا یہ وہی ہیں جن کی حدیث ابوبکر نے روایت کی یا ان کے علاوہ ہیں؟ پھر یعلی بن اسد کے طریق سے بحوالہ محمد بن حمران، انہوں نے عبداللہ بن حبیب سے، انہوں نے ام سلیمان سے، انہوں نے اپنی والدہ سے، انہوں نے اپنی دادی ماریہ سے حدیث روایت کی، فرماتی ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے لیے جھکی یہاں تک کہ آپ دیوار کے اوپر چڑھ گئے جس رات مشرکین سے جان بچا کر نکلے تھے۔ ابونعیم کا قول ہے: ابن مندہ نے ان کا علیحدہ ذکر کیا ہے، حالانکہ وہ دونوں میرے نزدیک ایک ہیں۔ میں کہتا ہوں: ابن مندہ نے اسے دو طریق سے موصولاً ذکر کیا ہے، بحوالہ ابوبکر بن عیاش، ابو عمر کے قول کے مطابق ان میں سے ایک یہ ہیں، بحوالہ مثنی بن صالح، انہوں نے اپنی دادی سے روایت کیا ہے، اور دوسرا طریق یہ ہے: بحوالہ ابوبکر، فرماتے ہیں: اللہ کی قسم! ہم سے محمد بن مثنی بن صالح نے بحوالہ اپنی دادی روایت کیا ہے۔ واللہ اعلم! ابو عمر کا قول ہے، مثنی بن صالح اور وہ ابن مہران مولی عمرو بن حریث ہے، اسی طرح فرمایا۔","",{"fn":"(1) اسد الغابہ (۷۲۷۰) الاستيعاب (۳۵۴۱) تجرید (۳۰۳/۲)\n(2) الاستيعاب (۱۹۱۳/۴)\n(3) المعجم الکبیر (۷۷/۲۵) جامع المسانید والسنن (۹۶/۱۶)"}],[11697,"§۱۱۷۳۶ ۔ ماریہ\n(1)یا ماویہ، راویوں نے بحوالہ ابن اسحاق ان میں اختلاف کیا ہے، یونس بن بکیر وغیرہ نے ان کے حوالے سے کہا ہے: ماویہ واؤ کے ساتھ ہے، انہوں نے خبیب بن عدی کے قصہ میں ذکر کیا ہے، جب مشرکوں نے بئر معونہ کے قصے میں انہیں قیدی بنا لیا تھا، اور بیڑیاں پہنا کر انہیں قتل کرنے لگے۔ ابن اسحاق(2) کا قول ہے: مجھ سے عبداللہ بن ابی نجیح نے بحوالہ ماریہ مولاۃ حجیر بن ابی اہاب روایت کی، فرماتی ہیں: مکہ میں خبیب کو میرے گھر میں قید کیا گیا، میں نے ایک دن جھانکا تو ان کے ہاتھ میں ان کے سر سے بڑا انگور کا گچھا تھا، جس میں سے وہ کھا رہے تھے، حالانکہ اس وقت انگور کا موسم نہیں تھا۔ میں کہتا ہوں: یہ بخاری رحمہ اللہ نے صحیح میں خبیب کی شہادت کے قصہ میں بیان کیا ہے، لیکن ان کی روایت میں یہ نہیں: ان کے سر سے بڑا تھا۔ انہوں نے اپنی روایت میں فرمایا: مکہ میں اس وقت اور یہی مراد ہے، گویا انہوں نے مطلق زمین کہا اور مکہ کی سرزمین مراد لی۔ ابو عمر(3) نے بحوالہ عقیلی ان کی سند سے جسے وہ عبداللہ بن اورلین اودی تک لے گئے ہیں، بحوالہ محمد بن اسحاق ذکر کیا، وہ فرماتے ہیں کہ مجھ سے ابن نجیح نے حدیث بیان کی کہ انہوں نے بحوالہ ماریہ مولاۃ حجیر حدیث بیان کی اور اسے راء اور تخفیف کے ساتھ ذکر کیا کہ سیدنا خبیب بن عدی کو جب ان کے گھر میں قید کیا گیا، وہ اسلام لانے کے بعد بیان کرتی ہیں، فرماتی ہیں: اللہ کی قسم! انہیں میرے گھر میں قید کیا گیا، جس کا دروازہ بند تھا، جب دروازے کی رون سے میں نے جھانکا تو ان کے ہاتھ آدمی کے سر کی طرح انگور کا گچھا تھا، جس میں سے وہ کھا رہے تھے، اس وقت زمین پر انگور نہیں تھے۔ جب ان کے قتل کا وقت آیا تو انہوں نے فرمایا: اے ماریہ! مجھے کوئی تیز دھار چیز دو، جس سے صفائی کروں۔ فرماتی ہیں: میں نے اپنے ایک لڑکے کو استرا دیا اور اس سے کہا کہ یہ اس کے پاس لے جاؤ، جب وہ اس کے پاس گیا تو میں نے دل میں کہا کہ اس لوہے کے ذریعے اس لڑکے کو قتل کرنے سے اس شخص کو اپنا بدلہ مل جائے گا، تا کہ مرد کے بدلے مرد ہو جائے، تو وہ کہنے لگے مجھے اپنی زندگی کی قسم! تمہاری ماں کو جو خدشہ ہو رہا ہے اس کی ضرورت نہیں، جب اس نے استرے کے ساتھ میرے پاس بھیجا، یعنی تمہارے ساتھ، پھر اسے چھوڑ دیا۔ یہ قصہ بخاری میں بھی ہے۔ ابن سعد رحمہ اللہ(4) نے بحوالہ واقدی رحمہ اللہ یہ اسے ذکر کیا ہے، انہوں نے اہل علم میں سے کئی راویوں سے اسے نقل کیا، اس میں ہے: انہوں نے انہیں، ان کے گھر قید کیا، تا کہ حرمت والا مہینہ گزر جائے تو انہیں قتل کریں۔ وہ اسلام لانے کے بعد ان کا قصہ بیان کرتی تھیں، جبکہ ان کا اسلام سنور چکا تھا، اس میں ہے: وہ تہجد کی نماز میں قرآن پڑھتے تھے، جب عورتوں نے اسے سنا تو رونے لگیں اور انہیں ان پر رحم آگیا تو میں نے ان سے پوچھا: تمہاری کوئی حاجت ہے؟ انہوں نے فرمایا: نہیں! سوائے اس کے کہ مجھے میٹھا پانی پلاؤ، جو بتوں کے پاس ذبح کیا جائے مجھے نہ کھانے کو دو، اور جب وہ مجھے قتل کرنے کا ارادہ کریں تو مجھے خبر دینا، جب ان لوگوں نے انہیں قتل کرنے کا ارادہ کیا تو میں نے انہیں اس کی خبر دی، اللہ کی قسم! انہیں اس کا مطلق خوف نہ ہوا۔ انہوں نے کہا: میرے لیے استرا بھیج دینا، جس سے پاکیزگی حاصل کروں۔ میں نے اپنے بیٹے ابو حسین کے ہاتھ ان کے پاس استرا بھیجا، وہ انہیں دودھ پلاتی تھیں، وہ ان کا اپنا بیٹا نہیں تھا۔ پھر انہوں نے پہلے کی طرح ذکر کیا، اس میں ہے: میں اسے قتل کرنے والا نہیں ہوں اور ہمارے دین میں دھوکہ کرنا جائز نہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۷۱) تجرید (۳۰۳/۲)\n(2) السیرۃ النبویۃ (۱۳۶/۳، ۱۳۷)\n(3) الاستيعاب (۱۹۱۱/۴)\n(4) الطبقات الکبریٰ (۲۶۱/۸)"}],[11698,"§۱۱۷۳۷ ۔ محبہ بنت الربیع\n(1)بن عمرو بن ابی زہیر انصاریہ۔ بنو حارث بن خزرج سے ہیں۔ ابن سعد(2) رحمہ اللہ اور ابن حبیب نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ سعد بن ربیع کی بہن ہیں، ان سے ابودرداء عامر بن زید بن قیس انصاری خزرجی نے نکاح کیا، جس سے بلال پیدا ہوئے، ان کی والدہ کا نام ہریلہ بنت مکتبہ بن عمرو بن حدیج بن عامر بن بشم ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۲) تجرید (۳۰۳/۲)\n(2) الطبقات الکبریٰ (۲۶۱/۸)"}],[11699,"§۱۱۷۳۸ ۔ محجنہ\n(1)بعض کا قول ہے: ام مجن، حبشی خاتون تھیں، اور مسجد میں جھاڑو دیتی تھیں، صحیح میں بغیر نام لیے ان کا تذکرہ کیا ہے، یحییٰ بن ابی انیسہ نے ان کا نام لیا ہے، اور وہ متروک راوی ہیں، بحوالہ علقمہ بن مرثد، انہوں نے اہل مدینہ کے ایک آدمی سے روایت کی، فرماتے ہیں: اہل مدینہ میں سے ایک خاتون جنہیں مجنہ کہا جاتا تھا، مسجد کی صفائی کرتی تھیں، نبی کریم صلی اللہ علیہ وسلم نے انہیں نہ پایا تو پوچھا، لوگوں نے بتایا کہ وہ فوت ہو گئی ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے مجھے خبر کیوں نہ دی؟\"(2) آپ صلی اللہ علیہ وسلم تشریف لے گئے، ان کی نماز جنازہ پڑھی اور چار تکبیریں کہیں۔ یحییٰ کا قول ہے: ہم سے زہری رحمہ اللہ نے بحوالہ ابو امامہ بن سہل انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہی حدیث روایت کی۔ عبداللہ بن بریدہ کے طریق سے بحوالہ ان کے والد روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم ایک قبر سے گزرے جس کی تازی تازی تدفین ہوئی تھی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے کب دفن کیا گیا؟\" لوگوں نے کہا: یہ ام مجن ہے۔ جو مسجد سے خس و خاشاک شوق سے اٹھاتی تھیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے مجھے کیوں نہ بتایا؟\" کہنے لگے: آپ صلی اللہ علیہ وسلم سوئے ہوئے تھے، ہم نے آپ کو بیدار کرنا پسند نہ کیا۔ (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۲۷۳) تجرید (۳۰۳/۲)\n(2) بخاری (۴۶۰) (۱۳۳۶)"}],[11700,"§۱۱۷۳۹ ۔ محیاۃ بنت خالد\n(1)بن سنان عبسی۔ ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، اور محمد بن عمر رازی حافظ کے طریق سے بحوالہ عمرو بن اسحاق بن علاء، انہوں نے ابراہیم بن علاء سے وہ فرماتے ہیں کہ ہم سے ابومحمد قریشی، ہاشمی نے بحوالہ ہشام بن عروہ، انہوں نے ابن عمارہ سے، انہوں نے اپنے والد عمارہ بن حزن بن شیطان سے خالد بن سنان کے قصے میں روایت کیا، فرماتے ہیں: جب اللہ تعالیٰ نے آپ صلی اللہ علیہ وسلم کو مبعوث فرمایا تو آپ صلی اللہ علیہ وسلم کے پاس محیاۃ بنت خالد آئیں، اور اپنا نسب بیان کیا۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے اپنی چادر بچھائی اور انہیں اس پر بٹھایا، فرمایا: \"میری بھتیجی! اور اس نبی کی بیٹی جسے اس کی قوم نے ضائع کر دیا۔\"(2) ابن کلبی کی روایت میں ان کا نام منقول ہے، فرماتے ہیں: میرے والد نے فرمایا: اور مجھے ابن ابی عمارہ نے خبر دی، فرماتے ہیں: ہمارے پاس خالد بن سنان آئے اور فرمایا: اے بنو عبس کی جماعت! اللہ تعالیٰ نے مجھے اس آگ کے بجھانے کا حکم دیا ہے، میرے والد نے کہا: اور میرے والد ان کے ساتھ گئے تھے، پھر طویل قصہ ذکر کیا۔ حدیث کے آخر میں ہے، ہشام بن محمد فرماتے ہیں: محیاۃ بنت خالد بن سنان نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میری بھتیجی کو خوش آمدید! اور اس نبی کی بیٹی جسے اس کی قوم نے ضائع کر دیا، میں نے خالد بن سنان کے سوانح میں آگ بجھانے کا قصہ بہت سے طرق سے ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۴) تجرید (۳۰۴/۲)\n(2) اسد الغابہ (۳۹۵/۵)"}],[11701,"§۱۱۷۴۰ ۔ محیاۃ بنت ابی نائلہ\n(1)سلکان بن سلامہ بن وقش اشہلیہ، ابن سعد(2) نے ان کا ذکر کیا ہے اور فرمایا: اسلام لائیں اور بیعت کی، یہ ابن عمارہ کی روایت میں ہے، واقدی رحمہ اللہ کا قول ہے: یہ عبادہ ہیں جن کا ذکر حرف عین میں گزر چکا ہے۔","",{"fn":"(1) تجرید (۳۰۴/۲)\n(2) الطبقات الکبریٰ (۲۳۵/۸)"}],[11702,"§۱۱۷۴۱ ۔ مرضیہ\n(1)ابن ابی عاصم نے کتاب الوحدان میں ان کا ذکر کیا ہے، اور بحوالہ ابی حفص صیرفی مسنداً ذکر کیا ہے، انہوں نے محمد بن راشد سے، انہوں نے محمد بن حمران سے، انہوں نے عبداللہ بن حبیب سے، انہوں نے ام سلیمان سے، انہوں نے اپنی والدہ مرضیہ سے روایت کیا ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم کے زمانے میں جو کام کیا جاتا تھا، میں دیکھتی ہوں کہ تم اسے ناپسند کرتے ہو، میں نے دیکھا کہ میت کے پیچھے دھونی دی جاتی ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۲۷۵) تجرید (۳۰۴/۲)\n(2) الاحاد والمثانی (۲۶۱/۶)"}],[11703,"§۱۱۷۴۲ ۔ مریم بنت ایاس الانصاریہ\n(1)مدنیہ۔ ان سے عمرو بن یحییٰ مازنی نے روایت کی۔ ابو عمر(2) کا یہی قول ہے، وہ انصاریہ ہیں، ایسا نہیں، بلکہ وہ کیتھیہ، بنت ایاس بن بکیر ہیں۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے، وہ صحابہ کا گھرانہ ہے۔ ان کے والد اور بچے بدر میں حاضر ہوئے، وہ بنو عدی کے حلیف تھے، مسند احمد اور نسائی میں عمرو بن یحییٰ مازنی کی ان سے صحیح سند سے روایت ہے، جو انہوں نے بعض ازواج مطہرات رضی اللہ عنہن سے نقل کی، مسند میں تصریح ہے کہ وہ بنت ایاس بن بکیر ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۷۶) تجرید (۳۰۴/۲)\n(2) الاستيعاب (۱۹۱۳/۴)"}],[11704,"§۱۱۷۴۳ ۔ مریم بنت ابی سفیان الانصاریہ\nدوسیہ۔ بنو عمرو بن عوف سے ہیں، لیلیٰ بنت خظیم، اور ان کے والد ابوسفیان، جنہیں ابوالبنات کہا جاتا تھا اور احد میں شریک تھے، کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11705,"§۱۱۷۴۴ ۔ مریم بنت عثمان الانصاریہ\nشائد یہ مغالیہ ہیں، محمد بن حسن ابن زبالہ کی کتاب المدینہ میں ان کا ذکر ہے، فرمایا: بحوالہ محمد بن فضالہ، انہوں نے عبدالحمید بن جعفر سے روایت کی، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے اپنا خیمہ بئر ابی کے پاس لگایا، جس وقت بنوقریظہ کا محاصرہ کیا۔ مسجد میں نماز پڑھی اور اپنا جانور مریم بنت عثمان کی حویلی میں بیری کے درخت کے ساتھ باندھا۔"],[11706,"§۱۱۷۴۵ ۔ مریم المغالیہ\n(1)بنو مغالہ سے ہیں، جو انصار کا قبیلہ ہے۔ ثابت بن قیس بن شماس کی زوجہ تھیں۔ یونس بن بکیر نے مغازی میں ان کی حدیث روایت کی، اور حسن بن سفیان نے اپنے طریق سے بحوالہ ابن اسحاق، انہوں نے قتادہ بن ولید سے، انہوں نے عبادہ بن صامت سے، انہوں نے ربیع بنت معوذ سے روایت کیا کہ انہوں نے اپنے شوہر سے خلع لیا، تو سیدنا عثمان رضی اللہ عنہ نے انہیں حکم دیا کہ وہ ایک ماہ ٹھہریں۔ سیدہ ربیع نے فرمایا: سیدنا عثمان رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے اس قول کو لیا ہے، جو آپ صلی اللہ علیہ وسلم نے سیدہ مریم مغالیہ کو اس وقت فرمایا، جب انہوں نے اپنے خاوند کو فدیہ دیا۔(2)","",{"fn":"(1) اسد الغابہ (۷۲۷۷) تجرید (۳۰۴/۲)\n(2) المعجم الکبیر (۸۰/۲۵)"}],[11707,"§۱۱۷۴۶ ۔ مسرہ\n(1)ان کا نام نمیرہ تھا، نبی کریم صلی اللہ علیہ وسلم نے مسرہ تھا، ان سے ایک حدیث مروی ہے، جسے زید بن ابی انیسہ نے بحوالہ زہری مرسل روایت کیا ہے، یہ ابن مندہ کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۹) تجرید (۳۰۴/۲)"}],[11708,"§۱۱۷۴۷ ۔ مشکہ\n(1)بعض کا قول ہے: مسیکہ تصغیر کے ساتھ ہے، عبداللہ بن ابی بن سلول کی باندی ہیں، معاذہ میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۷۲۸۰) تجرید (۳۰۴/۲)"}],[11709,"§۱۱۷۴۸ ۔ مطیعہ بنت النعمان\n(1)بن مالک انصاریہ، بنو عمرو بن عوف سے ہیں، ان کا نام عاصیہ تھا، رسول اللہ صلی اللہ علیہ وسلم نے مطیعہ رکھا، یہ ابن حبیب کا قول ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۸۱) تجرید (۳۰۴/۲)"}],[11710,"§۱۱۷۴۹ ۔ معاذہ بنت عبداللہ\nبن عمرو بن مرہ بن قیس بن عدی بن امیہ بن خلاوہ انصاریہ۔ ابن سعد کا قول ہے: واقدی رحمہ اللہ نے ذکر کیا کہ وہ اسلام لائیں اور رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔"],[11711,"§۱۱۷۵۰ ۔ معاذہ\n(1)اشی مازنیہ کی زوجہ ہیں، اشی مازنی کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۸۲) تجرید (۳۰۴/۲)"}],[11712,"§۱۱۷۵۱ ۔ معاذہ\nشجاع بن حارث سدوسی کی زوجہ ہیں، شجاع میں ان کا ذکر گزر چکا ہے۔"],[11713,"§۱۱۷۵۲ ۔ معاذہ\n(1)عبداللہ بن ابی بن سلول کی باندی ہیں، اور عبداللہ بن ابی کی باندی مسیکہ کی باندی ہیں۔ صحیح مسلم وغیرہ میں مسیکہ کا ذکر اعمش کے طریق سے بحوالہ ابو سفیان ثابت ہے، انہوں نے جابر سے روایت کی، فرماتے ہیں: عبداللہ بن ابی کی باندی جسے مسیکہ کہا جاتا تھا، اس نے اسے بدکاری پر مجبور کیا، وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئی اور آپ صلی اللہ علیہ وسلم سے شکایت کی، اللہ تعالیٰ نے یہ آیت نازل فرمائی: تم اپنی لونڈیوں کو بدکاری پر مجبور نہ کرو جبکہ وہ پاک رہنا چاہیں۔(2) ہمیں معرفہ عالی سند سے ابو معاویہ کے طریق سے بحوالہ اعمش روایت ملی ہے، اس کے الفاظ یہ ہیں: امیمہ اور مسیکہ، عبداللہ بن ابی کی لونڈیاں، نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور عبداللہ بن ابی کی شکایت کی، تو ان دونوں کے بارے میں یہ آیت اتری: اپنی لونڈیوں کو بدکاری پر مجبور نہ کرو۔۔۔۔ شعبی رحمہ اللہ کی مرسل روایت میں معاذہ کا ذکر ثابت ہے، فرماتے ہیں: جنہوں نے اپنے شوہر سے خلع لی اور ان سے خولہ نے نکاح کیا، اس کی والدہ معاذہ ہیں، جن کے بارے میں نازل ہوا: تم اپنی لونڈیوں کو بدکاری پر مجبور نہ کرو۔۔۔۔ اسے عمر بن شبہ نے صحیح سند سے جسے وہ شعبی رحمہ اللہ تک لے گئے ہیں نقل کیا ہے۔ ابو موسیٰ نے آدم بن ابی ایاس کے طریق سے بحوالہ لیث، انہوں نے عقیل سے، انہوں نے ابن شہاب سے روایت کیا، وہ فرماتے ہیں کہ مجھ سے محمد بن ثابت نے جو بنو حارث بن خزرج سے ہیں اس آیت اپنی لونڈیوں کو بدکاری پر مجبور نہ کرو کے بارے میں حدیث بیان کی، یہ معاذہ عبداللہ بن ابی بن سلول کی باندی کے بارے میں نازل ہوئی۔ جس کی وجہ یہ ہے کہ ان کے پاس ایک قیدی تھا، اور عبداللہ بن ابی انہیں اس سے بدکاری کرنے پر مجبور کرتا تھا، تا کہ یہ حاملہ ہو جائیں، یوں اس قیدی کا فدیہ لے جائے۔ یہی وہ سامان ہے جس کے بارے میں اللہ تعالیٰ نے فرمایا: تم دنیا کی زندگی کا نفع تلاش کرتے۔۔۔۔ اور لونڈی اس سے انکار کرتی تھی، وہ مسلمان تھی۔ اللہ تعالیٰ نے ان کے بارے میں آیت نازل فرمائی، اور لوگوں کو اس بات سے روک دیا گیا۔ ابن عمر(3) نے اسے ابراہیم بن سعد کے طریق سے بحوالہ محمد بن اسحاق، انہوں نے زہری رحمہ اللہ سے روایت کیا ہے، فرماتے ہیں: معاذہ مولاۃ عبداللہ بن ابی سلمان خاتون تھیں، بڑی فضیلت والی تھیں، جس کی طرف وہ انہیں بلاتے تھے، وہ انکار کرتی تھیں۔ ابو عمر کے نزدیک وہ دونوں ایک ہیں اور ان کے نام میں اختلاف ہے، فرماتے ہیں، زہری رحمہ اللہ کا قول ہے: معاذہ، اور اعمش نے بحوالہ ابوسفیان، انہوں نے جابر سے روایت کی، مسیکہ، فرماتے ہیں: ابن شہاب کا قول صحیح ہے ان شاء اللہ، فرماتے ہیں: ابو صالح نے بحوالہ ابن عباس رضی اللہ عنہما قصہ بیان کیا، اور لونڈی کا نام مسیکہ لیا ہے، جس سے وہ اعمش کے موافق ہیں۔ میں کہتا ہوں: دونوں روایتوں کے جمع کا امکان ہے اس لیے کسی قول کو ترجیح نہیں۔ شعبی رحمہ اللہ کی روایت تعدد پر دلالت کرتی ہے، اور اس آیت میں فَتَيَاتِكُمْ سے ظاہر ہوتا ہے کہ وہ ایک سے زیادہ ہیں، پھر ابن اسحاق نے زہری کی روایت سے متصل فرمایا: مجھے یہ بات پہنچی ہے کہ خواتین میں انہوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی، ان سے سہل بن قرطہ نے جو بنو عمرو بن حارث سے ہیں نکاح کیا، جس سے عبداللہ بن سہل، ام سعید بنت سہل پیدا ہوئے، وہ انہیں چھوڑ کر وفات پا گئے یا جدا ہو گئے، اس کے بعد ان سے حمیر بن عدی قاری نے نکاح کیا جو بنو حنظلہ سے ہیں، ان سے جڑواں حارث، عدی اور ام سعد پیدا ہوئیں، پھر انہوں نے طلاق دے دی تو عامر بن عدی نے جو بنو خطمہ سے ہیں ان سے نکاح کیا، جس سے ام حبیب بنت عامر پیدا ہوئی، جو معاذہ بنت عبداللہ بن جریر ضریر بن امیہ بن خدارہ بن حارث بن خزرج ہیں۔ تنبیہ: ابن اثیر رحمہ اللہ کا گمان ہے کہ یہ کہنے والے \"مجھے یہ بات پہنچی ہے\" زہری رحمہ اللہ ہیں۔(4) پھر فرمایا: زہری رحمہ اللہ کا قول جو انہوں نے ان کے نسب میں ذکر کیا، اس بات پر دلالت کرتا ہے کہ جاہلیت میں انصار ایک دوسرے کو قیدی بنا لیتے تھے، یہ معاذہ خزرج سے اور عبداللہ بن ابی کی لونڈی تھیں۔ میں کہتا ہوں: انہوں نے جو کہا اس میں تردد ہے، کیونکہ قیدیوں کے بارے میں اس احتمال کے ساتھ متعین نہیں ہے کہ معاذہ کے والد نے عبداللہ کی باندی سے نکاح کیا ہو یا اس کے ساتھ بدکاری کی ہو جس سے معاذہ پیدا ہوئیں، جو عبداللہ کی باندی تھیں۔ روایت دلالت کرتی ہے کہ جب عبداللہ نے معاذہ کو حکم دیا کہ وہ قیدی کو اپنے نفس پر قابو پانے دے، انہوں نے چاہا کہ وہ قیدی سے حاملہ ہوں، اور باندی کی اولاد کو اپنے والد کے فدیے میں دے، جو انہوں نے ذکر کیا، اس سے یہ لازم نہیں آتا کہ وہ لوگ ایک دوسرے کو قیدی بنا لیتے تھے۔","",{"fn":"(1) اسد الغابہ (۷۲۸۳) الاستيعاب (۳۵۴۶) تجرید (۳۰۴/۲)\n(2) سورۃ النور الآیۃ (۳۳)\n(3) الاستيعاب (۱۹۱۳/۴)\n(4) اسد الغابہ (۳۹۸/۵)"}],[11714,"§۱۱۷۵۳ ۔ معاذہ الغفاریہ\n(1)لیلی میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۸۴) تجرید (۳۰۵/۲)"}],[11715,"§۱۱۷۵۴ ۔ ملیکہ بنت ابی امیہ\nطبقات ابن سعد میں طبقات النساء میں ان کا ذکر ہے کہ سیدنا عمر رضی اللہ عنہ نے جب یہ آیت مبارکہ اتری تو انہیں طلاق دے دی: تم خود بھی کافر عورتوں کو اپنے نکاح میں نہ روکے رکھو۔(1) پھر ان سے سیدنا معاویہ نے نکاح کیا اور عبیداللہ کی والدہ ہیں جو سیدنا عمر بن خطاب رضی اللہ عنہ کے بیٹے ہیں۔","",{"fn":"(1) سورۃ الممتحنہ الآیۃ (۱۰)"}],[11716,"§۱۱۷۵۵ ۔ ملیکہ بنت ثابت\n(1)بن فاکہ، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۵/۲)\n(2) الطبقات الکبریٰ (۲۵۶/۸)"}],[11717,"§۱۱۷۵۶ ۔ ملیکہ بنت خارجہ\n(1)بن زید بن ابی زہیر انصاریہ، حبیبہ میں ان کے حالات گزر چکے ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۸۶) تجرید (۳۰۵/۲)"}],[11718,"§۱۱۷۵۷ ۔ ملیکہ بنت خارجہ\n(1)بن سنان، قسم ثالث میں ان کا ذکر آئے گا۔","",{"fn":"(1) اسد الغابہ (۷۲۸۷) تجرید (۳۰۵/۲)"}],[11719,"§۱۱۷۵۸ ۔ ملیکہ بنت داؤد\n(1)ابن بشکوال نے مزدوجات میں ان کا ذکر کیا ہے، وہ صحیح نہیں، ملیکہ بنت کعب میں ان کا ذکر آئے گا، اس کی اصلاح کر لیں۔","",{"fn":"(1) تجرید (۳۰۵/۲)"}],[11720,"§۱۱۷۵۹ ۔ ملیکہ بنت سہل\n(1)بن زید بن عمرو بن عامر بن بخشم انصاریہ، ابوہیثم بن تیہان کی زوجہ ہیں، ابن سعد(2) نے ان کا ذکر کیا ہے اور فرمایا: اسلام لائیں اور بیعت کی، یہ محمد بن عمر کی روایت میں ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۹۱)\n(2) الطبقات الکبریٰ (۲۳۸/۸)"}],[11721,"§۱۱۷۶۰ ۔ ملیکہ بنت عبداللہ\n(1)بن ابی بن سلول انصاری خزرجیہ، ابن سعد نے بھی ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۵/۲)"}],[11722,"§۱۱۷۶۱ ۔ ملیکہ بنت عبداللہ\n(1)بن صحر بن خنساء انصاریہ۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۰۵/۲)"}],[11723,"§۱۱۷۶۲ ۔ ملیکہ بنت عمرو الانصاریہ\n(1)بنو زید اللات بن سعد سے ہیں، ابو عمر(2) نے ان کا ذکر کیا ہے، فرمایا: زہیر بن معاویہ کے ہاں ان کی حدیث بحوالہ ان کے گھرانے کی کسی خاتون سے مروی ہے جو انہوں نے ان سے روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے گائے کے بارے میں فرمایا: \"ان کے دودھ میں شفاء، ان کا گھی دوا اور گوشت بیماری ہے۔\"(3) میں کہتا ہوں: ابوداؤد نے مراسیل میں اسے نقل کیا ہے اور ابن مندہ نے اسے موصولاً نقل کیا ہے، ہمارے پاس اس سے عالی سند کے ساتھ مروی ہے، ان کے حالات میں وہی نقل کیا جو ابن ابو عاصم نے وحدان میں نقل کیا ہے اور ابن وہب کے طریق سے فرماتے ہیں: میری طرف حمزہ بن عبدالواحد بن محمد بن عمرو بن طلحہ نے بحوالہ محمد بن عمرو خط لکھا کہ ملیکہ نے انہیں بتایا کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"جب تم کسی قوم کے بارے میں سنو کہ انہیں زمین میں دھنسا دیا گیا ہے تو قیامت قریب آگئی ہے۔\" یہ روایت ابن مندہ کے ہاں بھی عالی سند سے مروی ہے۔ اس دوسری روایت میں ملیکہ کا نسب بیان نہیں کیا گیا، اس لیے احتمال ہے کہ وہ کوئی اور ہوں۔","",{"fn":"(1) اسد الغابہ (۷۲۹۰) تجرید (۳۰۵/۲)\n(2) الاستيعاب (۱۹۱۴/۴)\n(3) المعجم الکبیر (۷۹/۲۵) مجمع الزوائد (۹۰/۵)"}],[11724,"§۱۱۷۶۳ ۔ ملیکہ بنت عمرو\n(1)بن سہل انصاریہ، بنو عبد الاشہل سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، ابو ہیثم بن تیہان کی زوجہ ہیں۔(2)","",{"fn":"(1) اسد الغابہ (۷۲۹۱) الاستيعاب (۳۵۵۰)\n(2) اسد الغابہ (۴۰۰/۵)"}],[11725,"§۱۱۷۶۴ ۔ ملیکہ بنت عویمر الہذلیہ\n(1)بعض کا قول ہے: بنت عویم، راء کے بغیر ہے، ان کی کنیت ام عفیف تھی، بعض کا قول ہے: ام قطیف، پہلا قول قابل اعتماد ہے، دوسرا قول ابوعمر کے کلام میں ہے اور وہ لفظی غلطی ہے۔ رجال کے حصے میں حرف میم میں ان کی حدیث کا ذکر گزر چکا ہے۔ اس میں اس اختلاف کا ذکر کیا کہ وہ عویمر ہے یا عویم بغیر راء کے ہے، حدیث کی سند ضعیف ہے، جو ان دو عورتوں کے بارے میں ہے جو حمل بن نابغہ ہذلی کے نکاح میں تھیں، ان میں سے ایک نے دوسری کو مارا جس سے بچہ ضائع ہو گیا۔۔۔۔ (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۲۹۲) تجرید (۳۰۵/۲)"}],[11726,"§۱۱۷۶۵ ۔ ملیکہ بنت کعب الکنانیہ\n(1)واقدی نے بحوالہ ابومعشر ذکر کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ان سے نکاح کیا، وہ بہت حسین و جمیل تھیں ان کے پاس سیدہ عائشہ یا حفصہ آئیں اور ان سے کہا: کیا تمہیں اس بات سے حیا نہیں آتی کہ تم اپنے باپ کے قاتل سے نکاح کرو، ان کا والد فتح مکہ کے دن قتل ہوا، اسے سیدنا خالد بن ولید نے قتل کیا، فرماتے ہیں: انہوں نے نبی کریم صلی اللہ علیہ وسلم سے پناہ چاہی تو آپ صلی اللہ علیہ وسلم نے انہیں طلاق دے دی۔ ان کی قوم کے لوگ آئے اور آپ سے کہنے لگے کہ ان سے رجوع کر لیں، ان کی کم عمری اور ضعف رائے کا عذر پیش کیا اور یہ کہ انہیں دھوکہ دیا گیا تھا، آپ صلی اللہ علیہ وسلم نے انکار کر دیا، انہوں نے بنو عذرہ میں اس کا کسی قریبی سے نکاح کرنے کی اجازت مانگی، آپ صلی اللہ علیہ وسلم نے اجازت دے دی۔ عطاء بن یزید جندعی کے طریق سے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے ملیکہ بنت کعب سے رمضان کے مہینے میں نکاح کیا اور ان کے پاس آئے اور آپ صلی اللہ علیہ وسلم کے پاس ہی وفات پا گئیں۔ واقدی رحمہ اللہ کا قول ہے: ہمارے اصحاب اس کا انکار کرتے ہیں اور نبی کریم صلی اللہ علیہ وسلم نے کسی کنانیہ سے نکاح نہیں کیا۔","",{"fn":"(1) تجرید (۳۰۶/۲)"}],[11727,"§۱۱۷۶۶ ۔ ملیکہ\n(1)خباب بن ارت کی زوجہ ہیں، ابن مندہ رحمہ اللہ کا قول ہے: انہوں نے نبی کریم صلی اللہ علیہ وسلم کا زمانہ پایا، ابو خالد والبی نے بحوالہ منہال بن عمرو موقوفاً ان کی حدیث روایت کی ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۲۸۸) تجرید (۳۰۵/۲)\n(2) اسد الغابہ (۳۹۹/۵)"}],[11728,"§۱۱۷۶۷ ۔ ملیکہ الانصاریہ\n(1)صحیحین میں مالک کی روایت میں(2) بحوالہ اسحاق بن عبداللہ بن ابو طلحہ، انہوں نے انس سے روایت کیا ہے، ان کا ذکر ہے کہ ان کی دادی ملیکہ نے رسول اللہ صلی اللہ علیہ وسلم کو کھانے کی دعوت دی۔۔۔۔ (الحدیث)(3) اس روایت میں نبی کریم صلی اللہ علیہ وسلم کا ان کے گھر نماز پڑھنے کا ذکر ہے۔ سیدنا انس رضی اللہ عنہ فرماتے ہیں: میں اور یتیم آپ صلی اللہ علیہ وسلم کے پیچھے کھڑے ہوئے اور بڑھیا ہمارے پیچھے کھڑی ہوئی، \"ان کی دادی\" اس ضمیر کے بارے میں اختلاف ہے، بعض کا قول ہے: انس کی اور بعض کا قول ہے اسحاق کی، ابو عمر نے دوسرے قول پر اعتماد کیا ہے۔ ابن اثیر نے لکھا(4) ہے کہ سیدنا انس رضی اللہ عنہ کے والد یا والدہ کی طرف سے کوئی خالہ ایسی نہیں جس کا نام ملیکہ ہو۔ میں کہتا ہوں: اس نفی میں تردد ہے جس کا تذکرہ کیا گیا ہے، عدوی نے انصار کے نسب میں ذکر کیا ہے کہ ام سلیم کی والدہ کا نام ملیکہ ہے۔ اس کے الفاظ یہ ہیں: سلیم بن ملحان اور ان کے بہن بھائیوں زید، حرام، عباد، ام سلیم اور ام حرام بنو ملحان، ان کی والدہ ملیکہ بنت مالک بن عدی بن زید مناۃ بن عدی بن عمرو بن مالک بن نجار، اس سے ظاہر ہوتا ہے کہ \"ان کی دادی\" میں ضمیر سیدنا انس رضی اللہ عنہ کی طرف ہے، یہ ان کی نانی ہیں، جنہوں نے ضمیر اسحاق کی طرف کی ہے ان کا قول باطل ہوا، اور اس بنا پر یہ کہہ دیا کہ ام سلیم کا نام ملیکہ تھا۔ واللہ الموفق!","",{"fn":"(1) اسد الغابہ (۷۲۸۴) تجرید (۳۰۵/۲)\n(2) لمالک: قصر الصلاۃ فی السفر (الحدیث: ۳۶۷)\n(3) ترمذی (الحدیث: ۲۳۴)\n(4) اسد الغابہ (۳۹۸، ۳۹۹)"}],[11729,"§۱۱۷۶۸ ۔ ملیکہ\n(1)سائب بن اقرع کی والدہ ہیں۔ قسم اول، رجال کے تحت حرف سین میں ان کا ذکر گزر چکا ہے، وہ عطر بیچا کرتی تھیں۔ نبی کریم صلی اللہ علیہ وسلم نے ان سے پوچھا: \"کیا تمہاری کوئی حاجت ہے؟\"(2) انہوں نے کہا: میرے بیٹے کے لیے دعا کر دیجئے۔۔۔۔ (الحدیث)","",{"fn":"(1) اسد الغابہ (۷۲۸۹) تجرید (۳۰۵/۲)\n(2) التاریخ الکبیر (۱۵۱/۴)"}],[11730,"§۱۱۷۶۹ ۔ ملیکہ الہلالیہ\n(1)عبداللہ بن ابی حدرد کی زوجہ ہیں، مسلم نے افراد میں ان کا ذکر کیا ہے، تجرید(2) میں بھی ان کا ذکر ہے۔","",{"fn":"(1) تجرید (۳۰۵/۲)\n(2) تجرید (۱۹۷)"}],[11731,"§۱۱۷۷۰ ۔ مندوس بنت خلاد\n(1)بن سوید بن ثعلبہ انصاریہ، خزرجیہ، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۲۹۳) تجرید (۳۰۶/۲)\n(2) اسد الغابہ (۴۰۰/۵)"}],[11732,"§۱۱۷۷۱ ۔ مندوس بنت عبادہ\n(1)بن دلیم بن حارثہ بن ابی خزیمہ انصاریہ، خزرجیہ، خزرج کے سردار سعد بن عبادہ کی بہن ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۲۹۴) تجرید (۳۰۶/۲)\n(2) اسد الغابہ (۴۰۰/۵)"}],[11733,"§۱۱۷۷۲ ۔ مندوس بنت عمرو\n(1)بن نخسیس بن لوذان بن عبدوڈ انصاریہ، منذر بن عمرو اور ام سلمہ بن مخلد کی بہن ہیں، بیعت کرنے والی صحابیات میں ان کا ذکر ہے، ابن اثیر(2) نے ذکر کیا ہے کہ ان کی بیٹی قریبہ نے ان سے روایت کی کہ وہ نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں اور کہنے لگیں: یا رسول اللہ میں آگ۔ آپ صلی اللہ علیہ وسلم نے پوچھا: \"تمہارا یہ کہنے کا کیا مطلب ہے؟\" انہوں نے اپنے معاملے کے بارے میں بتایا، وہ نقاب کیے ہوئے تھیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ کی بندی! اپنے چہرے کو کھلا رکھو، کیونکہ باندیوں کے لیے اپنے چہرے کو کھلا رکھنا اسلام کا حصہ ہے، اور نقاب فسق و فجور ہے۔\" اس کی نسبت ابن مندہ اور ابو نعیم کی طرف کی ہے، جبکہ مجھے ان دونوں میں سے کسی کے پاس یہ روایت نہیں ملی۔","",{"fn":"(1) اسد الغابہ (۷۲۹۵) تجرید (۳۰۶/۲)\n(2) اسد الغابہ (۴۰۰/۵)"}],[11734,"§۱۱۷۷۳ ۔ مندوس بنت قطبہ\n(1)بن عمرو بن مسعود بن عبد الاشہل بن حارثہ بن دینار بن نجار، ابن سعد کا قول ہے کہ بیعت کرنے والی صحابیات میں سے ہیں، ان کی والدہ کا نام عمیرہ بنت قرط بن خنساء بن سنان ہے، ان سے عمارہ بن حباب بن سعد بن قیس بن عمرو بن زید مناۃ نے نکاح کیا، ان سے ابو عمرو پیدا ہوئے، ان کے بعد عبداللہ بن کعب بن زید بن قیس بن مالک بن کعب بن عبد الاشہل سے نکاح ہوا، ان سے ام عتبہ اور ام سعد پیدا ہوئیں، ان کے بعد عبداللہ بن ابی سلیط بن عمرو بن قیس پیدا ہوئے، جس سے مروان پیدا ہوئے۔","",{"fn":"(1) تجرید (۳۰۶/۲)"}],[11735,"§۱۱۷۷۴ ۔ موہبہ\nنبی کریم صلی اللہ علیہ وسلم کی مولاۃ ہیں، حدیث ابو نضرہ غفاری میں ان کے اسلام لانے کے قصہ میں ان کا تذکرہ ہے۔ جزء رابع میں اسماعیل صفار کی حدیث میں، ابن لہیعہ کے طریق سے موسیٰ بن وردان سے بحوالہ ابو نضرہ غفاری حدیث مروی ہے۔۔۔۔ پھر حدیث ذکر کی۔ اس میں ہے، آپ صلی اللہ علیہ وسلم نے موہبہ سے ایک اونٹنی منگوائی جس کا دودھ دوہا اور مجھے پلایا، مجھے یوں محسوس ہوا جیسے میں نے کچھ پیا ہی نہیں۔ پھر دوسری اونٹنی منگوائی یہاں تک کہ فرماتے ہیں: موہبہ غصے میں آگئی اور مجھے غصہ سے گھورنے لگی، اس میں ہے: \"کافر سات آنتوں سے کھاتا ہے۔\""],[11736,"§۱۱۷۷۵ ۔ میمونہ بنت الحارث\n(1)بن حزن ہلالیہ، ام فضل لبابہ کی بہن ہیں، حرف لام میں ان کی بہن کے ساتھ ان کا نسب گزر چکا ہے، میمونہ ام المومنین ہیں۔۔۔۔ ان کا نام برہ تھا، نبی کریم صلی اللہ علیہ وسلم نے میمونہ رکھا۔ نبی کریم صلی اللہ علیہ وسلم سے نکاح سے قبل ابو رہم بن عبد العزیٰ بن عبدود بن مالک بن حسل بن عامر بن لوی قرشی عامری کے نکاح میں تھیں۔ بعض کا قول ہے: حویطب بن عبدالعزیٰ کے نکاح میں تھیں اور بعض نے کہا فروہ جو ان کے بھائی ہیں، ان کے پاس تھیں۔ نبی کریم صلی اللہ علیہ وسلم نے ذی قعدہ ۷ھ میں جب عمرہ قضیہ کیا تو ان سے نکاح کیا، بعض کا قول ہے: آپ صلی اللہ علیہ وسلم نے جعفر بن ابی طالب کو نکاح کا پیغام دے کر بھیجا، انہوں نے سیدنا عباس رضی اللہ عنہ کو نکاح کی اجازت دی، انہوں نے آپ صلی اللہ علیہ وسلم سے ان کا نکاح کر دیا۔ بعض کا قول ہے کہ سیدنا عباس رضی اللہ عنہ نے آپ صلی اللہ علیہ وسلم کے سامنے ان کی تعریف کی اور فرمایا: وہ ابو رہم سے بیوہ ہوگئی ہیں، آپ صلی اللہ علیہ وسلم نے ان سے نکاح کر لیا۔(2) ابن اسحاق(3) کا قول ہے: یونس بن بکیر وغیرہ کی ان سے روایت میں ہے: پھر سیدہ میمونہ رضی اللہ عنہا سے سیدہ صفیہ رضی اللہ عنہا کے بعد نکاح کیا اور ابو رہم کے نکاح میں تھیں۔ یونس بن بکیر کا قول ہے: مجھ سے جعفر بن برقان نے میمون بن مہران سے بحوالہ یزید بن اصم روایت کیا ہے۔ فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ان سے نکاح کیا اور وہ حالت احرام میں نہیں تھے، اور ایک خیمہ میں رخصتی ہو گئی۔ اور اسی (مقام سرف) میں ان کی وفات ہوئی۔(4) یہ روایت مرسل ہے، بحوالہ میمونہ بنت خالد بن یزید بن اصم، ان کی دوسری خالہ کے بیٹے عبداللہ بن عباس نے اس کی مخالفت کی ہے، اور یقین کیا ہے کہ آپ صلی اللہ علیہ وسلم نے ان سے حالت احرام میں نکاح کیا تھا۔ صحیح بخاری میں یہی مذکور ہے، اس حکم کے بارے میں فقہاء میں اختلاف ہے، بعض نے ان دونوں کو جمع کیا ہے کہ آپ صلی اللہ علیہ وسلم نے حالت احرام میں ان سے نکاح کیا تھا اور تنعیم میں عمرہ کا احرام اتارنے کے بعد ان کی رخصتی ہوئی، آپ صلی اللہ علیہ وسلم نے حل پر عمرہ کا احرام اتارا، یہ ابن اسحاق کی روایت میں قصے کی سیاق سے ظاہر ہے، بعض کا قول ہے: احرام سے قبل ان سے نکاح ہوا اور احرام باندھنے کے بعد آپ صلی اللہ علیہ وسلم کی ان سے نکاح کی خبر پھیل گئی، اس سے نکاح کے وقت کا تعین مشکل ہو گیا۔ زہری اور قتادہ نے ذکر کیا ہے کہ یہ وہی ہیں جنہوں نے نبی کریم صلی اللہ علیہ وسلم کے لیے اپنے نفس کو ہبہ کر دیا تھا تو ان کے بارے میں قرآن کی آیت اتری، بعض نے کہا: ہبہ کرنے والی ان کے علاوہ کوئی اور ہیں۔ بعض کا قول ہے: وہ بہت سی ہیں، یہ قول زیادہ صحیح ہے۔ ابن سعد(5) کا قول ہے: یہ آخری خاتون تھیں جن سے نبی کریم صلی اللہ علیہ وسلم نے نکاح کیا، یعنی جن کی رخصتی ہوئی، اور اپنی سند سے ذکر کیا ہے کہ آپ صلی اللہ علیہ وسلم نے شوال ۷ھ میں ان سے نکاح کیا تھا اگر یہ بات ثابت ہو تو صحیح یہ ہے کہ نبی کریم صلی اللہ علیہ وسلم نے عمرہ کا احرام اتارنے کے بعد ان سے نکاح کیا، کیونکہ آپ صلی اللہ علیہ وسلم نے ذی قعدہ میں عمرہ کیا تھا، اور اپنی سند سے جس میں واقدی بھی ہیں، اس سند کو علی بن عبداللہ بن عباس تک لے گئے ہیں، فرماتے ہیں: جب رسول اللہ صلی اللہ علیہ وسلم نے مکہ کی طرف عمرہ کے لیے نکلنے کا ارادہ کیا تو اوس بن خولی اور ابو رافع کو سیدنا عباس رضی اللہ عنہ کے پاس بھیجا تا کہ وہ سیدہ میمونہ رضی اللہ عنہا سے ان کا نکاح کر دیں۔ ان دونوں کے اونٹ گم ہو گئے، وہ کئی دن بطن رابغ میں ٹھہرے رہے، یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو انہیں ان کے اونٹ مل گئے، وہ دونوں آپ صلی اللہ علیہ وسلم کے ساتھ روانہ ہوئے یہاں تک کہ مکہ آپہنچے، آپ صلی اللہ علیہ وسلم نے سیدنا عباس رضی اللہ عنہ کے پاس پیغام بھیجا، جس میں اس بات کا ذکر تھا تو انہوں نے اپنا معاملہ رسول اللہ صلی اللہ علیہ وسلم کے سپرد کر دیا، آپ صلی اللہ علیہ وسلم سیدنا عباس رضی اللہ عنہ کے گھر آئے، اور سیدنا عباس رضی اللہ عنہ کو ان کے نکاح کا پیغام دیا، انہوں نے آپ صلی اللہ علیہ وسلم سے ان کا نکاح کر دیا۔ سلیمان بن یسار کے طریق سے ہے کہ نبی کریم صلی اللہ علیہ وسلم نے ابو رافع اور دوسرے شخص کو بھیجا کہ وہ سیدہ میمونہ کا نکاح آپ کے ساتھ مدینہ سے نکلنے سے قبل کر دیں۔ ابن سعد نے بھی عبدالکریم کے طریق سے بحوالہ میمون بن مہران نقل کیا ہے، فرماتے ہیں: میں صفیہ بنت شیبہ کے پاس گیا اس وقت وہ بڑی عمر کی تھیں، میں نے ان سے پوچھا، رسول اللہ صلی اللہ علیہ وسلم نے جب سیدہ میمونہ رضی اللہ عنہا سے نکاح کیا کیا وہ حالت احرام میں تھے؟ انہوں نے کہا: نہیں، اللہ کی قسم! آپ صلی اللہ علیہ وسلم نے ان سے نکاح کیا، وہ دونوں حالت احرام میں نہیں تھے۔ ابن سعد(6) کا قول ہے: ہم سے ابونعیم نے حدیث بیان کی، وہ فرماتے ہیں کہ ہم سے ہشام بن سعد نے بحوالہ عطاء خراسانی حدیث بیان کی، میں نے ابن مسیب سے کہا: عکرمہ کا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدہ میمونہ رضی اللہ عنہا سے نکاح کیا تو آپ صلی اللہ علیہ وسلم حالت احرام میں تھے، انہوں نے کہا: میں ابھی تمہیں بتاتا ہوں رسول اللہ صلی اللہ علیہ وسلم جب تشریف لائے تو حالت احرام میں تھے، جب احرام اتارا تو ان سے نکاح کیا۔ ابن سعد کا قول ہے: ہم سے محمد بن عمر نے حدیث بیان کی، اور ہمیں ابن جریج نے بحوالہ ابوزبیر، انہوں نے عکرمہ سے بتایا کہ سیدہ میمونہ بنت حارث رضی اللہ عنہا نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کیا تھا، محمد بن عمر سے بحوالہ موسیٰ بن محمد بن عبدالرحمن، انہوں نے اپنے والد سے، انہوں نے عمرہ سے روایت کیا ہے، فرماتے ہیں: ان سے کہا گیا: سیدہ میمونہ رضی اللہ عنہا نے اپنے نفس کو نبی کریم صلی اللہ علیہ وسلم کے لیے ہبہ کر دیا۔ وہ فرماتی ہیں: ان سے رسول اللہ صلی اللہ علیہ وسلم نے ۵۰۰ درہم مہر پر نکاح کیا، آپ صلی اللہ علیہ وسلم کا ان سے نکاح کا معاملہ سیدنا عباس رضی اللہ عنہ کے سپرد تھا۔ ابن سعد(7) نے صحیح سند سے جسے وہ سیدنا ابن عباس رضی اللہ عنہما تک لے گئے ہیں نقل کیا ہے، فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن بہنیں یہ ہیں: میمونہ، ام فضل، اسماء ابن سعد کا قول ہے: ہمیں کثیر بن ہشام نے بتایا، وہ فرماتے ہیں: کہ ہم سے جعفر بن برقان نے روایت کی، وہ فرماتے ہیں: کہ ہم سے یزید بن اصم نے حدیث بیان کی، فرماتے ہیں: میں اور ابن طلحہ جو ان کا بھانجا تھا مکہ میں سیدہ عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوئے، ہم مدینہ کے ایک باغ میں ٹھہرے تھے، جس میں سے ہم نے کچھ لیا تھا، جب انہیں یہ بات معلوم ہوئی تو اپنی بہن کے بیٹے کی طرف متوجہ ہوئیں اور اسے ملامت کرنے لگیں، پھر وہ میری طرف متوجہ ہوئیں اور مجھے پر اثر نصیحت کی، فرمانے لگیں: کیا تم نہیں جانتے کہ اللہ تعالیٰ نے تمہیں چلایا یہاں تک کہ تمہیں اپنے نبی کے گھروں میں سے ایک گھر میں ٹھہرا دیا ہے؟ اللہ کی قسم! میمونہ چل بسیں اور تمہاری مہار تمہارے کندھے پر ڈال دی گئی۔ وہ ہم سب سے زیادہ اللہ سے ڈرنے والی اور ہم سے زیادہ صلہ رحمی کرنے والی تھیں۔ یہ سند صحیح ہے۔ اسی طرح فرمایا: ہم سے ابونعیم نے حدیث بیان کی، وہ فرماتے ہیں کہ ہم سے جعفر بن برقان نے حدیث بیان کی، کہ مجھے میمون بن مہران نے بتایا، فرماتے ہیں: میں نے صفیہ بنت شیبہ سے پوچھا، کہنے لگیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدہ میمونہ سے مقام سرف میں نکاح کیا اور ان کے خیمہ میں رخصتی ہوئی، مقام سرف میں ہی وفات ہوئی۔ اور ہمارے خیمہ کی جگہ دفن ہوئیں۔۔۔۔(8) سیدہ میمونہ رضی اللہ عنہا کی وفات ۵۱ھ میں ہوئی۔ ابن سعد نے واقدی سے نقل کیا ہے کہ وہ ۶۱ھ میں وفات پا گئیں، فرماتے ہیں، انہوں نے ازواج مطہرات میں انہیں میں سب سے آخر میں وفات پائی۔ اگر یہ آخری کلام نہ ہوا تو احتمال تھا کہ یہ قول: ۶۰ھ بعض راویوں کا وہم ہے لیکن سیدہ عائشہ رضی اللہ عنہا کی روایت جسے ان سے یزید بن اصم نے روایت کیا ہے اس پر دلالت کرتی ہے کہ سیدہ عائشہ رضی اللہ عنہا ۶۰ھ سے قبل وفات پاگئیں، اس میں کسی کا اختلاف بھی نہیں، اور مذکورہ روایت درست ہے جو واقدی رحمہ اللہ کے قول سے بہتر ہے۔ یعقوب بن سفیان نے اس پر اعتماد کیا ہے کہ وہ ۴۹ھ میں وفات پاگئیں، بعض کا قول ہے ۶۳ھ میں وفات پائی، بعض نے کہا: ۲۶ھ میں یہ دونوں قول ثابت نہیں، پہلا قول ثابت ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۹۷) الاستيعاب (۳۵۵۲) تجرید (۳۰۶/۲)\n(2) اسد الغابہ (۴۰۱/۵)\n(3) السیرۃ النبویۃ (۲۲۱/۴)\n(4) مسلم (۳۴۳۷)، ترمذی (۸۴۵)، نسائی (۲۸۳۷)، ابن ماجہ (۱۹۶۵)\n(5) الطبقات الکبریٰ (۹۴/۸)\n(6) الطبقات الکبریٰ (۹۴/۸)\n(7) الطبقات الکبریٰ (۹۸/۸)\n(8) مسند احمد (۳۳۵/۶)"}],[11737,"§۱۱۷۷۶ ۔ میمونہ بنت سعد\n(1)بعض کا قول ہے: سعید، نبی کریم صلی اللہ علیہ وسلم کی خدمت کیا کرتی تھیں، اور آپ صلی اللہ علیہ وسلم سے روایت کی، ان سے زیاد اور عثمان جو ابو سودہ کے بیٹے ہیں، ہلال بن ابو ہلال، ابو یزید ضمی، آمنہ بنت عمر بن عبد العزیز، ایوب بن خالد بن صفوان، طارق بن عبدالرحمن وغیرہ نے روایت کی، اصحاب سنن اربعہ نے ان سے روایت کی ہوئی حدیث نقل کی ہے، بعض نے معاویہ بن صالح کی روایت بحوالہ زیاد بن ابی سودہ انہوں نے سیدہ میمونہ سے (یہ نبی کریم صلی اللہ علیہ وسلم کی زوجہ میمونہ بنت حارث نہیں ہیں) روایت کی ہے کہ انہوں نے عرض کیا: یا رسول اللہ صلی اللہ علیہ وسلم! ہمیں بیت المقدس کے بارے میں بتائیے! آپ صلی اللہ علیہ وسلم نے فرمایا: \"وہ حشر و نشر کی سرزمین ہے، وہاں جاؤ اور اس میں نماز پڑھو۔ (الحدیث)(2) ابو عمر کا قول ہے: میمونہ بنت سعد نبی کریم صلی اللہ علیہ وسلم کی مولاۃ ہیں، ان سے ابو یزید ضمی بن خالد نے روزہ دار کے بوسہ لینے کے بارے اور ولد زنا (حرام) کے آزاد کرنے کے بارے میں مرفوع حدیث روایت کی ہے، اس کی سند قوی نہیں ہے، پھر فرمایا: میمونہ (دوسری) اہل شام کے ہاں بیت المقدس کی فضیلت کے بارے میں ان کی حدیث ہے، اور سخت عذاب قبر غیبت اور پیشاب سے نہ بچنے پر ہوتا ہے، ان سے زیاد بن ابی سودہ اور قاسم بن عبدالرحمن نے روایت کی ہے۔ میں کہتا ہوں: زیاد بن ابی سودہ نے اس کی تصریح کی ہے کہ جن سے حدیث مروی ہے میمونہ بنت سعد ہیں، ظاہر یہ ہے کہ وہ دونوں ایک ہیں، ابن عبدالبر سے پہلے یہ فرق ابو علی بن السکن نے ذکر کیا ہے۔ فرماتے ہیں: میمونہ بنت سعد، نبی کریم صلی اللہ علیہ وسلم کی مولاۃ ہیں، ان سے احادیث مروی ہیں، پھر عکرمہ بن عمار کے طریق سے بحوالہ طارق بن قاسم، انہوں نے میمونہ مولاۃ رسول اللہ صلی اللہ علیہ وسلم سے روایت کی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: اے میمونہ! عذاب قبر سے اللہ کی پناہ مانگو۔ کہنے لگیں: کیا وہ برحق ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ہاں! اکثر غیبت اور پیشاب سے نہ بچنے سے ہوتا ہے۔(3) ابو یزید ضمی کے طریق سے بحوالہ سیدہ میمونہ، جو نبی کریم صلی اللہ علیہ وسلم کی مولاۃ ہیں، مروی ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم سے ولد زنا (حرام) کے بارے میں سوال کیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس میں بھلائی نہیں۔۔۔۔\"۔ (الحدیث)(4) میں کہتا ہوں: یہ روایت زہری رحمہ اللہ نے اس طریق سے نقل کی ہے، اور ایوب بن خالد کے طریق سے بحوالہ میمونہ بنت سعد جو نبی کریم صلی اللہ علیہ وسلم کی خادمہ ہیں، مروی ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم نے فرمایا: \"زیب و زینب میں حد سے بڑھنے والی ایسی تاریکی ہے جس میں روشنی کا نام ونشان تک نہ ہو۔\" پھر فرمایا: سیدہ میمونہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کی مولاۃ ہیں۔(5) میں کہتا ہوں: بنت سعد ان سے بیت المقدس کی فضیلت کے بارے میں ایک حدیث مروی ہے، اس میں تردد ہے، پھر عیسیٰ بن یونس کے طریق سے ثور بن یزید سے بحوالہ زیاد بن ابی سودہ، انہوں نے اپنے بھائی عثمان بن ابی سودہ سے، انہوں نے میمونہ نبی کریم صلی اللہ علیہ وسلم کی مولاۃ سے روایت کی ہے، پھر فرمایا: اسے سعید بن عبد العزیز نے ثور سے بحوالہ زیاد انہوں نے سیدہ میمونہ رضی اللہ عنہا سے روایت کیا ہے، ان دونوں راویوں کے درمیان حضرت عثمان بن سعد نہیں۔ میں کہتا ہوں: ابن مندہ نے اسے دو طریق سے نقل کیا ہے، اور ان دونوں کے حالات بیان کیے ہیں۔ جیسا ابن سکن نے میمونہ، مولاۃ النبی صلی اللہ علیہ وسلم کا عنوان قائم کیا ہے، لیکن اس میں یہ اضافہ کیا ہے کہ ان سے علی بن ابی طالب رضی اللہ عنہ نے روایت کی، اور ان کی روایت ان کے حوالے سے نقل نہیں کی، پھر ولد زنا کے آزاد کرنے کے بارے میں حدیث روایت کی، فرماتے ہیں: بحوالہ میمونہ مولاۃ النبی صلی اللہ علیہ وسلم جیسا کہ عذاب قبر سے پناہ مانگنے کے بارے میں طارق بن قاسم بن عبد الرحمن کے طریق سے حدیث مروی ہے، اس میں ہے، بحوالہ میمونہ بنت حبیب پھر سیدہ میمونہ بنت سعد رضی اللہ عنہا خادم النبی صلی اللہ علیہ وسلم کا عنوان قائم کیا، اور محمد بن ہلال کی بحوالہ ان کے والد حدیث نقل کی کہ انہوں نے میمونہ بنت سعد رضی اللہ عنہا کو فرماتے ہوئے سنا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا، فرمایا: \"جو رات سے روزے کو جمع کرے اسے چاہیے کہ روزہ رکھ لے\"۔ (الحدیث)(6) ایوب بن خالد کے طریق سے بحوالہ میمونہ بنت سعد زیب و زینب میں تجاوز کرنے والی کے بارے میں حدیث مروی ہے، وہ نبی کریم صلی اللہ علیہ وسلم کی خدمت کرتی تھیں، ابن سکن، ابن مندہ اور ابو عمر کا اتفاق ہے کہ وہ دونوں خواتین علیحدہ علیحدہ ہیں۔ ابو نعیم نے ان کی مخالفت کی ہے، فرماتے ہیں: میرے نزدیک وہ دونوں ایک ہیں، ابن اثیر نے اسے درست قرار دیا ہے، اسی سے مزی نے تہذیب میں اپنے کلام کو شروع کیا ہے۔ پھر فرمایا، بعض نے کہا: وہ دو ہیں۔ میں کہتا ہوں: ابن سکن کا قول دوسری صحابیہ کے بارے میں ہے اور وہ بنت سعد نہیں، بیت المقدس میں نماز پڑھنے کے بارے میں بھی ان کی روایت نقل ہے۔ اس سے یہ سمجھا جائے گا کہ روایت میں یہ موجود نہیں (۔۔۔۔ اسے نقل کیا ہے۔۔۔۔)(7) اسی سے ابو نعیم کے قول کو تقویت ملتی ہے کہ وہ دونوں ایک ہیں۔ پھر ابن مندہ نے تیسری میمونہ کا ذکر کیا اور فرمایا: میمونہ بے نسبت، ان سے امیہ بنت عمر نے روایت کی ہے، وہ فرماتی ہیں: یا رسول اللہ صلی اللہ علیہ وسلم! ہمیں صدقہ کے بارے میں بتائیے! آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ آگ سے اوٹ ہے۔\"(8) انہوں نے کہا: ہمیں کتے کی قیمت کے بارے میں بتائیے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس کا کھانا جاہلیت میں سے ہے۔\" انہوں نے کہا: ہمیں عذاب قبر کے بارے میں بتائیے! آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ پیشاب سے نہ بچنے سے ہوتا ہے۔\" ابو نعیم نے اسے اسحاق بن زریق سے بحوالہ عثمان، اس سند سے روایت کیا ہے، اور فرمایا: بحوالہ میمونہ بنت سعد، اور دوسری حدیث بیان کی، اس کے الفاظ یہ ہیں: ہمیں چوری کے مال کے بارے میں بتائیے! آپ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے اسے ان میں کھایا وہ اس کے گناہ اور عار میں شریک ہے\"(9) عمرو بن ہشام کے طریق سے بحوالہ عثمان مروی ہے، ہمیں جنابت سے غسل کے بارے میں بتائیے۔ سر کے دھونے کے لیے کتنا پانی کافی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"تین چلو\"۔(10) ابو نعیم کا قول ہے: ابن مندہ نے علیحدہ اس کا ذکر کیا ہے۔ طبرانی رحمہ اللہ نے مسند میمونہ بنت سعد میں ان دونوں کی حدیث روایت کی ہے۔ میں کہتا ہوں: غالب گمان یہ ہے کہ وہ تینوں ایک ہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۹۹) تجرید (۳۰۶/۲)\n(2) ابوداؤد (۴۵۷) ابن ماجہ (۱۴۰۷) مسند احمد (۴۶۳/۶) طبرانی المعجم الکبیر (۵۴/۲۵، ۵۵) جامع المسانید والسنن (۱۳۳/۱۶، ۱۳۴)\n(3) کنز العمال (۴۳۹۳۵) طبقات الکبریٰ (۲۲۳/۸)\n(4) ابن ماجہ (۲۵۳۱) نسائی (۴۹۹/۱۲) مسند احمد (۴۵۳/۶) جامع المسانید والسنن (۱۳۲/۱۶) البدایۃ والنہایۃ (۳۳۰/۵)\n(5) ترمذی (۱۱۶۷)\n(6) جامع المسانید والسنن (۱۳۵/۱۶)\n(7) بیاض فی الاصل ای فی کتاب ابن حجر۔ (مترجم)\n(8) اسد الغابہ (۴۰۳/۵)\n(9) الآحاد والمثانی (۲۱۷/۶)\n(10) المعجم الکبیر (۶۱/۲۵) مجمع الزوائد (۱۱۱/۳) جامع المسانید والسنن (۱۳۷/۱۶)"}],[11738,"§۱۱۷۷۷ ۔ میمونہ (خادم النبی صلی اللہ علیہ وسلم)\nپہلے گزر چکی ہیں۔"],[11739,"§۱۱۷۷۸ ۔ میمونہ (غیر منسوبہ)\nان کا ذکر بھی پہلے گزر چکا ہے۔"],[11740,"§۱۱۷۷۹ ۔ میمونہ بنت صبیح\n(1)یا صفیح۔ طبرانی(2) رحمہ اللہ کا قول ہے: یہ ابی ہریرہ رضی اللہ عنہ کی والدہ ہیں، اور ان کا قصہ بیان کیا۔ امیمہ میں ان کا ذکر ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۰۰) تجرید (۳۰۷/۲)\n(2) المعجم الکبیر (۴۰/۲۵)"}],[11741,"§۱۱۷۸۰ ۔ میمونہ بنت عبداللہ\n(1)بنی مرید سے ہیں، جو بلی کی شاخ ہے۔ انہیں بھا درہ کہا جاتا تھا، بنو امیہ بن زید جو انصار میں سے ہیں، ان کے حلیف ہیں۔ ابن اسحاق اور ابن سعد نے ان کا ذکر کیا اور ان کے اسلام لانے کا تذکرہ کیا ہے۔ ابن ہشام(2) رحمہ اللہ کا قول ہے کہ انہی نے اپنے ان اشعار کے ذریعہ کعب بن اشرف کے اس مرثیہ کا جواب دیا ہے جس میں اس نے بدر میں قتل ہونے والے مشرکین کا مرثیہ کہا ہے: \"یہ بندہ پوری طرح مہربان ہو گیا، مقتول لوگوں کے لیے رلاتا پھرتا ہے تھکتا نہیں۔ جو شخص بدر اور اہل بدر کے لیے گریہ کناں ہے اس کی آنکھ اشکبار ہے اور لوی بن غالب کے لیے دوہری مصیبت ہے۔ کاش! وہ لوگ جو اپنے خون میں لتھڑے ہیں ان کی کیفیت مکہ کے پہاڑوں میں بسنے والوں کو نظر آ جاتی۔\" ابن ہشام لکھتے ہیں: شعر کا علم رکھنے والے اکثر حضرات نے انکار کیا ہے کہ یہ اشعار ان کے نہیں ہیں۔","",{"fn":"(1) اسد الغابہ (۷۳۰۱) تجرید (۳۰۷/۲)\n(2) السیرۃ النبویۃ (۴۴/۳)"}],[11742,"§۱۱۷۸۱ ۔ میمونہ بنت ابی عسیب\n(1)بعض کا قول ہے: بنت ابی عنبہ، ابو نعیم نے پہلے قول پر اور ابو عمر نے دوسرے قول پر اعتماد کیا ہے اور فرمایا: میمونہ بنت ابی عنبہ، نبی کریم صلی اللہ علیہ وسلم کی مولاۃ ہیں، آپ صلی اللہ علیہ وسلم سے دعا کے بارے میں حدیث روایت کی ہے، ابن مندہ کا قول ہے: میمونہ بنت عنبہ، بعض نے کہا: بنت ابی عنبہ، نبی کریم صلی اللہ علیہ وسلم کی مولاۃ ہیں، مشجع بن مصعب نے بحوالہ ربیعہ بن یزید، انہوں نے منحہ سے انہوں نے میمونہ بنت ابی عنبہ سے حدیث روایت کی کہ حریش سے ایک خاتون نبی کریم صلی اللہ علیہ وسلم کے پاس آئیں، اور کہا: اے عائشہ! رسول اللہ صلی اللہ علیہ وسلم کی دعاؤں میں سے ایسی دعا بتائیے جس سے مجھے اطمینان ہو۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اپنا دایاں ہاتھ اپنے دل پر رکھو، اور مل کر یوں کہو: اے اللہ! اپنی دوا سے میرا علاج کر، اور اپنی شفاء سے مجھے صحت یاب کر، اور اپنے علاوہ لوگوں سے مجھے اپنے فضل کے ذریعہ بے نیاز کر دے۔\"(2) ربیعہ کا قول ہے: میں نے ان الفاظ کے ذریعے اللہ تعالیٰ سے دعا مانگی تو اس سے مجھے بہت اطمینان ہوا، ابو نعیم نے اس طریق سے اسے موصولاً ذکر کیا ہے، اور فرمایا: میمونہ بنت ابی عسیب۔","",{"fn":"(1) اسد الغابہ (۷۳۰۲) تجرید (۳۰۷/۲)\n(2) المعجم الکبیر (۷۲/۲۵) مجمع الزوائد (۱۸۰/۱۶) جامع المسانید والسنن (۱۲۸/۱۶) اسد الغابہ (۴۰۴/۵)"}],[11743,"§۱۱۷۸۲ ۔ میمونہ بنت گردم الثقفیہ\n(1)ان سے یزید بن مقسم نے روایت کی، اہل بصرہ کے پاس ان کی حدیث ہے، یہ یزید معروف نہیں، اسی طرح استیعاب کے بعض نسخوں میں ہے، یہ ابن اثیر کے نسخے میں موجود نہیں۔ انہوں نے ان کا تذکرہ فروگزاشت کیا ہے۔ ابو عمر کے کلام میں تردد ہے، اس لیے کہ انہوں نے فرمایا: اہل بصرہ کے پاس ان کی حدیث ہے، جبکہ اہل طائف کے پاس ان کی حدیث ہے۔ ابوداؤد نے سنن میں کتاب الایمان والنذور میں عبداللہ بن یزید بن مقسم کے طریق سے بحوالہ اپنے والد، اور انہوں نے ان کی پھوپھی سارہ سے، جنہوں نے ان سے روایت کی، حدیث نقل کی ہے، بعض نے سند سے سارہ کا نام ساقط کر دیا ہے، اور بعض نے عبداللہ کو ساقط کیا ہے۔ ابن ماجہ(2) نے بھی ان کی حدیث نقل کی ہے۔ ابن مندہ کی کتاب المعرفۃ میں ہمیں یہ روایت عالی سند سے ملی ہے۔ اسے ابو نعیم کے طریق سے بحوالہ عبداللہ بن عبد الرحمن طائی، انہوں نے یزید بن مقسم سے، انہوں نے سیدہ میمونہ رضی اللہ عنہا سے روایت کیا ہے کہ وہ سواری پر اپنے والد کے پیچھے بیٹھی تھیں، میں نے اپنے والد سے سنا کہ وہ رسول اللہ صلی اللہ علیہ وسلم سے سوال کر رہے تھے، فرمایا: میں نے نذر مانی ہے کہ بوانہ کے مقام پر اونٹ ذبح کروں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا اس جگہ کوئی بت یا طاغوت ہے؟\" انہوں نے کہا: نہیں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"پھر اپنی نذر پوری کرو۔\" اور اسے مختصر نقل کیا ہے۔ احمد بن حنبل(3) رحمہ اللہ نے بحوالہ یزید بن ہارون، انہوں نے عبید اللہ بن یزید بن مقسم سے، انہوں نے اپنی پھوپھی سارہ بنت مقسم سے، انہوں نے میمونہ بنت کردم سے طویل حدیث نقل کی ہے۔ اس میں سے کچھ میں نے طارق بن مرقع کے سوانح میں ذکر کیا ہے۔ اس میں ہے: بحوالہ میمونہ، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ میں کاتبوں کے درہ سے جیسا ایک درہ تھا میں نے دیہاتیوں کو کہتے سنا: طبطبیۃ طبطبیۃ (زمین پر کوڑا اور قدم لگنے کی آواز) میرے والد آپ کے قریب ہوئے، اور آپ کا پاؤں پکڑ لیا۔ آپ نے ان (میرے والد) کے لیے سواری روک لی۔ فرماتی ہیں: مجھے آپ کے پاؤں کی انگوٹھے کے ساتھ والی انگلی کی لمبائی بقیہ انگلیوں کے مقابلہ میں نہیں بھولے گی۔ میرے والد نے آپ سے عرض کیا: میں جیش عثران میں شریک تھا، حدیث جو طارق کے قصہ میں گزری ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۰۳) الاستيعاب (۳۵۵۶) تجرید (۳۰۷/۲)\n(2) ابن ماجہ (الحدیث: ۲۱۳۱)\n(3) مسند احمد (۳۶۶/۶)"}],[11744,"§۱۱۷۸۳ ۔ میمونہ بنت الولید\nبن حارث بن عامر بن نوفل، عبد اللہ بن ابی ملیکہ جو مشہور تابعی ہیں، ان کی والدہ ہیں، رجال کے حصے میں حرف واؤ کے تحت ان کے والد کے سوانح میں ان کی روایت ہے۔"],[11745,"§۱۱۷۸۴ ۔ مریم بنت ایاس\n(1)بن بکیر لیثیہ۔ انہیں دیدار حاصل ہے، قسم اول میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۶) تجرید ..."}],[11746,"§۱۱۷۸۵ ۔ مرجانہ\nسیدنا عمر رضی اللہ عنہ کی مولاۃ ہیں، معرفہ میں ان کا ذکر ہے۔"],[11747,"§۱۱۷۸۶ ۔ ملیکہ بنت خارجہ\n(1)بن سنان بن ابی حارثہ بن مرہ بن عوف، مستغفری نے محمد بن ثور کے طریق سے بحوالہ ابن جریج، انہوں نے عکرمہ کے حوالے سے ان کا ذکر کیا ہے۔ فرماتے ہیں: اسلام نے ملیکہ بنت خارجہ بن سنان اور ان کے شوہر میں تفریق کرا دی۔ وہ زبان کی زوجہ تھیں، اس کے بعد اس کے بیٹے منظور نے ان سے نکاح کیا۔(2) ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے۔ میں کہتا ہوں: عمر بن شبہ نے کتاب مدینہ میں بحوالہ ابو غسان مدنی ذکر کیا ہے، فرمایا: میں مسجد نبوی صلی اللہ علیہ وسلم میں داخل ہوا، یعنی سیدنا عثمان رضی اللہ عنہ نے اس میں دار عبد الرحمن بن عوف کا اضافہ کیا تھا جسے ملیکہ بنت خارجہ بن سنان بن ابی حارثہ کو ٹھہرایا، جب وہ سیدنا ابوبکر صدیق رضی اللہ عنہ کی خلافت میں مدینہ آئے تھے، وہ زبان بن سیار کی زوجہ تھیں، وہ فوت ہو گئے تو اس کے بیٹے منظور نے ان سے نکاح کر لیا، سیدنا ابوبکر رضی اللہ عنہ انہیں مدینہ لائے اور ان دونوں کے درمیان تفریق کرا دی اور فرمایا: اس خاتون کو کون ٹھہرائے گا؟ سیدنا عبدالرحمن بن عوف نے فرمایا: میں۔ انہوں نے اس گھر میں انہیں ٹھہرایا، گھر کی نسبت ان کی طرف ہو گئی۔ میں نے رجال کے تحت حرف میم کی قسم اول میں منظور کے سوانح میں بیان کیا ہے کہ سیدنا عمر رضی اللہ عنہ کی خلافت میں یہ قصہ پیش آیا ہے، لیکن احتمال ہے کہ وہ دو مرتبہ لائی گئی ہوں، مجھے نہیں معلوم کہ کسی نے عہد نبوی صلی اللہ علیہ وسلم میں ان کے آنے کا ذکر کیا ہو۔ بخلاف منظور کے اس واسطے کہ میں نے ان کے قصہ میں جو بات ذکر کی ہے اس سے اس کا پتہ چلتا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۸۷) تجرید (۳۰۵/۲)\n(2) التفسیر (۱۳۳/۸) (۱۳۴) تفسیر ابن کثیر (۲۱۴/۲) اسد الغابہ (۳۹۹/۵)"}],[11748,"§۱۱۷۸۷ ۔ ملیکہ\nخطیبہ شاعر کی والدہ ہیں، جن کے سوانح میں ان کا ذکر ہے، یہ اس پر دلالت کرتا ہے کہ وہ نبی کریم صلی اللہ علیہ وسلم کے زمانے تک زندہ رہیں۔"],[11749,"§۱۱۷۸۸ ۔ مہدد بنت حمران\nبن بشر بن عمرو بن مرشد، سنان بن علقمہ بن حاجب کی والدہ ہیں، یہ تمیمی کی روایت ہے۔ سنان، ان کے بیٹے، اور ان کے دادا کا ذکر اپنی اپنی جگہ پر گزر چکا ہے۔ انہیں لازماً دور نبوت نصیب ہوا ہے۔ میں نے ابو سعید بن سمعانی کی کتاب الانساب کے مقدمہ میں ان کی سند سے جسے وہ یزید بن سنان بن علقمہ تک لے گئے ہیں، پڑھا کہ انہوں نے حج کیا، تو بنو مہرہ کا ایک آدمی انہیں ملا، اس نے نسب پوچھا تو ان دونوں کے درمیان بحث ہو گئی، یہاں تک کہ ان سے مہری نے کہا: علقمہ کا ایک ہی بیٹا ہے جس کا نام سنان ہے، اور میرا خیال ہے کہ وہ فوت ہو چکا ہے، میں نے کہا: میں یزید ان کا بیٹا ہوں، اس نے کہا: کس بیوی سے؟ میں نے کہا: مہدد بنت حمران سے، پھر وہ قصہ ذکر کیا۔"],[11750,"§۱۱۷۸۹ ۔ میہ بنت محرز\nبنو حارث بن کعب سے ہیں جو اہل بصرہ سے ہیں۔ ابن سعد(1) رحمہ اللہ نے ان کا ذکر ان لوگوں میں کیا ہے جنہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت نہیں کی، اور جید سند سے جو ان تک پہنچتی ہے روایت نقل کی ہے، فرماتی ہیں: میں نے سیدنا عمر بن خطاب رضی اللہ عنہ سے فرماتے ہوئے سنا: \"اس اولاد کو حج کراؤ ان کے حصے مت کھاؤ اور ان کی رسیاں ان کے گلوں میں چھوڑ دو یعنی آزادی دو۔\"","",{"fn":"(1) الطبقات الکبریٰ (۳۴۵/۸)"}],[11751,"§۱۱۷۹۰ ۔ مزیدہ العصریہ\n(1)ابو نعیم نے ان کا ذکر کیا ہے اور قیس بن حفص کے طریق سے بحوالہ طالب بن حجیر، انہوں نے ہود بن عبد اللہ بن سعد سے، انہوں نے اپنی دادی مزیدہ عصریہ سے روایت کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انصار کے جھنڈے بنائے اور انہیں زرد رنگ دیا۔(2) ابو موسیٰ کا قول ہے: اسی طرح مروی ہے، اور مزیدہ عورت نہیں بلکہ مرد ہیں، ابو نعیم نے رجال میں ان کا صحیح تذکرہ کیا ہے۔ ابن اثیر(3) رحمہ اللہ نے ابو موسیٰ کے کلام کی طرح ذکر کیا، پھر فرمایا: وہ مرد ہیں، اور عورتوں میں ان کا ذکر وہم ہے۔ بخاری(4) رحمہ اللہ کا قول ہے: مزیدہ عصری انہیں شرف صحابیت حاصل ہے، ان سے ہود نے روایت کی، اور ان کا شمار بصریوں میں ہوتا ہے، اسی طرح کئی ایک نے ان کا ذکر کیا ہے۔ میں کہتا ہوں: رجال کے تحت حرف میم میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۲۷۸) تجرید (۳۰۴/۲)\n(2) جامع المسانید والسنن (۹۹/۱۶) اسد الغابہ (۳۹۶/۵)\n(3) اسد الغابہ (۳۹۶/۵)\n(4) التاریخ الکبیر (۳۰/۸)"}],[11752,"§۱۱۷۹۱ ۔ میمونہ بنت سعد\n(1)یہ وہی ہیں جن سے امیہ بنت عمر بن عبد العزیز نے روایت کی، بعض نے میمونہ بنت سعد، خادم النبی صلی اللہ علیہ وسلم سے الگ ان کا ذکر کیا ہے۔ میں نے قسم اول میں ان کے بارے میں وضاحت کر دی ہے اور ان کا علیحدہ ذکر ان کے بارے میں وہم ہے، کیونکہ ان کی روایت میں ان کا نسب مذکور نہیں۔","",{"fn":"(1) اسد الغابہ (۷۲۹۹) الاستيعاب (۳۵۵۴) تجرید (۳۰۶/۲)"}],[11753,"§۱۱۷۹۲ ۔ نائلہ بنت الربیع\n(1)بن قیس بن عامر بن عبادہ بن ابجر، وہ خدرہ بن عوف بن حارث بن خزرج انصاریہ ہیں، جو عبد اللہ بن ربیع بدری کی بہن ہیں۔ ابن سعد(2) رحمہ اللہ نے ان کا ذکر کیا ہے اور فرمایا: ان کی والدہ فاطمہ بنت عمرو بن عطیہ ہیں، جو بنو مازن بن نجار سے، ان سے اوس بن خالد بن قرط بن قیس بن وہب نے نکاح کیا جو بنو مالک بن نجار سے ہیں، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) تجرید (۳۰۷/۲)\n(2) الطبقات الکبریٰ (۳۰۷/۲)"}],[11754,"§۱۱۷۹۳ ۔ نائلہ بنت سعد\n(1)بن مالک انصاریہ، بنو ساعدہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۳۰۵) تجرید (۳۰۷/۲)\n(2) اسد الغابہ (۴۰۶/۵)"}],[11755,"§۱۱۷۹۴ ۔ نائلہ بنت سلامہ\n(1)بن وقش، سلمہ بن سلامہ جن کا ذکر گزر چکا ہے اور ام عمرو بنت سلامہ کی بہن ہیں۔ ابن سعد(2) نے ان کا ذکر کیا ہے، اور فرمایا: اسلام لائیں اور بیعت کی، فرماتے ہیں: ان کی والدہ ام عمرو بنت تنیک بن عمرو بحشمتیہ ہیں، فرمایا: عبداللہ بن سمال بن عمرو بن عزیہ سے نکاح کیا، اس کے بعد قیس بن کعب بن قین سلمی سے نکاح کیا، جس سے سہل بن قیس پیدا ہوئے جو غزوہ احد میں شہید ہوئے۔","",{"fn":"(1) تجرید (۳۰۷/۲)\n(2) الطبقات الکبریٰ (۲۸۹/۲)"}],[11756,"§۱۱۷۹۵ ۔ نائلہ بنت عبید\n(1)بن خر بن عمرو بن جعد بن مبذول، بنو مازن بن نجار انصاریہ سے ہیں جو بنو ساعدہ سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا شمار کیا ہے۔(2) اور فرمایا: ان کی والدہ رغیبہ بنت اوس بن خالد بن جعد ہیں، ان سے معمر بن حزم بن زید بن لوذان نے نکاح کیا جس سے عبد الرحمن پیدا ہوئے۔","",{"fn":"(1) تجرید (۳۰۷/۲)\n(2) اسد الغابہ (۴۰۶/۵)"}],[11757,"§۱۱۷۹۶ ۔ تبعہ الحبشیہ\n(1)سیدہ ام ہانی کی باندی ہیں۔ ابو موسیٰ نے ذیل میں ان کا ذکر کیا ہے، اور کلبی کے طریق سے بحوالہ ابو صالح مولی ام ہانی بنت ابو طالب نے رسول اللہ صلی اللہ علیہ وسلم کی اسراء کے بارے میں روایت کی، فرماتی ہیں: جب اسراء کا واقعہ پیش آیا اس رات آپ صلی اللہ علیہ وسلم ہمارے ہاں تھے، آپ صلی اللہ علیہ وسلم نے عشاء کی نماز پڑھی پھر سو گئے، ہم بھی سو گئے، صبح ہم نماز پڑھنے کے لیے اٹھے اور آپ صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، آپ صلی اللہ علیہ وسلم نے فرمایا: اے ام ہانی! میں نے عشاء کی نماز پڑھی جیسا کہ تم نے دیکھا، پھر میں بیت المقدس گیا، اس میں نماز پڑھی، پھر تم لوگوں کے ساتھ فجر کی نماز پڑھی۔\"(2) پھر آپ صلی اللہ علیہ وسلم جانے کے لیے کھڑے ہوئے تو میں نے آپ صلی اللہ علیہ وسلم کی چادر کا پلو پکڑا۔ میں نے کہا: اے اللہ کے نبی صلی اللہ علیہ وسلم! اس بات کو لوگوں سے بیان نہ کریں، وہ اسے جھٹلائیں گے اور آپ کو ایذاء دیں گے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: اللہ کی قسم! میں اسے ضرور بیان کروں گا۔\"(3) راوی بیان کرتے ہیں: وہ فرماتی ہیں کہ میں نے اپنی حبشی باندی سے کہا جسے سبعہ کہا جاتا تھا، لڑی! رسول اللہ صلی اللہ علیہ وسلم کے پیچھے جا اور دیکھے کہ وہ لوگوں سے کیا فرماتے ہیں اور وہ انہیں کیا جواب دیتے ہیں۔ جب رسول اللہ صلی اللہ علیہ وسلم لوگوں کے پاس گئے اور انہیں بتایا تو وہ تعجب کرنے لگے، اور کہنے لگے: اے محمد (صلی اللہ علیہ وسلم)! اس کی کیا نشانی ہے؟۔۔۔۔ پھر وہ حدیث ذکر کی۔ میں کہتا ہوں: اسے ابو یعلیٰ نے یحییٰ بن ابی عمرو شیبانی کے طریق سے بحوالہ ابو صالح مولی ام ہانی، انہوں نے سیدہ ام ہانی رضی اللہ عنہا سے روایت کیا، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم اندھیرے میں ہمارے ہاں تشریف لائے، اس وقت ہم سو رہے تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا تمہیں معلوم ہے میں رات مسجد حرام میں سویا، تو میرے پاس حضرت جبرائیل علیہ السلام آئے۔۔۔۔\"۔ پھر بیت المقدس کی طرف سفر کے بارے میں حدیث نقل کی، راوی فرماتے ہیں، انہوں نے فرمایا: میں نے اپنی باندی صبعہ سے کہا، آپ صلی اللہ علیہ وسلم کے پیچھے جاؤ اور دیکھو وہ لوگوں سے کیا فرماتے ہیں اور وہ انہیں کیا جواب دیتے ہیں؟ فرماتی ہیں: جب تبعہ آئی تو مجھے بتایا کہ آپ صلی اللہ علیہ وسلم قریش کی ایک جماعت کے پاس گئے۔۔۔۔ (الحدیث) اس حدیث میں ہے کہ آپ صلی اللہ علیہ وسلم نے بیت المقدس کے بارے میں بتایا اور سیدنا ابو بکر صدیق رضی اللہ عنہ کا یہ قول ہے کہ آپ صلی اللہ علیہ وسلم نے سچ کہا۔ فرماتی ہیں: میں نے اس دن رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"اے ابوبکر! اللہ تعالیٰ نے تمہارا نام صدیق رکھا ہے۔\" میں کہتا ہوں: یہ کلبی رحمہ اللہ کی روایت سے زیادہ صحیح ہے کہ ان کی روایت میں منکر حصے ہیں کہ آپ صلی اللہ علیہ وسلم نے عشاء اور صبح کی نماز ان کے ساتھ پڑھی جبکہ معراج کی رات نماز فرض ہوئی تھی، اسی طرح سیدہ ام ہانی بھی ان کے گھر اس رات سونا، جبکہ آپ صلی اللہ علیہ وسلم مسجد میں سوئے تھے۔","",{"fn":"(1) اسد الغابہ (۷۳۰۷) تجرید (۳۰۷/۲)\n(2) جامع المسانید والسنن (۵۷۹/۱۰) تفسیر طبری (۳/۱۵) اسد الغابہ (۴۰۶/۵)\n(3) جامع المسانید والسنن (۵۷۹/۱۶) (۵۸۰) تفسیر طبری (۳/۱۵) اسد الغابہ (۴۰۶/۵)"}],[11758,"§۱۱۷۹۷ ۔ نبیتہ\n(1)شہیتہ میں ان کا تذکرہ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۰۶) تجرید (۳۰۷/۲)"}],[11759,"§۱۱۷۹۸ ۔ نتیلہ\n(1)بنت قیس بن جریر بن عمرو بن عوف بن مبذول انصاریہ، بنو مازن سے ہیں، ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۳۰۸) تجرید (۳۰۷/۲)\n(2) اسد الغابہ (۴۰۶/۵)"}],[11760,"§۱۱۷۹۹ ۔ ندبہ\n(1)سیدہ میمونہ رضی اللہ عنہا کی مولاۃ ہیں، سیدہ عائشہ رضی اللہ عنہا کی حدیث میں ان کا تذکرہ ہے۔ ابن مندہ(2) رحمہ اللہ نے مختصراً ان کا ذکر کیا ہے۔(3)","",{"fn":"(1) اسد الغابہ (۷۳۰۹) تجرید (۳۰۷/۲)\n(2) اسد الغابہ (۴۰۶/۵)\n(3) تجرید (۳۰۷/۲)"}],[11761,"§۱۱۸۰۰ ۔ نسیبہ بنت ثابت\nبن عمیر، ابن جوزی نے تنقیح میں ان کا ذکر کیا ہے۔"],[11762,"§۱۱۸۰۱ ۔ نسیبہ\n(1)تصغیر کے ساتھ ہے، بنت حارث انصاریہ، ام عطیہ ہیں، کنیتوں میں ان کا ذکر آئے گا۔","",{"fn":"(1) الاستيعاب (ت: ۳۵۵۸)"}],[11763,"§۱۱۸۰۲ ۔ نسیبہ بنت رافع\n(1)بن معلی بن لوذان بن حارثہ بن عدی بن زید بن ثعلبہ انصاریہ اوسیہ، ابو سعد بن اوس بن معلی کی زوجہ ہیں جو ان کی چچا زاد ہیں، ان کی والدہ بنو عبد اللہ بن غطفان سے ہیں، اسلام لائیں اور بیعت کی، یہ ابن سعد کا قول ہے۔","",{"fn":"(1) تجرید (۳۰۸/۲)"}],[11764,"§۱۱۸۰۳ ۔ نسیبہ بنت سماک\nبن نعمان بن قیس بن عمرو بن امیہ بن زید بن مالک بن عوف بن عمرو بن عوف بن اوس، انصاریہ، اوسیہ۔ ان کی والدہ قسامہ بنت عبداللہ بن امیہ بن عبید بن عمرو بن زید ہیں، ان سے عثمان بن طلحہ عبدری نے جاہلیت میں نکاح کیا جس سے اولاد ہوئی، اس کے بعد ان کے رشتے داروں میں سے بجاد بن عثمان بن عامر بن مجمع نے نکاح کیا۔ نسیبہ اسلام لائیں اور بیعت کی، یہ ابن سعد(1) رحمہ اللہ کا قول ہے۔","",{"fn":"(1) الطبقات الکبریٰ (۲۶۰/۸)"}],[11765,"§۱۱۸۰۴ ۔ نسیبہ بنت ابی طلحہ\nان کا نام ثابت بن عصیمہ بن زید بن مخلد ہے، بنو خطمہ سے ہیں، جو اوس سے ہے، انصاریہ، بنو نظمہ سے ہیں۔ محمد بن سعد نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کرنے والوں میں ان کا ذکر کیا ہے۔ فرمایا: ان کی والدہ ام طلحہ بنت مخلد بن زید بن مخلد ہے۔ ایک قابل اعتماد نسخے میں ان کا نام نون کے زبر کے ساتھ ہے۔"],[11766,"§۱۱۸۰۵ ۔ نسیبہ بنت کعب\n(1)بنت کعب بن عمرو بن عوف بن عمرو بن مبذول بن عمرو بن غنم بن مازن بن نجار انصاریہ، ام عمارہ اپنے نام اور کنیت دونوں سے مشہور ہیں۔ ابن سعد(2) نے یونس بن بکیر وغیرہ کی ان سے مروی روایت میں بیعت عقبہ ثانیہ کا ذکر کرتے ہوئے فرمایا: بنو خزرج سے باسٹھ مرد اور دو عورتیں تھیں، مؤرخین کا بیان ہے کہ دو عورتوں نے نبی کریم صلی اللہ علیہ وسلم سے بیعت کی اور آپ صلی اللہ علیہ وسلم عورتوں سے مصافحہ نہیں کرتے تھے۔ آپ صلی اللہ علیہ وسلم ان سے عہد لیتے، جب وہ اقرار کر لیتیں تو آپ صلی اللہ علیہ وسلم فرماتے: \"جاؤ\"۔ دو عورتیں یہ ہیں: بنو مازن بن نجار سے نسیبہ اور ان کی بہن جو کعب کی بیٹیاں ہیں، پھر نسب بیان کیا، اور فرمایا: ان کے ساتھ ان کے شوہر زید بن عاصم اور ان کے دو بیٹے حبیب جن کو بعد میں مسلمہ نے شہید کیا، اور عبد اللہ جو حدیث الوضو کے راوی ہیں۔ واقدی رحمہ اللہ نے ذکر کیا ہے، جب انہیں معلوم ہوا کہ مسیلمہ نے ان کے بیٹے کو شہید کر دیا ہے تو انہوں نے اللہ تعالیٰ سے عہد کیا کہ مسیلمہ کو قتل کریں گی یا خود شہید ہوں گی۔ یمامہ میں سیدنا خالد بن ولید کے ساتھ شریک تھیں، ان کے ساتھ ان کا بیٹا عبداللہ تھا۔ مسیلمہ مارا گیا اور لڑائی میں ان کا ہاتھ کٹ گیا، ابو عمر فرماتے ہیں: غزوہ احد میں وہ اپنے شوہر زید بن عاصم کے ساتھ شریک تھیں۔ میں کہتا ہوں: ابن ہشام نے زیادات میں ام سعد بنت سعد بن ربیع کے طریق سے نقل کیا ہے، فرماتے ہیں: میرے پاس ام عمارہ آئیں، میں نے پوچھا: اے خالہ! مجھے بتائیے؟ انہوں نے کہا: میں احد کے دن نکلی میرے ساتھ پانی کا مشکیزہ تھا۔ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اس وقت آپ صلی اللہ علیہ وسلم اپنے اصحاب کے پاس تھے، غنیمت اور فتح اس وقت مسلمانوں کا پلہ بھاری تھا اور انہیں دبدبہ حاصل تھا۔ جب مسلمانوں کو شکست ہونے لگی تو میں رسول اللہ صلی اللہ علیہ وسلم کی طرف چلی اور کفار سے قتال کرنے لگی اور انہیں تلوار کے ساتھ آپ صلی اللہ علیہ وسلم سے دور کرنے اور تیر اندازی کرنے لگی، یہاں تک کہ مجھے زخم آئے۔ راوی کہتے ہیں کہ میں نے ان کے کندھے پر گہرا زخم دیکھا۔ میں نے پوچھا: آپ کو یہ کس نے مارا؟ کہنے لگیں: ابن قمیہ نے۔ ابو عمر کا قول ہے: بیعت رضوان میں حاضر تھیں، پھر یمامہ میں شریک ہوئیں، اس میں ان کا ہاتھ کٹ گیا اور بارہ زخم آئے، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے یہ روایت کی: \"روزہ دار کے سامنے جب تک کھایا جاتا رہے فرشتے اس کے لیے دعا کرتے رہتے ہیں۔\"(3) میں کہتا ہوں: ان کے بیٹے عباد بن تمیم، ان کی مولاۃ لیلیٰ، عکرمہ، حارث بن کعب، ام سعد بن ربیع نے ان سے روایت کیا، سنن اربعہ میں ان کی حدیث مروی ہے۔","",{"fn":"(1) اسد الغابہ (۱۷۳۱۱) تجرید (۳۰۸/۲)\n(2) السیرۃ النبویۃ (۸۳/۲)\n(3) ترمذی (۷۸۵) الإکمال (۲۵۹/۱۷)"}],[11767,"§۱۱۸۰۶ ۔ نسیبہ بنت نیار\n(1)بن حارث انصاریہ، بنو جعجبی سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا شمار کیا ہے۔ ابن اثیر(2) نے بھی ام عمارہ کے بعد ان کا ذکر کیا ہے، جس کا تقاضا ہے کہ نون پر زبر ہے۔ ان کا نام تصغیر کے ساتھ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۱۲) تجرید (۳۰۸/۲)\n(2) اسد الغابہ (۴۰۷/۵)"}],[11768,"§۱۱۸۰۷ ۔ نسیبہ بنت نیار\nبن حارث بن بلال بن احیحہ بن جلاح انصاریہ، ان کے رشتہ داروں میں سے عقبہ بن عبدود بن عقبہ بن احیحہ بن جلاح نے ان سے نکاح کیا۔ اسلام لائیں اور بیعت کی، یہ ابن سعد(1) کا قول ہے، میں نے طبقات کے قابل اعتماد نسخے میں تصغیر کے ساتھ لکھا دیکھا ہے۔ بعض کا قول ہے: زبر کے ساتھ ہے، جیسا کہ آگے آئے گا۔","",{"fn":"(1) الطبقات الکبریٰ (۲۵۶/۸)"}],[11769,"§۱۱۸۰۸ ۔ نسیکہ\n(1)عمرو بن جلاس کی والدہ ہیں، ان سے حبیبہ بنت سمعان نے روایت کی، طبرانی(2) ابراہیم بن اسماعیل بن ابی حبیبہ سے، انہوں نے حبیبہ بنت سمعان سے، انہوں نے نسیکہ بنت عمرو بن جلاس سے روایت کیا، فرماتی ہیں: میں سیدہ عائشہ رضی اللہ عنہا کے پاس تھی، انہوں نے اپنی بکری ذبح کی، رسول اللہ صلی اللہ علیہ وسلم تشریف لائے، آپ صلی اللہ علیہ وسلم کے ہاتھ میں لاٹھی تھی، آپ نے اسے پھینک دیا پھر مسجد کی طرف تشریف لے گئے، آپ صلی اللہ علیہ وسلم نے اس میں دو رکعت نماز پڑھی پھر اپنے بستر پر آئے اور اس پر دراز ہو گئے، پھر فرمایا: \"کیا کھانے کی کوئی شے ہے؟\" ہم آپ صلی اللہ علیہ وسلم کے پاس ایک پیالہ لائے، اس میں جو کی روٹی اور ایک ٹکڑا، تھوڑی سی اوجھ اور کندھے کا گوشت تھا، سیدہ عائشہ رضی اللہ عنہا نے اوجھ کا ٹکڑا لیا اور اسے دانتوں سے نوچنے لگیں، میں نے کہا: ہم نے آج بکری ذبح کی، جس میں سے اس کے علاوہ کچھ نہیں بچا، آپ صلی اللہ علیہ وسلم نے فرمایا: نہیں! بلکہ اس کے علاوہ سب بچا لیا۔","",{"fn":"(1) اسد الغابہ (۷۳۱۳) تجرید (۳۰۸/۲)\n(2) المعجم الکبیر (۸۳/۲۵)"}],[11770,"§۱۱۸۰۹ ۔ نعامہ\n(1)بنو عنبر کے قیدیوں میں سے تھیں، حسین و جمیل تھیں۔ نبی کریم صلی اللہ علیہ وسلم نے انہیں شادی کی پیشکش کی، کچھ ہی عرصے بعد ان کے شوہر حریش آگئے۔(2) حرف حاء میں حریش جن کا ذکر ہے، کے سوانح میں یہ سند کے ساتھ گزر چکا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۱۴) تجرید (۳۰۸/۲)\n(2) اسد الغابہ (۴۰۸/۵)"}],[11771,"§۱۱۸۱۰ ۔ نعم\n(1)بنت حسان، سیدنا شماس بن عثمان مخزومی کی زوجہ تھیں، ابن اسحاق(2) نے ان کے وہ اشعار نقل کیے ہیں جو انہوں نے اپنے خاوند کی احد میں شہادت کے موقعہ پر مرثیہ میں کہے تھے: ؎ \"اے میری آنکھ! بلا رکاوٹ آنسو بہاتی چلی جا ایسے نوجوان پر جو شرافت والا اور دشمنوں کو چقمہ دینے والا تھا۔ اس کا بے ساختہ حملہ بڑا سخت ہوتا تھا وہ بڑے بخت ونصیب والا تھا۔ اکثر جھنڈا اس کے ہاتھ ہوتا اور یکے بعد دیگرے کئی گھوڑوں پر سوار ہوتا تھا۔ جب اس کی عدم موجودگی کی وجہ سے مجالس خالی ہو گئیں تو میں کہتی ہوں: ہم سے شماس کا قرب دُور نہ ہو!\" ابن دباغ(3) نے بحوالہ ابو علی الغسانی اپنے استدراک میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۱۵) تجرید (۳۰۸/۲)\n(2) السیرۃ النبویۃ (۱۳۳/۳)\n(3) اسد الغابہ (۴۰۸/۵)"}],[11772,"§۱۱۸۱۱ ۔ نعمی بنت جعفر بن ابی طالب\n(1)ابن مندہ کا قول ہے کہ ان کا ذکر موجود ہے، اور ان سے کوئی حدیث مروی نہیں۔ میں کہتا ہوں: طبرانی(2) نے عبد الوہاب بن عطاء کے طریق سے، بحوالہ ابن جریج، انہوں نے عطاء سے، انہوں نے اسماء بنت عمیر سے اسے مندرجہ ذیل نقل کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم نے نعمی بنت جعفر بن ابی طالب سے فرمایا: \"کیا وجہ ہے کہ جعفر کے بیٹے کمزور نظر آ رہے ہیں، کیا انہیں فقر و فاقہ ہے؟\" انہوں نے کہا: نہیں، انہیں نظر بہت جلد لگ جاتی ہے۔ کیا میں انہیں دم کر دوں؟ فرماتی ہیں: میں نے آپ صلی اللہ علیہ وسلم کے سامنے ایسے کلمات پڑھے جن میں کوئی ضرر نہیں تھا۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں دم کر دو۔\"(3) ابن اثیر(4) کا قول ہے: یہ خبر معروف سیدہ اسماء رضی اللہ عنہا کے بارے میں ہے، مجھے معلوم نہیں کہ یہ سیدنا جعفر رضی اللہ عنہ کی اولاد کے بارے میں ہے۔ میں کہتا ہوں: مجھے لگتا ہے کہ اس حدیث میں لفظی غلطی ہے۔ صحیح یہ ہے کہ آپ صلی اللہ علیہ وسلم نے انہیں سیدنا جعفر رضی اللہ عنہ کے گھر میں یہ فرمایا۔۔۔ الخ۔","",{"fn":"(1) اسد الغابہ (۷۳۱۶) تجرید (۳۰۸/۲)\n(2) المعجم الکبیر (۸۱/۲۵)\n(3) مسند احمد (۴۲۸/۶)\n(4) اسد الغابہ (۴۰۸/۵)"}],[11773,"§۱۱۸۱۲ ۔ نفیسہ بنت امیہ\n(1)سیدنا یعلی کی بہن ہیں، ان کے بھائی کے سوانح میں ان کا نسب گزر چکا ہے۔ ابو عمر کا قول ہے: انہیں شرف صحابیت اور روایت حاصل ہے۔ ابن سعد(2) کا قول ہے: ان کی والدہ منیہ بنت جابر بن وہب ہیں، نفیسہ بنت منیہ اسلام لائیں، یہ وہی ہیں جو سیدہ خدیجہ رضی اللہ عنہا کے پاس نبی کریم صلی اللہ علیہ وسلم کا پیغام نکاح لے کر گئی تھیں، یہاں تک کہ آپ صلی اللہ علیہ وسلم نے ان سے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (۷۳۱۷) الاستيعاب (۳۵۵۹) تجرید (۳۰۱/۲)\n(2) الطبقات الکبریٰ (۱۷۸/۸)"}],[11774,"§۱۱۸۱۳ ۔ نفیسہ بنت ثعلبہ\nانیسہ کے سوانح میں ان کا ذکر گزر چکا ہے۔"],[11775,"§۱۱۸۱۴ ۔ نفیسہ بنت عمرو\n(1)بن خلدہ بن مخلد الانصاری۔ بنو زریق سے ہیں، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۱۸) تجرید (۳۰۸/۲)\n(2) المحبر (۴۲۵)"}],[11776,"§۱۱۸۱۵ ۔ نفیسہ جاریہ زینب بنت جحش\n(1)جب نبی کریم صلی اللہ علیہ وسلم ان سے ناراض ہوئے اور ایک مہینہ انہیں چھوڑے رکھا تو راضی ہونے کے بعد انہیں آپ صلی اللہ علیہ وسلم کو ہبہ کر دیا۔ علی بن احمد بن یوسف نے کتاب اخبار النساء میں ان کا نام لیا ہے، اصل قصہ مسند احمد میں ہے، انہوں نے ان کا نام نہیں لیا۔","",{"fn":"(1) اسد الغابہ (۷۳۱۹) تجرید (۳۰۸/۲)"}],[11777,"§۱۱۸۱۶ ۔ نہیہ (ام ولد عمر)\n(1)حرف لام میں کہیہ میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) تجرید (۳۰۸/۲)"}],[11778,"§۱۱۸۱۷ ۔ النوار بنت حارث بن قیس\n(1)انصاریہ۔۔۔۔ قیطی بن عمرو کی زوجہ ہیں، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۱۹) تجرید (۳۰۸/۲)\n(2) الطبقات الکبریٰ (۲۵۵/۸)"}],[11779,"§۱۱۸۱۸ ۔ النوار بنت قیس بن حارث\n(1)بن عدی بن نثم بن محمد بن حارثہ انصاریہ۔ عدی نے انصار کے نسب میں ان کا ذکر کیا ہے، ابو علی بجائی نے اپنے استدراک میں ان کا ذکر کیا ہے، ابن سعد کا قول ہے:(2) ان کے والد کی کنیت ان کے نام پر تھی، ان سے زید بن ثویرہ بن حارث بن عدی بن نثم نے نکاح کیا، جس سے غازی پیدا ہوئے۔ نوار اسلام لائیں اور رسول اللہ صلی اللہ علیہ وسلم سے بیعت کی۔","",{"fn":"(1) اسد الغابہ (۷۳۱۹) تجرید (۳۰۸/۲)\n(2) الطبقات الکبریٰ (۲۵۵/۸)"}],[11780,"§۱۱۸۱۹ ۔ النوار بنت قیس\nبن لوذان بن عدی بن مجدعہ انصاریہ۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔"],[11781,"§۱۱۸۲۰ ۔ النوار بنت مالک\n(1)بن صرمہ بن مالک بن عدی بن نجار، انصاریہ۔۔۔۔ بنو عدی بن نجار سے ہیں۔ ابن سعد کا قول ہے: ان کی والدہ سلمی بنت عامر بن مالک بن عدی ہیں، جو زید بن ثابت کی والدہ ہیں جو مشہور صحابی اور زید کے بھائی ہیں، انہوں نے نبی کریم صلی اللہ علیہ وسلم سے روایت کی، اور ان سے ام سعد، بنت اسعد بن زرارہ نے روایت کیا۔ سیدنا ثابت کے بعد ان سے عمارہ بن حزم نے نکاح کیا، جس سے مالک پیدا ہوئے۔(2) اور ثابت بن عبید کے طریق سے ذکر کیا، فرماتے ہیں: زید بن ثابت نے اپنی والدہ کی نماز جنازہ میں چار تکبیریں کہیں۔","",{"fn":"(1) اسد الغابہ (۷۳۲۱) الاستيعاب (۳۵۶۰) تجرید (۳۰۸/۲)\n(2) اسد الغابہ (۴۰۹/۵)"}],[11782,"§۱۱۸۲۱ ۔ نوبہ خادم النبی صلی اللہ علیہ وسلم\n(1)ابو موسیٰ نے خواتین میں ان کا ذکر کیا ہے،(2) اور عبد اللہ بن سعید نے مہمات میں ان کا نسب بیان کیا ہے۔ حدیث زائدہ میں بحوالہ عاصم، انہوں نے ابو وائل سے، انہوں نے مسروق سے اور انہوں نے سیدہ عائشہ رضی اللہ عنہا سے ان کا ذکر کیا ہے، فرماتی ہیں: نبی کریم صلی اللہ علیہ وسلم شدید بیمار ہوئے، آپ صلی اللہ علیہ وسلم کے مرض کی شدت کم ہوئی تو سیدہ بریرہ اور نو بہ کے سہارے باہر تشریف لائے۔ میں کہتا ہوں: اس میں تصریح نہیں کہ وہ خاتون ہے، سیف بن عمر کی کتاب الردۃ کی روایت سے پتہ چلتا ہے کہ وہ مرد ہیں، بحوالہ مسلمہ بن عطیہ، انہوں نے نعیم بن ابی ہند سے، انہوں نے شقیق بن سلمہ سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم تشریف لائے اور سیدنا ابو بکر صدیق رضی اللہ عنہ نماز شروع کرا چکے تھے۔ آپ صلی اللہ علیہ وسلم نے غلام نو بہ اور بریرہ کا سہارا لیا، پھر حدیث ذکر کی۔ لیکن یعقوب بن سفیان نے اپنی تاریخ میں اسے معتمر بن سلیمان کے طریق سے بحوالہ تمیم بن ابی ہند اس سند سے اسے نقل کیا ہے، فرماتے ہیں: نو بہ اور بریرہ آئیں اور آپ صلی اللہ علیہ وسلم کو سہارا دیا۔۔۔۔ (الحدیث) ابو موسیٰ نے بھی اسے اپنے طریق سے نقل کیا ہے، اس سے ظاہر ہوتا ہے کہ وہ خاتون ہیں، اگر وہ مرد ہوتے تو مذکر کا صیغہ استعمال کرتے۔ اسی بنا پر انہوں نے کہا ان دونوں مردوں نے آپ صلی اللہ علیہ وسلم کو سہارا دیا۔","",{"fn":"(1) اسد الغابہ (۷۳۲۲) تجرید (۳۰۸/۲)\n(2) اسد الغابہ (۴۰۹/۵)"}],[11783,"§۱۱۸۲۲ ۔ نوبہ بنت اسلم\n(1)یا مسلم انصاریہ جاریہ، بعض کا قول ہے: تویل۔ اسحاق بن ادریس نے بحوالہ جعفر بن محمود اسے نون کے ساتھ ذکر کیا ہے۔ ابراہیم بن حمزہ کی روایت گزر چکی، وہ زیادہ قابل اعتماد ہے۔ فوت: قسم ثانی اور قسم ثالث دونوں ہیں۔","",{"fn":"(1) اسد الغابہ (۷۳۲۳) الاستيعاب (۳۵۶۱) تجرید (۳۰۹/۲)"}],[11784,"§۱۱۸۲۳ ۔ نبیشہ بنت کعب\nبعض نے ان کے نام میں لفظی غلطی کی ہے۔ یہ ام عمارہ وہی ہیں جن کا کنیتوں میں ذکر ہے۔"],[11785,"§۱۱۸۲۴ ۔ ہالہ بنت خویلد\n(1)بن اسد بن عبد العزیٰ قرشیہ، اسدیہ، سیدہ خدیجہ رضی اللہ عنہا کی بہن ہیں جو نبی کریم صلی اللہ علیہ وسلم کی زوجہ ہیں۔ ابو العاص بن ربیع کی والدہ ہیں۔ ابن مندہ کا قول ہے: ان سے سیدہ عائشہ رضی اللہ عنہا نے کچھ حدیث کا لفظ نقل کیا ہے۔ ایسے انہوں نے اسے مختصر کیا ہے شاید انہوں نے صحیح میں بخاری(2) کی روایت کی طرف اشارہ کیا ہے جو علی بن نصر کے طریق سے بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی ہے۔ فرماتی ہیں: سیدہ ہالہ بنت خویلد جو سیدہ خدیجہ رضی اللہ عنہا کی بہن ہیں، نبی کریم صلی اللہ علیہ وسلم سے آنے کی اجازت طلب کی، آپ صلی اللہ علیہ وسلم کی سیدہ خدیجہ رضی اللہ عنہا کا اجازت طلب کرنا یاد آگیا۔ آپ صلی اللہ علیہ وسلم خوش ہو گئے، اور فرمایا: \"یہ تو ہالہ ہیں\"۔ مجھے غیرت آئی اور میں نے کہا: آپ قریش کی ایک بوڑھیا کو یاد کرتے ہیں۔۔۔۔ (الحدیث) اسے ابو نعیم نے اس طریق سے نقل کیا ہے، اصل حدیث صحیحین میں ہے، جس میں ہالہ کا ذکر نہیں۔","",{"fn":"(1) اسد الغابہ (۷۳۲۴) تجرید (۳۰۹/۲)\n(2) بخاری (حدیث: ۳۸۲۱)"}],[11786,"§۱۱۸۲۵ ۔ ہالہ بنت عوف الزہریہ\nان کے بھائی عبد الرحمن بن عوف کے ساتھ جو عشرہ مبشرہ میں سے ہیں، ان کا نسب گزر چکا ہے۔ دار قطنی نے حنظلہ بن ابی سفیان ثقفی کے طریق سے بحوالہ اپنی والدہ روایت کیا ہے، فرماتی ہیں: میں نے دیکھا کہ عبد الرحمن بن عوف کی بہن سیدنا بلال رضی اللہ عنہ کی زوجہ ہیں۔ امام رافعی نے شرح الوجیز میں کتاب الکفاءۃ میں ان کا نام ہالہ لکھا ہے۔"],[11787,"§۱۱۸۲۶ ۔ ہجیمہ\nبعض کا قول ہے: یہ صماء کا نام ہے جو سیدنا عبد اللہ بن بسر کی بہن ہیں۔"],[11788,"§۱۱۸۲۷ ۔ ہریرہ بنت زمعہ القرشیہ\n(1)اسدیہ، ام المؤمنین سیدہ سودہ رضی اللہ عنہا کی بہن ہیں، ان کی بہن کے سوانح میں ان کا نسب گزر چکا ہے، طبری نے صحابہ رضی اللہ عنہم میں ان کا ذکر کیا ہے۔ مستغفری کا قول ہے: انہیں شرف صحابیت حاصل ہے۔ معبد بن وہب عبدی کے سوانح میں گزر چکا ہے کہ انہوں نے ان سے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (۷۳۲۶) تجرید (۳۰۹/۲)"}],[11789,"§۱۱۸۲۸ ۔ ہزیلہ بنت ثابت\n(1)بن ثعلبہ بن جلاس بن مالک، اغر انصاریہ، ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد(3) کا قول ہے: ان سے ثابت بن حارث بن ثعلبہ بن جلاس نے نکاح کیا، ان کے بعد عبد الرحمن بن ساعدہ نے نکاح کیا، ابن سعد کا قول ہے: ہزیلہ اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (۷۳۲۷) تجرید (۳۰۹/۲)\n(2) المحبر (۴۲۱)\n(3) الطبقات الکبریٰ (۲۶۲/۸)"}],[11790,"§۱۱۸۲۹ ۔ ہزیلہ بنت الحارث\n(1)بن حزن ہلالیہ، ام المؤمنین سیدہ میمونہ کی بہن ہیں، بعض کا قول ہے: یہ ام حفید ہیں، کنیتوں میں جن کا ذکر آ رہا ہے۔ یہ ابو عمر کا قول ہے: فرماتے ہیں: انہوں نے دیہات میں شادی کی، یہ وہی ہیں جنہوں نے گوہ ہدیہ میں دی، سلیمان بن یسار وغیرہ نے سیدہ میمونہ رضی اللہ عنہا سے ان کی حدیث روایت کی۔ میں کہتا ہوں: امام مالک(2) نے اسے موطا میں بحوالہ عبد الرحمن بن ابی صعصعہ، انہوں نے سلیمان بن یسار سے روایت کی ہے، فرماتے ہیں: نبی کریم صلی اللہ علیہ وسلم نے سیدہ میمونہ بنت حارث رضی اللہ عنہا کے گھر تشریف لائے تو وہاں گوہ کا سالن تھا، آپ صلی اللہ علیہ وسلم کے ساتھ سیدنا عبد اللہ بن عباس، سیدنا خالد بن ولید رضی اللہ عنہم تھے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ کہاں سے آیا؟\" سیدنا عبد اللہ اور خالد رضی اللہ عنہما نے عرض کیا: \"یہ ہزیلہ بنت حارث نے مجھے ہدیہ میں دیا۔\" آپ صلی اللہ علیہ وسلم نے فرمایا: \"کھاؤ۔\" ان دونوں نے کہا: کیا آپ صلی اللہ علیہ وسلم نہیں کھائیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میرے پاس اللہ تعالیٰ کی طرف سے فرشتہ آتا ہے۔\" صحیحین میں اصل حدیث سعید بن جبیر کے طریق سے بحوالہ ابن عباس رضی اللہ عنہما مروی ہے، فرماتی ہیں: میری خالہ ام حفید بنت حارث نے نبی کریم صلی اللہ علیہ وسلم کی طرف گھی، پنیر اور گوہ ہدیہ میں بھیجی، خیز گوہ ہدیہ میں بھیجی، آپ صلی اللہ علیہ وسلم نے ان عورتوں کو بلایا اور انہوں نے دستر خوان پر ان چیزوں کو کھایا۔۔۔۔ (الحدیث) اسے ابو داؤد وغیرہ نے عمر بن کرملہ کی روایت سے بحوالہ ابن عباس رضی اللہ عنہما روایت کیا ہے۔ مسند ابن ابی عمر عدنی میں اس طریق سے حج کے بجائے تین کے ساتھ ام حفید مروی ہے۔ معروف ام حفید ہے۔ واللہ اعلم!","",{"fn":"(1) اسد الغابہ (۷۳۲۸) الاستيعاب (۳۵۶۲) تجرید (۳۰۹/۲)\n(2) موطا مالک (الحدیث: ۱۸۵۶)"}],[11791,"§۱۱۸۳۰ ۔ ہزیلہ بنت سعید\n(1)بن سہیل بن مالک بن کعب بن عبد الاشہل بن حارث بن دینار بن نجار انصاریہ۔ ابن سعد(2) اور ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے، ابن سعد کا قول ہے: ان کی والدہ فاطمہ بنت خدیج بن ابو بن قرقر بن ضحیان ہیں، جو بنو حرام کے حلیف تھے۔","",{"fn":"(1) اسد الغابہ (۷۳۲۹) تجرید (۳۰۹/۲)\n(2) الطبقات الکبریٰ (۲۲۰/۸)"}],[11792,"§۱۱۸۳۱ ۔ ہزیلہ بنت عتبہ\n(1)بن عمرو بن خدیج بن عامر بن نثم بن حارث بن خزرج انصاریہ۔ زید بن خارجہ کی والدہ ہیں۔ جنہوں نے سیدنا عثمان رضی اللہ عنہ کے زمانے میں موت کے بعد بات کی تھی۔ ابن سعد(2) کا قول ہے: اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (۷۳۳۰) تجرید (۳۰۹/۲)\n(2) الطبقات الکبریٰ (۲۶۴/۸)"}],[11793,"§۱۱۸۳۲ ۔ ہزیلہ بنت مسعود\n(1)بن زید انصاریہ، بنو حرام سے ہیں۔ ابن حبیب(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۳۱) تجرید (۳۰۹/۲)\n(2) الطبقات الکبریٰ (۲۹۷/۸)"}],[11794,"§۱۱۸۳۳ ۔ ہمینہ بنت خلف\n(1)بن اسعد بن عامر بن بیاضہ بن ریبعہ خزاعیہ، ابن سعد(2) کا قول ہے: اسلام کے ابتدائی دور میں اسلام لائیں، اور اپنے شوہر خالد بن سعید کے ساتھ حبشہ کی طرف ہجرت کی، وہاں سعید اور آمنہ پیدا ہوئے، ابن زبیر اس کے بعد آمنہ سے شادی کی۔","",{"fn":"(1) اسد الغابہ (۷۳۳۲) تجرید (۳۰۹/۲)\n(2) الطبقات الکبریٰ (۳۰۹/۸)"}],[11795,"§۱۱۸۳۴ ۔ ہند بنت ابی بن خلف\nجمحیہ، مسعود بن امیہ بن خلف کی زوجہ اور ان کے بیٹے عامر کی والدہ ہیں، زبیر بن بکار نے ان کا ذکر کیا ہے۔"],[11796,"§۱۱۸۳۵ ۔ ہند بنت اثاثہ\n(1)بن عباد بن مطلب بن عبد مناف، قرشیہ، مطلبیہ۔ مسطح کی بہن ہیں۔ ابن اسحاق(2) نے مکہ میں اسلام لانے والوں میں ان کا ذکر کیا ہے۔ احد کے واقعہ میں فرمایا: جب ہند بنت عتبہ نے سیدنا حمزہ رضی اللہ عنہ اور دوسرے مسلمانوں کے قتل کی وجہ سے فخر کرنے لگی اور ایک بلند ٹیلے پر چڑھ کر بلند آواز سے پکارا: ؎ \"ہم نے تمہیں بدر کا بدلہ دیا ہے جنگ کے بعد جنگ بھڑکے گی۔ عتبہ کے بارے مجھ سے صبر نہیں ہو سکتا، میرا والد، میرا چچا اور میرا جواں سال بھائی مارا گیا۔ وحشی نے میرے دل کی بھڑاس نکال دی۔ میرا جی بھی خوش ہو گیا اور میری نذر بھی پوری ہو گئی۔\" فرماتے ہیں، انہیں ہند بنت اثاثہ بن مطلب نے جواب دیا: ؎ \"تجھے بدر کیا، بدر سے باہر بھی رسوائی کا سامنا کرنا پڑا، اے بڑے والے واقع ہونے والے کی بیٹی! صبح کے تڑکے، دراز قد، بارونق چہروں والے ہاشمیوں سے اللہ تعالیٰ تیرا سامنا کرائے۔ جن میں دولخت تلوار کاٹ کر جدا کرنے والے ہوں گے: حمزہ میرا شیر اور علی میرا شکرہ ہے۔\" ابن اسحاق(3) نے نبی کریم صلی اللہ علیہ وسلم کے بارے میں ان کا مرثیہ نقل کیا۔ ابن سعد کا قول ہے: نبی کریم صلی اللہ علیہ وسلم نے ان کے بھائی مسطح کے ساتھ تھیں(۳۰) وسق کھجوریں کھانے کو دیں، انہوں نے خاندان سے باہر ابو جندب سے نکاح کیا، جس سے ایک بیٹی ریطہ پیدا ہوئی۔","",{"fn":"(1) اسد الغابہ (۷۳۳۳) تجرید (۳۰۹/۲)\n(2) السیرۃ النبویۃ (۷۲/۳)\n(3) السیرۃ النبویۃ (۷۲) (۳۵/۳)"}],[11797,"§۱۱۸۳۶ ۔ ہند بنت اسید\n(1)بن ہذیل انصاری۔ ان کا نسب ان کے والد کے ساتھ بیان ہو چکا ہے۔ ابن مندہ کا قول ہے کہ محمد بن عبد الرحمن بن سعد بن زرارہ کی حدیث میں ان کا ذکر ہے۔ ابو عمر کہتے ہیں کہ ابو رجال نے بواسطہ ان کے نبی علیا نام کی یہ حدیث نقل کی ہے کہ آپ قرآنی الفاظ میں خطاب کرتے تھے۔ فرماتی ہیں کہ میں نے سورہ قاف آپ صلی اللہ علیہ وسلم سے منبر پر بکثرت سن کر یاد کر لی۔","",{"fn":"(1) اسد الغابہ (۷۳۳۴) الاستيعاب (۳۵۶۴) تجرید (۳۰۹/۲)"}],[11798,"§۱۱۸۳۷ ۔ ہند بنت اوس\n(1)بن شریق، سعد بن خیثمہ انصاریہ کی والدہ ہیں، بنو خطمہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۳۳۶) تجرید (۳۱۰/۲)\n(2) اسد الغابہ (۴۱۴/۵)"}],[11799,"§۱۱۸۳۸ ۔ ہند بنت اوس\n(1)بن عدی بن امیہ انصاریہ۔ بنو خطمہ سے ہیں۔ ابن حبیب نے ان کا بھی ذکر کیا ہے۔","",{"fn":"(1) تجرید (۳۱۰/۲)"}],[11800,"§۱۱۸۳۹ ۔ ہند بنت البراء بن معرور\n(1)انصاریہ۔ جابر بن عتیک کی زوجہ ہیں، ابن سعد(2) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۳۵) تجرید (۳۱۰/۲)\n(2) الطبقات الکبریٰ (۲۹۸/۸)"}],[11801,"§۱۱۸۴۰ ۔ ہند بنت حارث\n(1)بن عبد المطلب بن ہاشم، نبی کریم صلی اللہ علیہ وسلم کی چچا زاد ہیں۔ محمد بن سعد نے نبی کریم صلی اللہ علیہ وسلم کی وفات پر ان کا مرثیہ نقل کیا ہے۔","",{"fn":"(1) تجرید (۳۱۰/۲)"}],[11802,"§۱۱۸۴۱ ۔ ہند بنت ابی امیہ\nان کا نام حذیفہ تھا، بعض کا قول ہے: سہل بن مغیرہ بن عبد اللہ بن عمر بن مخزوم قرشیہ مخزومیہ، ام المؤمنین، ام سلمہ، اپنی کنیت سے مشہور ہیں اور اپنے نام سے پہچانی جاتی ہیں۔ بعض کا شاذ قول یہ ہے کہ ان کا نام سلمہ ہے اور ان کے والد کا لقب زاد الراکب(1) تھا، کیونکہ وہ بہت سختی تھے۔ جب وہ سفر کرتے تو ان کے ساتھیوں میں سے کوئی زاد راہ نہ لیتا، کیونکہ وہ ان کی کفایت کرتے تھے، ان کی والدہ عاتکہ بنت عامر کنانیہ ہیں، بنو فراس سے تھے، اور ابو سلمہ بن عبد الاسد کی زوجہ تھیں، جو ان کے چچا زاد تھے، ان کے ساتھ حبشہ کی طرف پھر مدینہ کی طرف ہجرت کی، کہا جاتا تھا کہ وہ پہلی مسافر خاتون ہیں جو ہجرت کر کے مدینہ آئیں۔ جب ان کے شوہر زخمی ہو کر وفات پا گئے تو نبی کریم صلی اللہ علیہ وسلم نے انہیں نکاح کا پیغام دیا۔ ابن ابی عاصم(2) نے عبد الواحد بن ایمن کے طریق سے بحوالہ ابو بکر بن عبد الرحمن، انہوں نے سیدہ ام سلمہ رضی اللہ عنہا سے روایت کیا ہے، فرماتی ہیں: جب نبی کریم صلی اللہ علیہ وسلم نے مجھے نکاح کا پیغام دیا، میں نے آپ صلی اللہ علیہ وسلم سے کہا: میری تین صفات ہیں: میں بڑی عمر والی ہوں، صاحب عیال ہوں، سخت غیرت والی ہوں۔ آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں تم سے بڑا ہوں، اور عیال اللہ کے سپرد ہیں، رہی غیرت تو میں اللہ سے دعا کروں گا وہ اسے تم سے دور کر دے گا۔\" آپ صلی اللہ علیہ وسلم نے ان سے نکاح کیا، جب ان کے پاس آئے تو فرمایا: \"اگر تم چاہو تو ساتواں دن تمہارے لیے مقرر کر دوں\"۔ تو وہ تین دنوں پر راضی ہو گئیں۔ صحیح میں یہ حدیث کئی طرق سے مروی ہے۔ ابن سعد نے عاصم احول کے طریق سے بحوالہ زیاد بن ابی مریم نقل کیا ہے، فرماتے ہیں: سیدہ ام سلمہ رضی اللہ عنہا نے سیدنا ابو سلمہ رضی اللہ عنہ سے فرمایا: مجھے معلوم ہوا ہے، جس عورت کا خاوند فوت ہو جائے اور وہ شخص جنتی ہو پھر وہ عورت اس کے بعد نکاح نہ کرے تو اللہ تعالیٰ انہیں جنت میں اکٹھا کر دے گا، اسی طرح کوئی عورت مر جائے اور خاوند پیچھے رہ جائے۔ آؤ ہم عہد کریں کہ ہم آپ کے بعد نکاح نہ کریں گی، اور آپ میرے بعد شادی نہ کریں۔ انہوں نے کہا: \"کیا تم میرا کہا مانوں گی؟\" انہوں نے کہا: میں جب آپ سے مشورہ لیتی ہوں تو آپ کی اطاعت کرتی ہوں۔ انہوں نے کہا: اگر میں مر گیا تو نکاح کر لینا، پھر فرمایا: \"اے اللہ! میرے بعد ام سلمہ کو ایسا خاوند عطا فرما جو اسے رسوا نہ کرے، نہ ہی ایذا دے۔\" فرماتی ہیں، جب وہ فوت ہو گئے تو میں نے کہا: ابو سلمہ سے بہتر کون ہو سکتا ہے۔ تھوڑا عرصہ ہی گزرا تھا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے نکاح کر لیا۔ صحیح میں سیدہ ام سلمہ رضی اللہ عنہا سے روایت ہے کہ سیدنا ابو سلمہ رضی اللہ عنہ نے فرمایا: \"جب تم میں سے کسی کو مصیبت پہنچے تو کہے: ہم اللہ کے لیے ہیں اور اسی کی طرف لوٹنے والے ہیں۔ اے اللہ! تجھ سے ہی میں اپنی مصیبت کے ثواب کی امید رکھتا ہوں، مجھے اس پر ثواب عطا فرما۔\" میں یہ کہنا چاہتی کہ مجھے اس کا بہتر بدلہ دے تو کہتی: ابو سلمہ سے بہتر کون ہو سکتا ہے؟ میں یہی دعا مانگتی رہی، پھر قصہ ذکر کیا۔ ابن سعد(3) کا قول ہے: ہمیں معمر نے بحوالہ زہری، انہوں نے ہند بنت حارث فراسیہ سے روایت کی، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ کا میرے نزدیک ایک مقام ہے جس تک کوئی اور نہیں پہنچ سکا۔\" جب آپ صلی اللہ علیہ وسلم نے سیدہ زینب رضی اللہ عنہا سے نکاح کیا تو لوگوں نے پوچھا: اس مقام کا کیا ہوا؟ تو انہوں نے جان لیا کہ سیدہ ام سلمہ رضی اللہ عنہا اس مقام تک پہنچ چکی ہیں۔ فرماتے ہیں: ہمیں محمد بن عمر نے بتایا، وہ فرماتے ہیں کہ ہمیں عبد الرحمن بن ابی زناد نے بحوالہ ہشام بن عروہ، انہوں نے اپنے والد سے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کی، جب رسول اللہ صلی اللہ علیہ وسلم نے سیدہ ام سلمہ رضی اللہ عنہا سے نکاح کیا، مجھے ان کے حسن و جمال کا پتہ چلا تو سخت غم ہوا۔ میں نے بہانے سے انہیں دیکھ لیا، اللہ کی قسم! جو مجھ سے ان کی خوبصورتی بیان ہوتی تھی، وہ اس سے زیادہ حسن و جمال والی تھیں۔ سیدہ حفصہ رضی اللہ عنہا نے فرمایا: اللہ کی قسم! یہ تو صرف غیرت ہے۔ سیدہ حفصہ رضی اللہ عنہا نے بھی انہیں بہانے سے دیکھ لیا اور مجھ سے کہا: نہیں، اللہ کی قسم! تم جیسی کہہ رہی تھی ویسی نہیں بلکہ اس سے زیادہ خوبصورت ہیں۔ میں نے انہیں بعد میں دیکھا، وہ ویسی ہی تھیں جو سیدہ حفصہ رضی اللہ عنہا نے بیان کیا۔ سیدہ ام سلمہ رضی اللہ عنہا نے نبی کریم صلی اللہ علیہ وسلم اور ابو سلمہ رضی اللہ عنہ سے بہت سی احادیث روایت کیں۔ ان سے ان کی اولاد عمر، زینب اور ان کے مکاتب نبہان، ان کے بھائی عامر بن ابی امیہ اور ان کے موالی عبد اللہ بن رافع، نافع، سفینہ، ابو کثیر اور سلیمان بن سیار نے روایت کیا۔ ان سے سیدنا ابن عباس رضی اللہ عنہما نے بھی روایت کیا اور سیدہ عائشہ، ابو سعید خدری، قبیصہ بن ذویب، نافع مولی ابن عمر، عبد الرحمن بن حارث بن ہشام اور دوسرے لوگوں نے حدیث روایت کی۔ واقدی(4) کا قول ہے: ۵۹ھ میں شوال کے مہینے میں وفات پائی۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے ان کی نماز جنازہ پڑھی، ان کی عمر چوراسی(۸۴) برس تھی، جیسا کہ قول ہے۔ ان سے ایک جماعت نے حدیث کی روایت لی، یہ قول جید نہیں، صحیح مسلم میں ثابت ہے کہ حارث بن عبد اللہ بن ابی ربیعہ اور عبد اللہ بن صفوان یزید بن معاویہ کے دور حکومت میں سیدہ ام سلمہ رضی اللہ عنہا کے پاس آئے اور ان سے اس لشکر کے بارے میں پوچھا جو زمین میں دھنسا دیا جائے گا۔۔۔۔ (الحدیث) یزید کی حکومت ان کے والد کی وفات کے بعد ۶۰ھ میں تھی۔ ابن حبان کا قول ہے: ۶۱ھ میں سیدنا حسین بن علی کی شہادت کی خبر آنے کے بعد وفات پائی۔ میں کہتا ہوں: یہ زیادہ صحیح ہے۔ محارب بن دثار کا قول ہے کہ سیدہ ام سلمہ رضی اللہ عنہا نے وصیت کی کہ ان کی نماز جنازہ سیدنا سعید بن زید رضی اللہ عنہ پڑھائیں، اس وقت مروان بن حکم مدینہ کے امیر تھے۔ بعض کا قول ہے: ولید بن عتبہ بن ابو سفیان۔ میں کہتا ہوں: دوسرا قول زیادہ صحیح ہے، کیونکہ سیدنا سعید بن زید رضی اللہ عنہ وہ تمام اقوال کے مطابق سیدہ ام سلمہ رضی اللہ عنہا سے قبل وفات پا گئے، ایسا معلوم ہوتا ہے کہ انہوں نے حالت مرض میں نماز جنازہ کی وصیت سیدنا سعید رضی اللہ عنہ کے لیے کی تھی۔ پھر وہ صحت یاب ہو گئیں اور سیدنا سعید رضی اللہ عنہ ان سے پہلے وفات پا گئے۔","",{"fn":"(1) نسب قریش (۳۰۰، ۳۱۵)\n(2) الآحاد والمثانی (الحدیث: ۴۲۴/۵)\n(3) الطبقات الکبریٰ (۲۶۶/۸)\n(4) مسند احمد (۳۱۳، ۳۰۷/۶) المعجم الکبیر (۴۹۹/۲۳، ۵۰۶، ۵۸۶) الآحاد والمثانی (۴۲۴/۵، ۱۷۶، ۲۲۲، ۲۶۰)"}],[11803,"§۱۱۸۴۲ ۔ ہند بنت الحصین\n(1)بن مطلب۔ ابن سعد(2) نے ان کا ذکر کیا ہے۔ ان کی بہن سیدہ خدیجہ رضی اللہ عنہا کے سوانح میں ان کا ذکر گزر چکا ہے۔","",{"fn":"(1) تجرید (۳۱۰/۲)\n(2) الطبقات الکبریٰ (۱۶۵/۸)"}],[11804,"§۱۱۸۴۳ ۔ ہند بنت الحکم\nبن ابی العاص بن امیہ، قسم ثالث میں ان کا ذکر آئے گا۔"],[11805,"§۱۱۸۴۴ ۔ ہند بنت ربیعہ\n(1)بن حارث بن عبد المطلب، جہان بن واسع کی زوجہ ہیں، یہ ابو عمر کا قول ہے، فرماتے ہیں: وہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پا گئے، تو ان کی ایک اور زوجہ انصاریہ تھیں، جسے انہوں نے دودھ پلانے کے دوران طلاق دے دی، پھر ان کی وفات ہو گئی۔ ایک برس گزر گیا اور انہیں حیض نہ آیا، دونوں اپنا معاملہ لے کر سیدنا عثمان رضی اللہ عنہ کے پاس گئیں، انہوں نے فیصلہ کیا کہ یہ خاتون ہند کے ساتھ میراث میں شریک ہوں گی، سیدہ ہند نے انہیں ملامت کی تو انہوں نے فرمایا: تمہارے چچا زاد علی کا اسی پر عمل ہے۔ میں کہتا ہوں: زبیر بن بکار نے موفقیات میں یہ قصہ ذکر کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۳۹) الاستيعاب (۳۵۶۶) تجرید (۳۱۰/۲)"}],[11806,"§۱۱۸۴۵ ۔ ہند بنت زیاد\nسہل بن سعد الساعدی کی زوجہ ہیں۔ زبیر بن بکار نے اخبار مدینہ میں اپنی سند کے ساتھ ان سے روایت کیا ہے کہ نبی کریم صلی اللہ علیہ وسلم سیدنا سہل بن سعد کے ہاں تشریف لے گئے اور گھر کے درمیان بیٹھے سیدنا سہل رضی اللہ عنہ نے اس جگہ کو نماز پڑھنے کی جگہ بنا لیا۔ فرماتی ہیں: جب میں سیدنا سہل رضی اللہ عنہ کے گھر گئی تو میں نے گھر کے درمیان میں نماز پڑھنے کی جگہ دیکھی۔"],[11807,"§۱۱۸۴۶ ۔ ہند بنت ابی سفیان\nبن حرب بن امیہ امویہ۔ سیدنا معاویہ رضی اللہ عنہ کی بہن ہیں، حارث بن نوفل بن عبد المطلب کی زوجہ تھیں، ان سے محمد پیدا ہوئے، یہ ابن سعد کا قول ہے، اور یہ اضافہ کیا: عبد اللہ، ربیعہ، عبد الرحمن، ولد اور ام زبیر فرماتے ہیں: ان کی والدہ صفیہ بنت ابو عمر بن امیہ ہیں۔"],[11808,"§۱۱۸۴۷ ۔ ہند بن ابی سفیان\nبعض کا قول ہے کہ وہ سیدہ حبیبہ رضی اللہ عنہا ام حبیبہ ہیں، ان کا نام ہے۔ معروف یہ ہے کہ ان کا نام زملہ ہے جسا کہ گزر چکا ہے۔"],[11809,"§۱۱۸۴۸ ۔ ہند بنت سماک\n(1)بن ثعلبہ بن امری القیس بن زید بن عبد الاشہل انصاریہ، اسید بن حضیر کی چھوٹی بہن ہیں۔ ابن حبیب(2) کا قول ہے: سعد بن معاذ کی زوجہ ہیں، عمر اور عبد اللہ کی والدہ ہیں۔ عدی(3) کا قول ہے: حارث بن اوس بن معاذ بن والدہ ہیں، بیعت کرنے والی صحابیات میں ہیں۔ ابن سعد(4) کا قول ہے: ان کی والدہ جناب خندب بنت رفاعہ بن زبیر بن زید بن مالک اوسیہ ہیں، ہند، اسید بن حضیر بن سماک کی چھوٹی بہن ہیں۔ پہلے وہ اوس بن معاذ کی زوجہ تھیں، جس سے حارث بن اسلم پیدا ہوئے، وہ غزوہ بدر میں شہید ہوئے۔ اس کے بعد ان کے بھائی سعد بن معاذ سے نکاح ہوا، جن سے عبد اللہ اور عمر کی ولادت ہوئی، اسلام لائیں اور بیعت کی۔","",{"fn":"(1) اسد الغابہ (۷۳۴۰) تجرید (۳۱۰/۲)\n(2) الطبقات الکبریٰ (۱۷۴/۸)\n(3) اسد الغابہ (۴۱۵/۵)\n(4) الطبقات الکبریٰ (۲۳۲/۸)"}],[11810,"§۱۱۸۴۹ ۔ ہند بنت سہل الجہنیہ\nبعض کا قول ہے: معاذ بن جبل کی والدہ ہیں۔ یہ ابن سعد کا قول ہے: سیدہ ام عطیہ رضی اللہ عنہا کی صحیح حدیث نوحہ کی ممانعت کے بارے میں ہے، اس میں ہے: پانچ عورتوں نے اس عہد کو پورا نہ کیا، ان میں سے ایک ام معاذ ہیں۔"],[11811,"§۱۱۸۵۰ ۔ ہند بنت سہل\n(1)بن عمر بن جشم انصاریہ، شمیہ، اسلام لائیں اور بیعت کی۔ یہ واقدی(2) نے ابن سعد کے قول سے نقل کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۴۱) الاستيعاب (۳۵۶۷) تجرید (۳۱۰/۲)\n(2) تجرید (۳۱۰/۲)"}],[11812,"§۱۱۸۵۱ ۔ ہند بنت ابی طالب\n(1)بن عبد المطلب، بعض کا قول ہے: یہ سیدہ ام ہانی کا نام ہے، جو اپنی کنیت سے مشہور ہیں، بعض کا قول ہے: ان کا نام عاتکہ ہے اور مشہور یہ ہے کہ \"فاختہ\" ہے، یہ ابن اسحاق(2) کا قول ہے۔ جو یونس بن بکیر وغیرہ کی ان سے روایت میں منقول ہے، جو فتح مکہ کے قصے میں ہے۔ رہا ابن ابی ہبیرہ بن ابی وہب مخزومی، سیدہ ام ہانی خاوند تھا اور نجران میں حالت کفر میں میرا، جب اسے سیدہ ام ہانی رضی اللہ عنہا کے اسلام لانے کی خبر ملی تو کہا: \"ہند کیا تمہیں اس کا شوق ہو گیا تھا، یا تمہارے پاس اس کا سوال آیا، گٹھلیوں کے ایسے ہی اسباب اور بکھیر ہوتی ہے۔ مضبوط قلعے کی چوٹی میں جو نجران میں ہے، بے چینی کی لہر دوڑ گئی۔\"","",{"fn":"(1) اسد الغابہ (۷۳۴۲) الاستيعاب (۳۵۶۸) تجرید (۳۱۰/۲)\n(2) السیرۃ النبویۃ (۴۹/۴)"}],[11813,"§۱۱۸۵۲ ۔ ہند بنت عتبہ\nبن ربیعہ بن عبد شمس بن عبد مناف قرشیہ، سیدنا معاویہ بن ابو سفیان کی والدہ ہیں ان کے اسلام سے پہلے کے حالات مشہور ہیں کہ غزوہ احد میں شریک تھیں، انہوں نے سیدنا حمزہ رضی اللہ عنہ کی شہادت کے بعد ان کا مثلہ کیا، مسلمانوں کے بہت خلافت تھیں، یہاں تک کہ اللہ تعالیٰ نے فتح مکہ کی نعمت سے نوازا تو ان کے شوہر اسلام لائے پھر فتح کے دن یہ بھی اسلام لائیں، خواتین کی بیعت میں ان کا قول مروی ہے جب آپ صلی اللہ علیہ وسلم نے فرمایا: \"نہ وہ چوری کریں گی نہ زنا کریں گی\"۔ انہوں نے کہا: کیا آزاد عورت زنا کر سکتی ہے، اور جب آپ صلی اللہ علیہ وسلم نے فرمایا: \"اپنی اولادوں کو قتل نہ کریں گی\"۔ تو انہوں نے کہا: ہم نے ان کے بچپن میں ان کی پرورش کی اور بڑے ہونے پر آپ نے انہیں قتل کیا، ان کا یہ قول مشہور ہے۔ ابن سعد(1) نے اپنے طرق سے صحیح سند کے ساتھ بحوالہ شعبی(2)، انہوں نے میمون بن مہران سے مرسل حدیث روایت کی ہے۔ وہ زنا نہیں کریں گے۔ تو ہند نے کہا: کیا آزاد عورت زنا کر سکتی ہے؟ اور تم اپنی اولادوں کو قتل نہیں کرو گی۔ تو انہوں نے کہا: آپ نے انہیں قتل کیا ہے۔ ایک روایت میں ہے لیکن انہوں نے کہا: کیا آپ نے بدر کے دن ہماری اولاد کو چھوڑا ہے۔ انہوں نے اپنے خاوند کے مال میں سے بغیر اجازت کے کچھ مال لینے کے بارے میں سوال کیا جو کفایت کرے کہ اس میں انہیں گناہ ہوگا، یہ حدیث صحیحین میں ہے، اس میں ہے: \"ان کے مال میں سے معروف طریقے سے لو جو تمہیں اور تمہاری اولاد کو کافی ہے\"۔ یہ ہشام بن عروہ کی بحوالہ ان کے والد روایت ہے، انہوں نے سیدہ عائشہ رضی اللہ عنہا سے روایت کیا ہے۔ عبداللہ بن محمد بن عروہ نے شاذ روایت نقل کی ہے۔ فرماتے ہیں: بحوالہ ہشام، انہوں نے اپنے والد سے، انہوں نے ہند سے روایت کی ہے۔ اسے ابن مندہ نے نقل کیا ہے۔ اس کے شروع میں ہے: ہند نے کہا: میں محمد سے بیعت کرنا چاہتی ہوں، انہوں نے کہا: میں نے تمہیں کفر کرتے دیکھا ہے، انہوں نے کہا: اللہ کی قسم! اس مسجد میں، اس رات سے قبل میں نے کسی کو اللہ تعالیٰ کی عبادت کا حق ادا کرتے نہیں دیکھا۔ اللہ کی قسم! انہوں نے نماز میں قیام، رکوع اور سجدہ کرتے ہوئے رات گزاری، انہوں نے کہا: تم سے جو ہوا سو ہوا۔ اپنے قبیلے کے ایک آدمی کے ساتھ جاؤ۔ وہ سیدنا عمر رضی اللہ عنہ کی طرف گئیں، انہیں ساتھ لیا، انہوں نے ان کے لیے اجازت طلب کی، پھر وہ نقاب کئے ہوئے اندر گئیں، پھر بیعت کا قصہ بیان کیا، اس میں وہی الفاظ ہیں جو گزر چکے ہیں، اس میں ان کا یہ قول ہے: ابو سفیان بخیل آدمی ہے، مجھے اتنا خرچ نہیں دیتے جو مجھے کافی ہو، اور میں ان کو بتائے بغیر ان کے مال میں سے لے لیتی ہوں۔۔۔۔ (الحدیث) اس روایت میں ہے، جو شعبی روایت سے مرسل مروی ہے، سیدہ ہند رضی اللہ عنہا نے فرمایا: میں نے ابو سفیان کے مال میں سے خرچ کیا ہے تو سیدنا ابو سفیان رضی اللہ عنہ نے فرمایا: تم نے میرے مال سے جو لیا ہے وہ حلال ہے۔ ابن سعد کا قول ہے، واقدی نے کہا: جب سیدہ ہند رضی اللہ عنہا اسلام لائیں تو کلہاڑے سے اپنے گھر میں موجود بت کو مارنے لگیں، یہاں تک کہ اسے ٹکڑے ٹکڑے کر دیا اور کہنے لگیں: ہم تمہارے بارے میں دھوکے میں تھے۔ ابو عمر کا قول ہے: ایک قول کے مطابق سیدنا ابو بکر رضی اللہ عنہ کے تھوڑے عرصہ بعد سیدنا عمر رضی اللہ عنہ کی خلافت میں وفات پائی سیدنا ابو قحافہ کی وفات کے دن فوت ہوئیں، صاحب الامثال کی روایت سے پتہ چلتا ہے کہ وہ سیدنا عثمان رضی اللہ عنہ کی خلافت کے بعد بھی زندہ رہیں، کیونکہ بلا اختلاف سیدنا ابو سفیان رضی اللہ عنہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پاگئے، فرماتے ہیں: ایک شخص نے سیدنا معاویہ رضی اللہ عنہ سے کہا: ہند کا مجھ سے نکاح کر دیجئے۔ انہوں نے کہا: وہ اولاد سے نامید ہوگئی ہیں۔ اور انہیں شادی کی حاجت نہیں، اس نے کہا: پھر مجھے فلاں علاقے کی حکومت دے دیں، سیدنا معاویہ رضی اللہ عنہ نے شعر پڑھا: \"اس نے ایسی چیز کو طلب کیا جسے وہ حاصل نہیں کر سکتا، جب اس سے عاجز ہو گیا تو ایسی چیز کو طلب کیا جو اس سے بھی بعید ہے۔\" میں نے طبقات ابن سعد میں اعتماد کے ساتھ لکھا ہوا پایا کہ وہ سیدنا عثمان رضی اللہ عنہ کی خلافت میں وفات پاگئیں۔","",{"fn":"(1) الطبقات الکبریٰ (۱۷۰/۸)\n(2) سورۃ الممتحنہ (۱۲)"}],[11814,"§۱۱۸۵۳ ۔ ہند بنت عتیق\nبن عائذ بن عبداللہ بن عمر بن مخزوم، ان کی والدہ خدیجہ نبی کریم صلی اللہ علیہ وسلم کی زوجہ تھیں۔ دارقطنی نے کتاب الاخوۃ میں ان کا ذکر کیا ہے، اور فرمایا: اسلام لائیں اور نکاح کیا۔ آپ صلی اللہ علیہ وسلم سے کوئی حدیث روایت نہیں کی۔ ابن سعد رحمہ اللہ نے سیدہ خدیجہ رضی اللہ عنہا کے سوانح میں لکھا ہے: سیدہ خدیجہ رضی اللہ عنہا کا ابوہالہ کے بعد عتیق بن عائذ بن عبداللہ بن عمر بن مخزوم سے نکاح ہوا، جس سے ایک لڑکی جسے کہا جاتا تھا، پیدا ہوئی، ان سے صیفی بن امیہ بن عائذ بن عبداللہ بن عمر بن مخزوم جو ان کا چچا زاد تھا، نکاح کیا۔ اس سے محمد بن صیفی پیدا ہوئے۔ محمد کی اولاد کو سیدہ خدیجہ رضی اللہ عنہا کی وجہ سے بنو طاہرہ کہا جاتا تھا۔"],[11815,"§۱۱۸۵۴ ۔ ہند بنت عقبہ\nبن ابی معیط امویہ، ولید کی بہن ہیں۔ پہلے گزر چکا ہے کہ ان کے والد بدر میں قتل ہوئے اور ان کی والدہ ارویٰ بنت کریز اور دونوں بھائی ولید اور خالد فتح کے دن اسلام لائے۔"],[11816,"§۱۱۸۵۵ ۔ ہند بنت عمرو بن الجموح\nانصاریہ، ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن سعد نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔"],[11817,"§۱۱۸۵۶ ۔ ہند بنت عمرو\n(1) بن حرام انصاریہ، سیدنا جابر بن عبداللہ کی پھوپھی ہیں، جو مشہور صحابی ہیں۔ ان کے والد کے سوانح میں ان کا نسب گزر چکا ہے۔ ابن مندہ کا قول ہے: واقدی رحمہ اللہ نے ان کی حدیث ایوب بن نعمان سے بحوالہ اپنے والد اور انہوں نے ان سے روایت کیا ہے۔(2) میں کہتا ہوں: امالی المحاملی میں ہم نے اسے روایت کیا ہے۔","",{"fn":"(1) اسد الغابہ (۷۳۴۳) الاستيعاب (۳۵۶۹) تجرید (۳۱۰/۲)\n(2) اسد الغابہ (۴۱۷/۵) الطبقات الکبریٰ (۲۸۷/۸)"}],[11818,"§۱۱۸۵۷ ۔ ہند بنت محمود\n(1) بن سلمہ بن خالد بن عدی انصاریہ، ابن سعد رحمہ اللہ(2) اور ابن حبیب(3) نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔ ابن سعد رحمہ اللہ کا قول ہے: ان کی والدہ شموس بنت عمرو بن حرام بن ثعلبہ سلمیہ ہیں، ان سے عمر بن سعد بن معاذ اشہلی نے نکاح کیا۔","",{"fn":"(1) اسد الغابہ (۷۳۴۴)\n(2) الطبقات الکبریٰ (۲۴۳/۸)\n(3) اسد الغابہ (۴۱۷/۵)"}],[11819,"§۱۱۸۵۸ ۔ ہند بنت المقوم\n(1) بن عبدالمطلب بن ہاشم، ابن سعد رحمہ اللہ نے ان کا ذکر کیا ہے۔ ابوعمرہ انصاری نے ان سے نکاح کیا، جس سے عبدالرحمن اور عبداللہ پیدا ہوئے، فرماتے ہیں: ان کی والدہ قلابہ بنت عمرو بن جحونہ تیمیہ ہیں۔","",{"fn":"(1) تجرید (۳۱۱/۲)"}],[11820,"§۱۱۸۵۹ ۔ ہند بنت منبہ\n(1) بن حجاج سہمیہ، سیدنا عبداللہ بن عمرو کی والدہ ہیں اور فتح کے دن اسلام لائیں۔ واقدی رحمہ اللہ نے ان کا ذکر کیا ہے، ابن دباغ نے بحوالہ ابوعلی جیانی اپنے استدراک میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۳۴۵) تجرید (۳۱۱/۲)\n(2) اسد الغابہ (۴۱۷/۵)"}],[11821,"§۱۱۸۶۰ ۔ ہند بنت المنذر\n(1) بن جموح بن زید بن منذر انصاریہ، بنو ساعدہ سے ہیں۔ ابن حبیب نے بیعت کرنے والی صحابیات میں ان کا ذکر کیا ہے۔(2)","",{"fn":"(1) اسد الغابہ (۷۳۴۶) تجرید (۳۱۱/۲)\n(2) الطبقات الکبریٰ (۲۸۹/۸)"}],[11822,"§۱۱۸۶۱ ۔ ہند بنت کبیرہ\n(1) میں نے حدیث ثوبان میں ذکر کیا ہے، جسے نسائی(2) نے ابوسلام حبشی کے طریق سے بحوالہ ابواسماء رحبی نقل کیا ہے کہ ثوبان مولیٰ رسول اللہ صلی اللہ علیہ وسلم بیان کرتے ہیں کہ ہند بنت ہبیرہ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئیں اور ان کے ہاتھ میں سونے کی انگوٹھی تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کے ہاتھ پر مارا تو وہ سیدہ فاطمہ رضی اللہ عنہا کے پاس اس کی شکایت لے گئیں۔۔۔۔۔ (الحدیث) اس میں یہ قول بھی ہے: \"تمام تعریف اللہ کے لیے ہے، جس نے فاطمہ کو آگ سے نجات دی\"۔ ابن اثیر(3) کا قول ہے: ابوموسیٰ نے ان کا ذکر کیا ہے۔ میں کہتا ہوں: جو نسخہ مجھے ملا ہے اس میں صریفینی کے قلم سے نہیں لکھا۔","",{"fn":"(1) اسد الغابہ (۷۳۴۷) تجرید (۳۱۱/۲)\n(2) نسائی (۵۱۵۵)\n(3) اسد الغابہ (۴۱۷/۵)"}]])